68	/******************************************************************************
69	function:	SPI write byte (bit-bang)
70	parameter:
71	Info:
72	******************************************************************************/
73	void DEV_SPI_WriteByte(UBYTE data)
74	{
75	    DEV_Digital_Write(EPD_CS_PIN, 0);
76	
77	    for (int i = 0; i < 8; i++)
78	    {
79	        if ((data & 0x80) == 0)
80	            DEV_Digital_Write(EPD_MOSI_PIN, 0);
81	        else
82	            DEV_Digital_Write(EPD_MOSI_PIN, 1);
83	
84	        data <<= 1;
85	        DEV_Digital_Write(EPD_SCK_PIN, 1);
86	        DEV_Digital_Write(EPD_SCK_PIN, 0);
87	    }
88	
89	    DEV_Digital_Write(EPD_CS_PIN, 1);
90	}
91	
92	/******************************************************************************
93	function:	SPI read byte (bit-bang)
94	parameter:
95	Info:
96	******************************************************************************/
97	UBYTE DEV_SPI_ReadByte(void)
98	{
99	    UBYTE j = 0xff;
100	
101	    // Switch MOSI to input
102	    gpio_set_direction((gpio_num_t)EPD_MOSI_PIN, GPIO_MODE_INPUT);
103	
104	    DEV_Digital_Write(EPD_CS_PIN, 0);
105	    for (int i = 0; i < 8; i++)
106	    {
107	        j = j << 1;
108	        if (DEV_Digital_Read(EPD_MOSI_PIN))
109	            j = j | 0x01;
110	        else
111	            j = j & 0xfe;
112	
113	        DEV_Digital_Write(EPD_SCK_PIN, 1);
114	        DEV_Digital_Write(EPD_SCK_PIN, 0);
115	    }
116	    DEV_Digital_Write(EPD_CS_PIN, 1);
117	
118	    // Switch MOSI back to output
119	    gpio_set_direction((gpio_num_t)EPD_MOSI_PIN, GPIO_MODE_OUTPUT);
120	
121	    return j;
122	}
