292	/******************************************************************************
293	function :	Clear screen
294	parameter:
295	******************************************************************************/
296	void EPD_3IN5G_V2_Clear(UBYTE color)
297	{
298	    UWORD Width, Height;
299	    Width = (EPD_3IN5G_V2_WIDTH % 4 == 0)? (EPD_3IN5G_V2_WIDTH / 4 ): (EPD_3IN5G_V2_WIDTH / 4 + 1);
300	    Height = EPD_3IN5G_V2_HEIGHT;
301	
302	    EPD_3IN5G_V2_SendCommand(0x10);
303	    for (UWORD j = 0; j < Height; j++) {
304	        for (UWORD i = 0; i < Width; i++) {
305	            EPD_3IN5G_V2_SendData((color << 6) | (color << 4) | (color << 2) | color);
306	        }
307	    }
308	
309	    EPD_3IN5G_V2_TurnOnDisplay();
310	}
