312	/******************************************************************************
313	function :	Sends the image buffer in RAM to e-Paper and displays
314	parameter:
315	******************************************************************************/
316	void EPD_3IN5G_V2_Display(const UBYTE *Image)
317	{
318	    UWORD Width, Height;
319	    Width = (EPD_3IN5G_V2_WIDTH % 4 == 0)? (EPD_3IN5G_V2_WIDTH / 4 ): (EPD_3IN5G_V2_WIDTH / 4 + 1);
320	    Height = EPD_3IN5G_V2_HEIGHT;
321	
322	    EPD_3IN5G_V2_SendCommand(0x10);
323	    for (UWORD j = 0; j < Height; j++) {
324	        for (UWORD i = 0; i < Width; i++) {
325	            EPD_3IN5G_V2_SendData(Image[i + j * Width]);
326	        }
327	    }
328	
329	    EPD_3IN5G_V2_TurnOnDisplay();
330	}
