332	/******************************************************************************
333	function :	Enter sleep mode
334	parameter:
335	******************************************************************************/
336	void EPD_3IN5G_V2_Sleep(void)
337	{
338	    EPD_3IN5G_V2_SendCommand(0x02); // POWER_OFF
339	    EPD_3IN5G_V2_SendData(0X00);
340	    EPD_3IN5G_V2_ReadBusyH();
341	    EPD_3IN5G_V2_SendCommand(0x07); // DEEP_SLEEP
342	    EPD_3IN5G_V2_SendData(0XA5);
343	}
