/*
 * epd_protocol.cpp - 协议接收状态机，收满图片帧后送墨水屏显示。
 *
 * 复用 UART0（console 串口），收图期间不应有其它 console 输出干扰 RX。
 * 接收任务：等帧头 → 读 CMD/LEN → 收满 PAYLOAD → 校验 CRC16 → 显示。
 */
#include "epd_protocol.h"
#include "DEV_Config.h"
#include "EPD_3in5g_V2.h"

#include <string.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/uart.h"
#include "esp_log.h"
#include "esp_timer.h"

static const char *TAG = "epd_proto";

#define RX_BUF_SIZE 4096
#define RX_TIMEOUT_MS 200

/* CRC-16/MODBUS，与 tools/img2epd.py 的 crc16() 对齐。*/
static uint16_t crc16_modbus(const uint8_t *data, size_t len)
{
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x0001) crc = (crc >> 1) ^ 0xA001;
            else              crc >>= 1;
        }
    }
    return crc & 0xFFFF;
}

/* 从 UART 读 N 字节，超时则失败。返回实际读取字节数。*/
static int read_n(uint8_t *buf, size_t want, int uart_port)
{
    size_t got = 0;
    int64_t deadline = esp_timer_get_time() + (int64_t)RX_TIMEOUT_MS * 1000;
    while (got < want) {
        int n = uart_read_bytes(uart_port, buf + got, want - got,
                                pdMS_TO_TICKS(50));
        if (n > 0) got += n;
        if (esp_timer_get_time() > deadline) break;
    }
    return got;
}

static void rx_task(void *arg)
{
    /* 收图缓冲放 PSRAM（17664B 不算大，但养成习惯）*/
    uint8_t *payload = (uint8_t *)heap_caps_malloc(EPD_IMAGE_SIZE,
                                                   MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (!payload) {
        /* PSRAM 没开就退回内部 RAM（17664B 内部也够）*/
        payload = (uint8_t *)malloc(EPD_IMAGE_SIZE);
    }
    assert(payload);

    const int uart_port = UART_NUM_0;
    /* 复用 console UART0：装驱动后，console 的 printf 仍能 TX，
     * 但 RX 由本驱动接管。uart_driver_install 已被 console 装过的话会报 EBUSY，
     * 这里尝试装一次，失败就用现成的（IDF console 不占 RX 缓冲）。*/
    uart_config_t cfg = {
        .baud_rate = 115200,
        .data_bits = UART_DATA_8_BITS,
        .parity    = UART_PARITY_DISABLE,
        .stop_bits = UART_STOP_BITS_1,
        .flow_ctrl = UART_HW_FLOWCTRL_DISABLE,
        .source_clk = UART_SCLK_DEFAULT,
    };
    /* 若 console 已安装驱动，这里返回 EBUSY，可忽略——继续用其 RX。*/
    uart_driver_install(uart_port, RX_BUF_SIZE, 0, 0, NULL, 0);
    uart_param_config(uart_port, &cfg);

    ESP_LOGI(TAG, "接收任务启动，等帧头 0xA5 0x5A ...");

    while (1) {
        /* 状态机：等帧头 0xA5 0x5A */
        uint8_t head[2];
        /* 逐字节扫，遇到 0xA5 再看下一个是不是 0x5A */
        int n = uart_read_bytes(uart_port, head, 1, portMAX_DELAY);
        if (n <= 0) continue;
        if (head[0] != EPD_FRAME_HEAD0) continue;
        n = read_n(&head[1], 1, uart_port);
        if (n != 1 || head[1] != EPD_FRAME_HEAD1) continue;

        /* 读 CMD(1) + LEN(4) */
        uint8_t cmd_len[5];
        if (read_n(cmd_len, 5, uart_port) != 5) {
            ESP_LOGW(TAG, "CMD/LEN 超时");
            continue;
        }
        uint8_t cmd = cmd_len[0];
        uint32_t len = cmd_len[1] | (cmd_len[2] << 8) |
                       (cmd_len[3] << 16) | (cmd_len[4] << 24);
        if (len != EPD_IMAGE_SIZE) {
            ESP_LOGW(TAG, "LEN=%u 不符预期 %u，丢帧", len, EPD_IMAGE_SIZE);
            /* 不消费 PAYLOAD 会让后续错位，最简单：等下一帧头 */
            continue;
        }

        /* 收满 PAYLOAD */
        if (read_n(payload, len, uart_port) != len) {
            ESP_LOGW(TAG, "PAYLOAD 超时，丢帧");
            continue;
        }

        /* 校验 CRC16 */
        uint8_t crc_bytes[2];
        if (read_n(crc_bytes, 2, uart_port) != 2) {
            ESP_LOGW(TAG, "CRC 超时");
            continue;
        }
        uint16_t crc_recv = crc_bytes[0] | (crc_bytes[1] << 8);
        uint16_t crc_calc = crc16_modbus(payload, len);
        if (crc_recv != crc_calc) {
            ESP_LOGW(TAG, "CRC 错 收=%04X 算=%04X", crc_recv, crc_calc);
            continue;
        }

        /* 按 CMD 分发 */
        if (cmd == EPD_CMD_IMAGE) {
            ESP_LOGI(TAG, "收到图片帧 %uB，初始化并显示", len);
            EPD_3IN5G_V2_Init();
            EPD_3IN5G_V2_Display(payload);
            ESP_LOGI(TAG, "显示完成");
        } else {
            ESP_LOGW(TAG, "未知 CMD=0x%02X", cmd);
        }
    }
    free(payload);
    vTaskDelete(NULL);
}

int epd_protocol_start(uint32_t baudrate)
{
    (void)baudrate;  /* 复用 console UART0，固定 115200 */
    BaseType_t ok = xTaskCreate(rx_task, "epd_rx", 6144, NULL, 5, NULL);
    return ok == pdPASS ? 0 : -1;
}

