#include "freertos/task.h"
#include "DEV_Config.h"
#include "EPD_3in5g_V2.h"
#include "epd_protocol.h"

extern "C" void app_main(void)
{
    // Initialize hardware (墨水屏 GPIO)
    DEV_Module_Init();

    // 先刷一次白屏，确认屏幕连接正常
    EPD_3IN5G_V2_Init();
    EPD_3IN5G_V2_Clear(EPD_3IN5G_V2_WHITE);

    // 启动串口协议接收任务，等电脑/手机发图
    epd_protocol_start(115200);

    // app_main 返回后 IDF 会删 main_task，但接收任务会持续运行
    printf("epd_3in5g ready, waiting for image frames on UART0...\n");
}

