const uart_port_t uart_port = UART_NUM_1;
/* 用独立 UART1 收图，避免和 console UART0 抢 RX。
 * 引脚：RX=GPIO9, TX=GPIO10（安全区，不碰墨水屏 6/7/8/20/21/22）。
 * 接线：USB-TTL 的 TX → P4 GPIO9(RX)，USB-TTL 的 RX → P4 GPIO10(TX)。*/
uart_config_t cfg;
memset(&cfg, 0, sizeof(cfg));
cfg.baud_rate = 115200;
cfg.data_bits = UART_DATA_8_BITS;
cfg.parity    = UART_PARITY_DISABLE;
cfg.stop_bits = UART_STOP_BITS_1;
cfg.flow_ctrl = UART_HW_FLOWCTRL_DISABLE;
cfg.source_clk = UART_SCLK_DEFAULT;
uart_driver_install(uart_port, RX_BUF_SIZE, 0, 0, NULL, 0);
uart_param_config(uart_port, &cfg);
uart_set_pin(uart_port, 10, 9, UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE);

