#ifndef CAMERA_CAPTURE_H
#define CAMERA_CAPTURE_H

#include <stdint.h>
#include <stddef.h>
#include "esp_err.h"
#include "esp_ldo_regulator.h"
#include "driver/isp.h"
#include "esp_cam_ctlr.h"
#include "esp_cam_ctlr_csi.h"
#include "example_sensor_init.h"

#ifdef __cplusplus
extern "C" {
#endif

/* SC2336 配置：800x640 RGB565，MIPI 2-lane */
#define CAM_HRES              800
#define CAM_VRES              640
#define CAM_BPP               16
#define CAM_FB_SIZE           (CAM_HRES * CAM_VRES * (CAM_BPP / 8))  /* 1024000 = 1MB */

#define CAM_SCCB_SDA          7
#define CAM_SCCB_SCL          8
#define CAM_LDO_CHAN          3
#define CAM_LDO_MV            2500
#define CAM_LANE_BITRATE_MBPS 200
#define CAM_FORMAT_NAME       "MIPI_2lane_24Minput_RAW8_800x640_50fps"

typedef struct {
    esp_ldo_channel_handle_t ldo;
    example_sensor_handle_t  sensor;
    esp_cam_ctlr_handle_t    csi;
    isp_proc_handle_t        isp;
    void                    *frame_buffer;   /* 1MB PSRAM cache-aligned */
    size_t                   frame_buffer_size;
    esp_cam_ctlr_trans_t     trans;          /* 复用给 receive */
} cam_capture_t;

/* 初始化：LDO→I2C+sensor→CSI new+enable→ISP new+enable→CSI start。
 * 返回 ESP_OK 成功。失败时部分资源已分配，仍应调 deinit 清理。*/
esp_err_t cam_capture_init(cam_capture_t *cam);

/* 抓一帧 RGB565 到 cam->frame_buffer。
 * 返回 ESP_OK 成功，*out_fb 指向帧数据，*out_len 为字节数。
 * 数据在 PSRAM，调用方用完前不要调下一次 capture。*/
esp_err_t cam_capture_one_frame(cam_capture_t *cam, uint8_t **out_fb, size_t *out_len);

/* 反序释放所有资源。*/
esp_err_t cam_capture_deinit(cam_capture_t *cam);

#ifdef __cplusplus
}
#endif

#endif /* CAMERA_CAPTURE_H */

/*
 * camera_capture.cpp - SC2336 MIPI 摄像头拍照
 *
 * 初始化序列严格遵循 components/esp_driver_cam/test_apps/csi/main/test_csi_ov5647.c
 * （无 DSI 屏的 CSI+ISP 黄金参考）：
 *   LDO acquire → I2C+sensor_init → CSI new+callbacks+enable → ISP new+enable → CSI start
 */
#include "camera_capture.h"
#include <string.h>
#include "esp_log.h"
#include "esp_private/esp_cache_private.h"
#include "esp_heap_caps.h"

static const char *TAG = "cam";

/* 帧回调（静态函数，C++ 文件里不能用 lambda 注册给 C 回调表）*/
static bool IRAM_ATTR s_get_new_vb(esp_cam_ctlr_handle_t handle, esp_cam_ctlr_trans_t *trans, void *user_data)
{
    esp_cam_ctlr_trans_t *src = (esp_cam_ctlr_trans_t *)user_data;
    trans->buffer = src->buffer;
    trans->buflen = src->buflen;
    return false;
}

static bool IRAM_ATTR s_trans_finished(esp_cam_ctlr_handle_t handle, esp_cam_ctlr_trans_t *trans, void *user_data)
{
    return false;
}

esp_err_t cam_capture_init(cam_capture_t *cam)
{
    esp_err_t ret = ESP_FAIL;
    memset(cam, 0, sizeof(*cam));
    cam->frame_buffer_size = CAM_FB_SIZE;

    /* 1. LDO 上电（MIPI PHY 供电，必须最先）*/
    esp_ldo_channel_config_t ldo_cfg = {
        .chan_id = CAM_LDO_CHAN,
        .voltage_mv = CAM_LDO_MV,
    };
    ret = esp_ldo_acquire_channel(&ldo_cfg, &cam->ldo);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "LDO acquire fail[%d]", ret);
        return ret;
    }

    /* 2. 帧缓冲：PSRAM cache 对齐分配（CSI DMA 要求）*/
    size_t align = 0;
    esp_cache_get_alignment(0, &align);
    cam->frame_buffer = heap_caps_aligned_calloc(align, 1, CAM_FB_SIZE,
                                                 MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (!cam->frame_buffer) {
        ESP_LOGE(TAG, "frame_buffer alloc fail");
        return ESP_ERR_NO_MEM;
    }
    cam->trans.buffer = cam->frame_buffer;
    cam->trans.buflen = CAM_FB_SIZE;

    /* 3. I2C + sensor 探测（SC2336）*/
    example_sensor_config_t sensor_cfg = {
        .i2c_port_num = I2C_NUM_0,
        .i2c_sda_io_num = CAM_SCCB_SDA,
        .i2c_scl_io_num = CAM_SCCB_SCL,
        .reset_pin = -1,
        .pwdn_pin = -1,
        .xclk_pin = -1,
        .port = ESP_CAM_SENSOR_MIPI_CSI,
        .format_name = CAM_FORMAT_NAME,
    };
    example_sensor_init(&sensor_cfg, &cam->sensor);
    /* example_sensor_init 失败只打日志不返回错误码，检查句柄 */
    if (cam->sensor.sccb_handle == NULL) {
        ESP_LOGE(TAG, "sensor 探测失败，检查 FPC/LDO/I2C(SDA%d/SCL%d)",
                 CAM_SCCB_SDA, CAM_SCCB_SCL);
        return ESP_ERR_NOT_FOUND;
    }
    ESP_LOGI(TAG, "SC2336 探测成功");

    /* 4. CSI 控制器（input RAW8, output RAW8 交给 ISP 做 demaic）*/
    esp_cam_ctlr_csi_config_t csi_cfg;
    memset(&csi_cfg, 0, sizeof(csi_cfg));
    csi_cfg.ctlr_id = 0;
    csi_cfg.h_res = CAM_HRES;
    csi_cfg.v_res = CAM_VRES;
    csi_cfg.lane_bit_rate_mbps = CAM_LANE_BITRATE_MBPS;
    csi_cfg.input_data_color_type = CAM_CTLR_COLOR_RAW8;
    csi_cfg.output_data_color_type = CAM_CTLR_COLOR_RAW8;
    csi_cfg.data_lane_num = 2;
    csi_cfg.byte_swap_en = false;
    csi_cfg.queue_items = 1;
    ret = esp_cam_new_csi_ctlr(&csi_cfg, &cam->csi);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "CSI new fail[%d]", ret);
        return ret;
    }

    esp_cam_ctlr_evt_cbs_t cbs = {
        .on_get_new_trans = s_get_new_vb,
        .on_trans_finished = s_trans_finished,
    };
    ret = esp_cam_ctlr_register_event_callbacks(cam->csi, &cbs, &cam->trans);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "CSI callback fail[%d]", ret);
        return ret;
    }
    ret = esp_cam_ctlr_enable(cam->csi);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "CSI enable fail[%d]", ret);
        return ret;
    }

    /* 5. ISP（RAW8→RGB565，做 demaic）*/
    esp_isp_processor_cfg_t isp_cfg;
    memset(&isp_cfg, 0, sizeof(isp_cfg));
    isp_cfg.clk_hz = 80 * 1000 * 1000;
    isp_cfg.input_data_source = ISP_INPUT_DATA_SOURCE_CSI;
    isp_cfg.input_data_color_type = ISP_COLOR_RAW8;
    isp_cfg.output_data_color_type = ISP_COLOR_RGB565;
    isp_cfg.has_line_start_packet = false;
    isp_cfg.has_line_end_packet = false;
    isp_cfg.h_res = CAM_HRES;
    isp_cfg.v_res = CAM_VRES;
    ret = esp_isp_new_processor(&isp_cfg, &cam->isp);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "ISP new fail[%d]", ret);
        return ret;
    }
    ret = esp_isp_enable(cam->isp);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "ISP enable fail[%d]", ret);
        return ret;
    }

    /* 6. 最后才 start CSI */
    ret = esp_cam_ctlr_start(cam->csi);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "CSI start fail[%d]", ret);
        return ret;
    }

    ESP_LOGI(TAG, "摄像头初始化完成 %dx%d RGB565", CAM_HRES, CAM_VRES);
    return ESP_OK;
}

esp_err_t cam_capture_one_frame(cam_capture_t *cam, uint8_t **out_fb, size_t *out_len)
{
    if (!cam || !cam->csi) return ESP_ERR_INVALID_STATE;

    /* 收一帧（阻塞等待）*/
    esp_err_t ret = esp_cam_ctlr_receive(cam->csi, &cam->trans, ESP_CAM_CTLR_MAX_DELAY);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "receive fail[%d]", ret);
        return ret;
    }

    /* cache invalidate：CSI DMA 写 PSRAM 后，CPU 读前必须同步，否则读到旧值 */
    esp_cache_msync(cam->frame_buffer, CAM_FB_SIZE, ESP_CACHE_MSYNC_FLAG_DIR_M2C);

    *out_fb = (uint8_t *)cam->frame_buffer;
    *out_len = CAM_FB_SIZE;
    return ESP_OK;
}

esp_err_t cam_capture_deinit(cam_capture_t *cam)
{
    if (cam->csi) {
        esp_cam_ctlr_stop(cam->csi);
        esp_cam_ctlr_disable(cam->csi);
        esp_cam_ctlr_del(cam->csi);
    }
    if (cam->isp) {
        esp_isp_disable(cam->isp);
        esp_isp_del_processor(cam->isp);
    }
    if (cam->sensor.sccb_handle) {
        example_sensor_deinit(cam->sensor);
    }
    if (cam->frame_buffer) {
        heap_caps_free(cam->frame_buffer);
    }
    if (cam->ldo) {
        esp_ldo_release_channel(cam->ldo);
    }
    memset(cam, 0, sizeof(*cam));
    return ESP_OK;
}

#ifndef JPEG_ENCODER_H
#define JPEG_ENCODER_H

#include <stdint.h>
#include <stddef.h>
#include "esp_err.h"

#ifdef __cplusplus
extern "C" {
#endif

/* 把 RGB565 帧硬件编码成 JPG。
 * rgb565: 输入帧（CSI/ISP 输出，PSRAM 缓冲）
 * len: 帧字节数
 * width/height: 帧分辨率
 * out_jpg: [out] 返回 JPG 数据指针（指向内部静态缓冲，用完前不要再编码下一帧）
 * out_jpg_len: [out] JPG 字节数
 * 返回 ESP_OK 成功。*/
esp_err_t jpeg_enc_encode_rgb565(const uint8_t *rgb565, size_t len,
                                 uint16_t width, uint16_t height,
                                 uint8_t **out_jpg, size_t *out_jpg_len);

void jpeg_enc_deinit(void);

#ifdef __cplusplus
}
#endif

#endif /* JPEG_ENCODER_H */

/*
 * jpeg_encoder.cpp - 硬件 JPEG 编码（RGB565 → JPG）
 *
 * 参考 examples/peripherals/jpeg/jpeg_encode/main/jpeg_encode_main.c。
 * 编码器单例（lazy init），输出缓冲复用。jpeg_alloc_encoder_mem 自动用 PSRAM + cache 对齐。
 */
#include "jpeg_encoder.h"
#include "esp_log.h"
#include "driver/jpeg_encode.h"

static const char *TAG = "jpg";

static jpeg_encoder_handle_t s_enc = NULL;
static uint8_t *s_out_buf = NULL;
static size_t s_out_buf_size = 0;

/* 上界：RGB565 压成 JPG 不会比原数据大 */
#define JPG_OUT_BUF_CAP (800 * 640 * 2)

esp_err_t jpeg_enc_encode_rgb565(const uint8_t *rgb565, size_t len,
                                 uint16_t width, uint16_t height,
                                 uint8_t **out_jpg, size_t *out_jpg_len)
{
    esp_err_t ret = ESP_OK;

    /* lazy 初始化编码器 + 输出缓冲 */
    if (!s_enc) {
        jpeg_encode_engine_cfg_t eng_cfg;
        memset(&eng_cfg, 0, sizeof(eng_cfg));
        eng_cfg.timeout_ms = 70;
        ret = jpeg_new_encoder_engine(&eng_cfg, &s_enc);
        if (ret != ESP_OK) {
            ESP_LOGE(TAG, "new encoder fail[%d]", ret);
            return ret;
        }
        jpeg_encode_memory_alloc_cfg_t out_cfg = {
            .buffer_direction = JPEG_ENC_ALLOC_OUTPUT_BUFFER,
        };
        s_out_buf = (uint8_t *)jpeg_alloc_encoder_mem(JPG_OUT_BUF_CAP, &out_cfg, &s_out_buf_size);
        if (!s_out_buf) {
            ESP_LOGE(TAG, "out buf alloc fail");
            return ESP_ERR_NO_MEM;
        }
        ESP_LOGI(TAG, "JPEG 编码器就绪，输出缓冲 %uB", s_out_buf_size);
    }

    jpeg_encode_cfg_t enc_cfg;
    memset(&enc_cfg, 0, sizeof(enc_cfg));
    enc_cfg.src_type = JPEG_ENCODE_IN_FORMAT_RGB565;
    enc_cfg.sub_sample = JPEG_DOWN_SAMPLING_YUV422;
    enc_cfg.image_quality = 80;
    enc_cfg.width = width;
    enc_cfg.height = height;
    enc_cfg.pixel_reverse = false;

    uint32_t jpg_size = 0;
    ret = jpeg_encoder_process(s_enc, &enc_cfg,
                               rgb565, len,
                               s_out_buf, s_out_buf_size,
                               &jpg_size);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "encode fail[%d]", ret);
        return ret;
    }
    ESP_LOGI(TAG, "编码完成 %ux%u → %uB JPG", width, height, jpg_size);

    *out_jpg = s_out_buf;
    *out_jpg_len = jpg_size;
    return ESP_OK;
}

void jpeg_enc_deinit(void)
{
    if (s_enc) {
        jpeg_del_encoder_engine(s_enc);
        s_enc = NULL;
    }
    /* s_out_buf 由 jpeg_alloc_encoder_mem 分配，跟随编码器生命周期，
     * 编码器删除后由内部回收，这里不 free。*/
    s_out_buf = NULL;
    s_out_buf_size = 0;
}

