25	/* CRC-16/MODBUS，与 tools/img2epd.py 的 crc16() 对齐。*/
26	static uint16_t crc16_modbus(const uint8_t *data, size_t len)
27	{
28	    uint16_t crc = 0xFFFF;
29	    for (size_t i = 0; i < len; i++) {
30	        crc ^= data[i];
31	        for (int b = 0; b < 8; b++) {
32	            if (crc & 0x0001) crc = (crc >> 1) ^ 0xA001;
33	            else              crc >>= 1;
34	        }
35	    }
36	    return crc & 0xFFFF;
37	}
