39	/* 从 UART 读 N 字节，超时则失败。返回实际读取字节数。*/
40	static int read_n(uint8_t *buf, size_t want, uart_port_t uart_port)
41	{
42	    size_t got = 0;
43	    int64_t deadline = esp_timer_get_time() + (int64_t)RX_TIMEOUT_MS * 1000;
44	    while (got < want) {
45	        int n = uart_read_bytes(uart_port, buf + got, want - got,
46	                                pdMS_TO_TICKS(50));
47	        if (n > 0) got += n;
48	        if (esp_timer_get_time() > deadline) break;
49	    }
50	    return got;
51	}
