uint8_t cmd = cmd_len[0];
uint32_t len = cmd_len[1] | (cmd_len[2] << 8) |
               (cmd_len[3] << 16) | (cmd_len[4] << 24);

/* 按命令分别校验长度：
 * - CMD_IMAGE：必须是 EPD_IMAGE_SIZE
 * - CMD_CAPTURE：允许 0 长度（空 payload 触发拍照）*/
if (cmd == EPD_CMD_IMAGE && len != EPD_IMAGE_SIZE) {
    ESP_LOGW(TAG, "IMAGE LEN=%u 不符 %u，丢帧", len, EPD_IMAGE_SIZE);
    continue;
}
if (cmd != EPD_CMD_IMAGE && cmd != EPD_CMD_CAPTURE) {
    ESP_LOGW(TAG, "未知 CMD=0x%02X，丢帧", cmd);
    continue;
}

/* 收满 PAYLOAD（CMD_CAPTURE 可能 0 长度，跳过）*/
if (len > 0) {
    if (read_n(payload, len, uart_port) != len) {
        ESP_LOGW(TAG, "PAYLOAD 超时，丢帧");
        continue;
    }
    /* 校验 CRC16 */
    uint8_t crc_bytes[2];
    if (read_n(crc_bytes, 2, uart_port) != 2) {
        ESP_LOGW(TAG, "CRC 超时");
        continue;
    }
    uint16_t crc_recv = crc_bytes[0] | (crc_bytes[1] << 8);
    uint16_t crc_calc = crc16_modbus(payload, len);
    if (crc_recv != crc_calc) {
        ESP_LOGW(TAG, "CRC 错 收=%04X 算=%04X", crc_recv, crc_calc);
        continue;
    }
} else {
    /* 0 长度 payload 仍有 CRC16 字段 */
    uint8_t crc_bytes[2];
    if (read_n(crc_bytes, 2, uart_port) != 2) continue;
}

/* 按 CMD 分发 */
if (cmd == EPD_CMD_IMAGE) {
    ESP_LOGI(TAG, "收到图片帧 %uB，初始化并显示", len);
    EPD_3IN5G_V2_Init();
    EPD_3IN5G_V2_Display(payload);
    ESP_LOGI(TAG, "显示完成");
} else if (cmd == EPD_CMD_CAPTURE) {
    /* 触发拍照：摄像头抓帧 → JPEG 编码 → 回传 */
    extern cam_capture_t g_cam;  /* main.cpp 定义 */
    extern esp_err_t jpeg_enc_encode_rgb565(const uint8_t *, size_t,
                                             uint16_t, uint16_t,
                                             uint8_t **, size_t *);
    uint8_t *fb = NULL; size_t fb_len = 0;
    esp_err_t e = cam_capture_one_frame(&g_cam, &fb, &fb_len);
    if (e != ESP_OK) {
        ESP_LOGE(TAG, "capture fail[%d]", e);
        continue;
    }
    uint8_t *jpg = NULL; size_t jpg_len = 0;
    e = jpeg_enc_encode_rgb565(fb, fb_len, 800, 640, &jpg, &jpg_len);
    if (e != ESP_OK || !jpg) {
        ESP_LOGE(TAG, "jpeg encode fail");
        continue;
    }
    ESP_LOGI(TAG, "JPG %uB，回传电脑", jpg_len);

    /* 回传帧：帧头|0x06|LEN(4)|JPG|CRC16 */
    uint16_t crc = crc16_modbus(jpg, jpg_len);
    uint8_t hdr[7] = {EPD_FRAME_HEAD0, EPD_FRAME_HEAD1, EPD_CMD_CAPTURE_JPG,
                      (uint8_t)(jpg_len & 0xFF), (uint8_t)((jpg_len >> 8) & 0xFF),
                      (uint8_t)((jpg_len >> 16) & 0xFF), (uint8_t)((jpg_len >> 24) & 0xFF)};
    uart_write_bytes(uart_port, hdr, 7);
    /* 分块发 JPG（512B/块，留时间给对端消化）*/
    size_t off = 0;
    while (off < jpg_len) {
        size_t n = (jpg_len - off > 512) ? 512 : (jpg_len - off);
        uart_write_bytes(uart_port, jpg + off, n);
        off += n;
        vTaskDelay(pdMS_TO_TICKS(1));
    }
    uint8_t crc_b[2] = {(uint8_t)(crc & 0xFF), (uint8_t)((crc >> 8) & 0xFF)};
    uart_write_bytes(uart_port, crc_b, 2);
    ESP_LOGI(TAG, "JPG 回传完成");
}

