static int read_n(uint8_t *buf, size_t want, uart_port_t uart_port)
{
    size_t got = 0;
    TickType_t deadline = xTaskGetTickCount() + pdMS_TO_TICKS(RX_TIMEOUT_MS);
    while (got < want) {
        int n = uart_read_bytes(uart_port, buf + got, want - got,
                                pdMS_TO_TICKS(50));
