#ifndef ETH_INIT_H
#define ETH_INIT_H

#include "esp_err.h"

#ifdef __cplusplus
extern "C" {
#endif

/* 初始化以太网 + DHCP，阻塞等待获取 IP。
 * 返回 ESP_OK 表示已拿到 IP。*/
esp_err_t eth_init_and_wait_ip(uint32_t timeout_ms);

#ifdef __cplusplus
}
#endif

#endif

/*
 * eth_init.cpp - ESP32-P4 以太网初始化
 *
 * 基于 examples/ethernet/basic/ethernet_example_main.c 简化：
 * 只做 EMAC + PHY 初始化 + DHCP 等 IP，不做 iperf 等。
 *
 * ESP32-P4 Function EV-Board 用 Generic 802.3 PHY，RMII 接口。
 * PHY 地址、MDC/MDIO、复位脚用 ETH_ESP32_EMAC_DEFAULT_CONFIG 默认值。
 */
#include "eth_init.h"
#include "esp_log.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_eth.h"
#include "esp_eth_mac.h"
#include "esp_eth_phy.h"
#include "freertos/FreeRTOS.h"
#include "freertos/event_groups.h"

static const char *TAG = "eth";
static EventGroupHandle_t s_eth_event_group;
static esp_netif_t *s_eth_netif = NULL;
static esp_eth_handle_t s_eth_handle = NULL;

#define ETH_CONNECTED_BIT BIT0
#define ETH_GOT_IP_BIT    BIT1
#define ETH_FAIL_BIT      BIT2

static void eth_event_handler(void *arg, esp_event_base_t event_base,
                              int32_t event_id, void *event_data)
{
    uint8_t mac_addr[6] = {0};
    esp_eth_handle_t eth_handle = *(esp_eth_handle_t *)event_data;

    switch (event_id) {
    case ETHERNET_EVENT_CONNECTED:
        esp_eth_ioctl(eth_handle, ETH_CMD_G_MAC_ADDR, mac_addr);
        ESP_LOGI(TAG, "Link Up  MAC:%02x:%02x:%02x:%02x:%02x:%02x",
                 mac_addr[0], mac_addr[1], mac_addr[2], mac_addr[3], mac_addr[4], mac_addr[5]);
        xEventGroupSetBits(s_eth_event_group, ETH_CONNECTED_BIT);
        break;
    case ETHERNET_EVENT_DISCONNECTED:
        ESP_LOGW(TAG, "Link Down");
        xEventGroupClearBits(s_eth_event_group, ETH_CONNECTED_BIT | ETH_GOT_IP_BIT);
        break;
    case ETHERNET_EVENT_START:
        ESP_LOGI(TAG, "Started");
        break;
    case ETHERNET_EVENT_STOP:
        ESP_LOGW(TAG, "Stopped");
        break;
    default:
        break;
    }
}

static void got_ip_event_handler(void *arg, esp_event_base_t event_base,
                                 int32_t event_id, void *event_data)
{
    ip_event_got_ip_t *event = (ip_event_got_ip_t *)event_data;
    ESP_LOGI(TAG, "Got IP: " IPSTR, IP2STR(&event->ip_info.ip));
    xEventGroupSetBits(s_eth_event_group, ETH_GOT_IP_BIT);
}

esp_err_t eth_init_and_wait_ip(uint32_t timeout_ms)
{
    s_eth_event_group = xEventGroupCreate();

    /* 1. 网络接口 + 事件循环 */
    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());

    s_eth_netif = esp_netif_new(ESP_NETIF_DEFAULT_ETH());
    esp_eth_netif_glue_handle_t eth_netif_glue = esp_eth_new_netif_glue(s_eth_handle);

    /* 2. MAC + PHY 初始化 */
    eth_mac_config_t mac_config = ETH_MAC_DEFAULT_CONFIG();
    eth_phy_config_t phy_config = ETH_PHY_DEFAULT_CONFIG();

    esp_eth_mac_t *mac = esp_eth_mac_new_esp32(
        &(esp32_emac_config_t){
            .smi_gpio = ETH_ESP32_EMAC_DEFAULT_CONFIG.smi_gpio,
            .interface = EMAC_DATA_INTERFACE_RMII,
            .clock_config = ETH_ESP32_EMAC_DEFAULT_CONFIG.clock_config,
        },
        &mac_config);
    if (!mac) { ESP_LOGE(TAG, "MAC create fail"); return ESP_FAIL; }

    esp_eth_phy_t *phy = esp_eth_phy_new_generic(&phy_config);
    if (!phy) { ESP_LOGE(TAG, "PHY create fail"); mac->del(mac); return ESP_FAIL; }

    esp_eth_config_t eth_config = ETH_DEFAULT_CONFIG(mac, phy);
    ESP_ERROR_CHECK(esp_eth_driver_install(&eth_config, &s_eth_handle));
    mac->del(mac);
    phy->del(phy);

    /* 3. 驱动挂到 netif */
    ESP_ERROR_CHECK(esp_netif_attach(s_eth_netif,
                                     esp_eth_new_netif_glue(s_eth_handle)));

    /* 4. 注册事件 */
    ESP_ERROR_CHECK(esp_event_handler_register(ETH_EVENT, ESP_EVENT_ANY_ID,
                                               &eth_event_handler, NULL));
    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_ETH_GOT_IP,
                                               &got_ip_event_handler, NULL));

    /* 5. 启动以太网 + 等 DHCP */
    ESP_ERROR_CHECK(esp_eth_start(s_eth_handle));

    ESP_LOGI(TAG, "等待以太网连接并获取 IP（超时 %lu ms）...", (unsigned long)timeout_ms);
    EventBits_t bits = xEventGroupWaitBits(s_eth_event_group,
                                           ETH_GOT_IP_BIT | ETH_FAIL_BIT,
                                           pdFALSE, pdFALSE,
                                           pdMS_TO_TICKS(timeout_ms));

    if (bits & ETH_GOT_IP_BIT) {
        ESP_LOGI(TAG, "以太网就绪");
        return ESP_OK;
    }
    ESP_LOGW(TAG, "以太网未获取 IP（超时）");
    return ESP_ERR_TIMEOUT;
}

#ifndef TCP_SERVER_H
#define TCP_SERVER_H

#include "esp_err.h"
#include "camera_capture.h"

#ifdef __cplusplus
extern "C" {
#endif

/* 启动 TCP server（端口 8080），监听拍照命令。
 * 客户端连上后发 "CAPTURE\n"，server 拍照+JPEG+回传。
 * cam: 摄像头句柄（main.cpp 的全局 g_cam）*/
esp_err_t tcp_server_start(cam_capture_t *cam);

#ifdef __cplusplus
}
#endif

#endif

/*
 * tcp_server.cpp - 以太网 TCP Server，接收拍照命令并回传 JPG
 *
 * 协议（极简，TCP 自带可靠传输）：
 *   客户端发: "CAPTURE\n"
 *   服务端回: 4 字节 uint32_t (小端) JPG 长度 + JPG 数据
 *
 * 端口: 8080
 * Python 端: tools/capture_tcp.py
 */
#include "tcp_server.h"
#include "camera_capture.h"
#include "jpeg_encoder.h"

#include <string.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "lwip/sockets.h"
#include "lwip/netdb.h"

static const char *TAG = "tcp_srv";
#define TCP_PORT 8080
#define RECV_BUF_SIZE 64

static cam_capture_t *s_cam = NULL;

static void handle_client(int sock)
{
    char buf[RECV_BUF_SIZE];
    int len = recv(sock, buf, sizeof(buf) - 1, 0);
    if (len <= 0) {
        close(sock);
        return;
    }
    buf[len] = '\0';
    ESP_LOGI(TAG, "收到命令: %s", buf);

    /* 简单匹配 "CAPTURE" */
    if (strncmp(buf, "CAPTURE", 7) != 0) {
        ESP_LOGW(TAG, "未知命令: %s", buf);
        const char *err = "ERROR: unknown command\n";
        send(sock, err, strlen(err), 0);
        close(sock);
        return;
    }

    /* 1. 拍照 */
    ESP_LOGI(TAG, "开始拍照...");
    uint8_t *fb = NULL;
    size_t fb_len = 0;
    esp_err_t e = cam_capture_one_frame(s_cam, &fb, &fb_len);
    if (e != ESP_OK || !fb) {
        ESP_LOGE(TAG, "拍照失败[%d]", e);
        const char *err = "ERROR: capture failed\n";
        send(sock, err, strlen(err), 0);
        close(sock);
        return;
    }

    /* 2. JPEG 编码 */
    ESP_LOGI(TAG, "JPEG 编码中...");
    uint8_t *jpg = NULL;
    size_t jpg_len = 0;
    e = jpeg_enc_encode_rgb565(fb, fb_len, CAM_HRES, CAM_VRES, &jpg, &jpg_len);
    if (e != ESP_OK || !jpg) {
        ESP_LOGE(TAG, "JPEG 编码失败[%d]", e);
        const char *err = "ERROR: jpeg encode failed\n";
        send(sock, err, strlen(err), 0);
        close(sock);
        return;
    }
    ESP_LOGI(TAG, "JPG %uB，回传中...", jpg_len);

    /* 3. 回传：4字节长度 + JPG 数据 */
    uint32_t jpg_len_be = jpg_len;  /* lwip send 是可靠传输，小端即可 */
    send(sock, &jpg_len_be, 4, 0);

    size_t off = 0;
    while (off < jpg_len) {
        int n = send(sock, jpg + off, jpg_len - off, 0);
        if (n <= 0) {
            ESP_LOGE(TAG, "发送失败[%d]", n);
            break;
        }
        off += n;
    }

    ESP_LOGI(TAG, "回传完成 %uB", jpg_len);
    close(sock);
}

static void server_task(void *arg)
{
    int server_sock = socket(AF_INET, SOCK_STREAM, IPPROTO_IP);
    if (server_sock < 0) {
        ESP_LOGE(TAG, "socket 创建失败: errno %d", errno);
        vTaskDelete(NULL);
        return;
    }

    int opt = 1;
    setsockopt(server_sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(TCP_PORT);

    if (bind(server_sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        ESP_LOGE(TAG, "bind 失败: errno %d", errno);
        close(server_sock);
        vTaskDelete(NULL);
        return;
    }

    listen(server_sock, 1);
    ESP_LOGI(TAG, "TCP Server 监听端口 %d，等待连接...", TCP_PORT);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t addr_len = sizeof(client_addr);
        int client_sock = accept(server_sock, (struct sockaddr *)&client_addr, &addr_len);
        if (client_sock < 0) {
            ESP_LOGE(TAG, "accept 失败: errno %d", errno);
            continue;
        }

        char client_ip[16];
        inet_ntoa_r(client_addr.sin_addr, client_ip, sizeof(client_ip));
        ESP_LOGI(TAG, "客户端连接: %s:%d", client_ip, ntohs(client_addr.sin_port));

        handle_client(client_sock);
    }
}

esp_err_t tcp_server_start(cam_capture_t *cam)
{
    s_cam = cam;
    BaseType_t ok = xTaskCreate(server_task, "tcp_srv", 8192, NULL, 5, NULL);
    return ok == pdPASS ? ESP_OK : ESP_FAIL;
}

/*
 * ESP-IDF entry point
 * 以太网 + 摄像头拍照验证：开机初始化以太网(DHCP) → 启动 TCP Server → 等电脑连接拍照
 *
