    if (e != ESP_OK) {
        ESP_LOGW(TAG, "以太网未获取 IP，但继续启动摄像头+TCP（可用于调试）");
    }

    /* ---- 摄像头 ---- */
    ESP_LOGI(TAG, "初始化摄像头...");
    e = cam_capture_init(&g_cam);
    if (e != ESP_OK) {
        ESP_LOGE(TAG, "摄像头初始化失败[%d]", e);
    }

    /* ---- TCP Server ---- */
    if (e == ESP_OK) {
        ESP_LOGI(TAG, "启动 TCP Server...");
        tcp_server_start(&g_cam);
    }

    ESP_LOGI(TAG, "系统就绪");
    ESP_LOGI(TAG, "用 capture_tcp.py 连接拍照:");
    ESP_LOGI(TAG, "  python tools/capture_tcp.py --ip <P4的IP> --port 8080");
}

