1	/*
2	 * tcp_server.cpp - 以太网 TCP Server，接收拍照命令并回传 JPG
3	 *
4	 * 协议（极简，TCP 自带可靠传输）：
5	 *   客户端发: "CAPTURE\n"
6	 *   服务端回: 4 字节 uint32_t (小端) JPG 长度 + JPG 数据
7	 *
8	 * 端口: 8080
9	 * Python 端: tools/capture_tcp.py
10	 */
11	#include "tcp_server.h"
12	#include "camera_capture.h"
13	#include "jpeg_encoder.h"
14	
15	#include <string.h>
16	#include "freertos/FreeRTOS.h"
17	#include "freertos/task.h"
18	#include "esp_log.h"
19	#include "lwip/sockets.h"
20	#include "lwip/netdb.h"
21	
22	static const char *TAG = "tcp_srv";
23	#define TCP_PORT 8080
24	#define RECV_BUF_SIZE 64
25	
26	static cam_capture_t *s_cam = NULL;
27	
28	static void handle_client(int sock)
29	{
30	    char buf[RECV_BUF_SIZE];
31	    int len = recv(sock, buf, sizeof(buf) - 1, 0);
32	    if (len <= 0) {
33	        close(sock);
34	        return;
35	    }
36	    buf[len] = '\0';
37	    ESP_LOGI(TAG, "收到命令: %s", buf);
38	
39	    /* 简单匹配 "CAPTURE" */
40	    if (strncmp(buf, "CAPTURE", 7) != 0) {
41	        ESP_LOGW(TAG, "未知命令: %s", buf);
42	        const char *err = "ERROR: unknown command\n";
43	        send(sock, err, strlen(err), 0);
44	        close(sock);
45	        return;
46	    }
47	
48	    /* 1. 拍照 */
49	    ESP_LOGI(TAG, "开始拍照...");
50	    uint8_t *fb = NULL;
51	    size_t fb_len = 0;
52	    esp_err_t e = cam_capture_one_frame(s_cam, &fb, &fb_len);
53	    if (e != ESP_OK || !fb) {
54	        ESP_LOGE(TAG, "拍照失败[%d]", e);
55	        const char *err = "ERROR: capture failed\n";
56	        send(sock, err, strlen(err), 0);
57	        close(sock);
58	        return;
59	    }
60	
61	    /* 2. JPEG 编码 */
62	    ESP_LOGI(TAG, "JPEG 编码中...");
63	    uint8_t *jpg = NULL;
64	    size_t jpg_len = 0;
65	    e = jpeg_enc_encode_rgb565(fb, fb_len, CAM_HRES, CAM_VRES, &jpg, &jpg_len);
66	    if (e != ESP_OK || !jpg) {
67	        ESP_LOGE(TAG, "JPEG 编码失败[%d]", e);
68	        const char *err = "ERROR: jpeg encode failed\n";
69	        send(sock, err, strlen(err), 0);
70	        close(sock);
71	        return;
72	    }
73	    ESP_LOGI(TAG, "JPG %uB，回传中...", jpg_len);
74	
75	    /* 3. 回传：4字节长度 + JPG 数据 */
76	    uint32_t jpg_len_be = jpg_len;  /* lwip send 是可靠传输，小端即可 */
77	    send(sock, &jpg_len_be, 4, 0);
78	
79	    size_t off = 0;
80	    while (off < jpg_len) {
81	        int n = send(sock, jpg + off, jpg_len - off, 0);
82	        if (n <= 0) {
83	            ESP_LOGE(TAG, "发送失败[%d]", n);
84	            break;
85	        }
86	        off += n;
87	    }
88	
89	    ESP_LOGI(TAG, "回传完成 %uB", jpg_len);
90	    close(sock);
91	}
92	
93	static void server_task(void *arg)
94	{
95	    int server_sock = socket(AF_INET, SOCK_STREAM, IPPROTO_IP);
96	    if (server_sock < 0) {
97	        ESP_LOGE(TAG, "socket 创建失败: errno %d", errno);
98	        vTaskDelete(NULL);
99	        return;
100	    }
101	
102	    int opt = 1;
103	    setsockopt(server_sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
104	
105	    struct sockaddr_in addr;
106	    memset(&addr, 0, sizeof(addr));
107	    addr.sin_family = AF_INET;
108	    addr.sin_addr.s_addr = htonl(INADDR_ANY);
109	    addr.sin_port = htons(TCP_PORT);
110	
111	    if (bind(server_sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
112	        ESP_LOGE(TAG, "bind 失败: errno %d", errno);
113	        close(server_sock);
114	        vTaskDelete(NULL);
115	        return;
116	    }
117	
118	    listen(server_sock, 1);
119	    ESP_LOGI(TAG, "TCP Server 监听端口 %d，等待连接...", TCP_PORT);
120	
121	    while (1) {
122	        struct sockaddr_in client_addr;
123	        socklen_t addr_len = sizeof(client_addr);
124	        int client_sock = accept(server_sock, (struct sockaddr *)&client_addr, &addr_len);
125	        if (client_sock < 0) {
126	            ESP_LOGE(TAG, "accept 失败: errno %d", errno);
127	            continue;
128	        }
129	
130	        char client_ip[16];
131	        inet_ntoa_r(client_addr.sin_addr, client_ip, sizeof(client_ip));
132	        ESP_LOGI(TAG, "客户端连接: %s:%d", client_ip, ntohs(client_addr.sin_port));
133	
134	        handle_client(client_sock);
135	    }
136	}
137	
138	esp_err_t tcp_server_start(cam_capture_t *cam)
139	{
140	    s_cam = cam;
141	    BaseType_t ok = xTaskCreate(server_task, "tcp_srv", 8192, NULL, 5, NULL);
142	    return ok == pdPASS ? ESP_OK : ESP_FAIL;
143	}
