esp_err_t cam_capture_one_frame(cam_capture_t *cam, uint8_t **out_fb, size_t *out_len)
{
    if (!cam || !cam->csi) return ESP_ERR_INVALID_STATE;

    /* 每次拍照前重新启动 CSI（解决第二次 receive 阻塞问题）*/
    esp_cam_ctlr_stop(cam->csi);
    esp_cam_ctlr_start(cam->csi);

    /* 收一帧（5 秒超时，不用 MAX_DELAY 避免永久阻塞）*/
    esp_err_t ret = esp_cam_ctlr_receive(cam->csi, &cam->trans, pdMS_TO_TICKS(5000));
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "receive fail[%d]，尝试重启 CSI", ret);
        esp_cam_ctlr_stop(cam->csi);
        esp_cam_ctlr_start(cam->csi);
        return ret;
    }

    /* cache invalidate：CSI DMA 写 PSRAM 后，CPU 读前必须同步，否则读到旧值 */
    esp_cache_msync(cam->frame_buffer, CAM_FB_SIZE, ESP_CACHE_MSYNC_FLAG_DIR_M2C);

    *out_fb = (uint8_t *)cam->frame_buffer;
    *out_len = CAM_FB_SIZE;
    return ESP_OK;
}

