/*
 * C6 BLE-UART Bridge
 *
 * ESP32-C6 作为 BLE 外设，桥接 BLE ↔ UART：
 *   BLE RX → UART TX（发给 P4）
 *   UART RX（来自 P4）→ BLE TX
 *
 * 基于 ESP-IDF ble_uart_service 例程，增加 UART 转发功能。
 */

#include <stdio.h>
#include <string.h>

#include "esp_log.h"
#include "esp_mac.h"
#include "nvs_flash.h"
#include "sdkconfig.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/queue.h"
#include "driver/uart.h"

#include "ble_uart.h"

static const char *TAG = "bridge";

/* UART 配置（C6 → P4） */
#define UART_PORT_NUM    UART_NUM_1
#define UART_TX_PIN      16   /* C6 U0TXD → P4 RX */
#define UART_RX_PIN      17   /* C6 U0RXD → P4 TX */
#define UART_BAUD_RATE   115200
#define UART_RX_BUF_SIZE 2048
#define UART_TX_BUF_SIZE 2048

/* BLE → UART 队列 */
static QueueHandle_t s_ble_to_uart_queue = NULL;

/* ---- UART 初始化 ---- */
static void uart_init(void)
{
    uart_config_t uart_cfg = {
        .baud_rate = UART_BAUD_RATE,
        .data_bits = UART_DATA_8_BITS,
        .parity = UART_PARITY_DISABLE,
        .stop_bits = UART_STOP_BITS_1,
        .flow_ctrl = UART_HW_FLOWCTRL_DISABLE,
        .source_clk = UART_SCLK_DEFAULT,
    };

    /* 安装驱动（RX 缓冲 + 队列） */
    ESP_ERROR_CHECK(uart_driver_install(UART_PORT_NUM, UART_RX_BUF_SIZE,
                                        UART_TX_BUF_SIZE, 0, NULL, 0));
    ESP_ERROR_CHECK(uart_param_config(UART_PORT_NUM, &uart_cfg));
    ESP_ERROR_CHECK(uart_set_pin(UART_PORT_NUM, UART_TX_PIN, UART_RX_PIN,
                                 UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE));

    ESP_LOGI(TAG, "UART%d init: TX=GPIO%d RX=GPIO%d @ %d",
             UART_PORT_NUM, UART_TX_PIN, UART_RX_PIN, UART_BAUD_RATE);
}

/* ---- UART TX：从队列取数据发到 P4 ---- */
static void uart_tx_task(void *arg)
{
    uint8_t *data;
    while (1) {
        if (xQueueReceive(s_ble_to_uart_queue, &data, portMAX_DELAY) == pdTRUE) {
            /* data 是 BLE RX 回调动态分配的，用完释放 */
            size_t len = strlen((char *)data);
            if (len > 0) {
                uart_write_bytes(UART_PORT_NUM, data, len);
                ESP_LOGI(TAG, "BLE->UART: %u bytes", (unsigned)len);
            }
            free(data);
        }
    }
}

/* ---- UART RX：从 P4 收数据，转发到 BLE ---- */
static void uart_rx_task(void *arg)
{
    uint8_t buf[512];
    while (1) {
        int len = uart_read_bytes(UART_PORT_NUM, buf, sizeof(buf),
                                  pdMS_TO_TICKS(100));
        if (len > 0) {
            ESP_LOGI(TAG, "UART->BLE: %d bytes", len);
            ble_uart_tx(buf, len);
        }
    }
}

/* ---- BLE RX 回调：收到 BLE 数据，入队转发到 UART ---- */
static void ble_uart_on_rx(const uint8_t *data, size_t len)
{
    if (data == NULL || len == 0) {
        return;
    }
    ESP_LOGI(TAG, "BLE RX: %u bytes", (unsigned)len);

    /* 动态分配，放入队列（由 uart_tx_task 释放） */
    uint8_t *copy = malloc(len + 1);
    if (copy) {
        memcpy(copy, data, len);
        copy[len] = '\0';
        if (xQueueSend(s_ble_to_uart_queue, &copy, pdMS_TO_TICKS(100)) != pdTRUE) {
            ESP_LOGW(TAG, "BLE->UART queue full, drop %u bytes", (unsigned)len);
            free(copy);
        }
    }
}

void app_main(void)
{
    /* NVS 初始化（BT 和 bond 需要） */
    esp_err_t err = nvs_flash_init();
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        err = nvs_flash_init();
    }
    ESP_ERROR_CHECK(err);

    /* 设备名 = "Bridge-XXXX"（XXXX = MAC 后两位） */
    uint8_t mac[6] = {0};
    esp_err_t mac_err = esp_read_mac(mac, ESP_MAC_BT);
    if (mac_err != ESP_OK) {
        ESP_LOGW(TAG, "esp_read_mac failed, name suffix 0000");
    }
    char name[24];
    snprintf(name, sizeof(name), "%s-%02X%02X",
             CONFIG_BLE_UART_DEVICE_NAME_PREFIX, mac[4], mac[5]);

    /* UART 初始化 */
    uart_init();

    /* BLE→UART 队列 */
    s_ble_to_uart_queue = xQueueCreate(8, sizeof(uint8_t *));
    assert(s_ble_to_uart_queue);

    /* UART TX/RX 任务 */
    xTaskCreate(uart_tx_task, "uart_tx", 4096, NULL, 5, NULL);
    xTaskCreate(uart_rx_task, "uart_rx", 4096, NULL, 5, NULL);

    /* BLE UART 安装（加密 + 配对） */
    ESP_ERROR_CHECK(ble_uart_install(&(ble_uart_config_t){
        .encrypted      = true,
        .device_name    = name,
        .ble_uart_on_rx = ble_uart_on_rx,
    }));
    ESP_ERROR_CHECK(ble_uart_open());

    ESP_LOGI(TAG, "BLE-UART bridge started, name: %s", name);
}

