/*
 * ESP-IDF entry point
 * 以太网 + 摄像头拍照验证：开机初始化以太网(DHCP) → 启动 TCP Server → 等电脑连接拍照
 *
 * 流程：PSRAM → 以太网(DHCP 拿 IP) → 摄像头 → TCP Server → 等命令
 * 电脑发 "CAPTURE" → P4 拍照+JPEG → TCP 回传 JPG
 */
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_psram.h"
#include "esp_heap_caps.h"
#include "esp_log.h"
#include "esp_err.h"
#include "DEV_Config.h"
#include "camera_capture.h"
#include "jpeg_encoder.h"
#include "eth_init.h"
#include "tcp_server.h"

static const char *TAG = "main";

/* 全局摄像头句柄 */
cam_capture_t g_cam;

extern "C" void app_main(void)
{
    /* ---- PSRAM ---- */
    size_t psram_size = esp_psram_get_size();
    ESP_LOGI(TAG, "PSRAM: %u bytes (%.1f MB)", psram_size, psram_size / 1048576.0);
    if (psram_size == 0) {
        ESP_LOGE(TAG, "PSRAM 未初始化！");
        return;
    }

    /* ---- 墨水屏 GPIO（保留，后续集显示用）---- */
    DEV_Module_Init();

    /* ---- 以太网 ---- */
    ESP_LOGI(TAG, "初始化以太网...");
    esp_err_t e = eth_init_and_wait_ip(30000);  /* 30 秒超时 */
    if (e != ESP_OK) {
        ESP_LOGW(TAG, "以太网未获取 IP，但继续启动摄像头+TCP（可用于调试）");
    }

    /* ---- 摄像头 ---- */
    ESP_LOGI(TAG, "初始化摄像头...");
    e = cam_capture_init(&g_cam);
    if (e != ESP_OK) {
        ESP_LOGE(TAG, "摄像头初始化失败[%d]", e);
    }

    /* ---- TCP Server ---- */
    if (e == ESP_OK) {
        ESP_LOGI(TAG, "启动 TCP Server...");
        tcp_server_start(&g_cam);
    }

    ESP_LOGI(TAG, "系统就绪");
    ESP_LOGI(TAG, "用 capture_tcp.py 连接拍照:");
    ESP_LOGI(TAG, "  python tools/capture_tcp.py --ip <P4的IP> --port 8080");
}

