322	static void free_prep_wr_buffer(void)
323	{
324	    spp_receive_data_node_t *cur = spp_prep_wr_buff.first_node;
325	
326	    while (cur != NULL) {
327	        spp_receive_data_node_t *next = cur->next_node;
328	        if (cur->node_buff) {
329	            free(cur->node_buff);
330	        }
331	        free(cur);
332	        cur = next;
333	    }
334	
335	    spp_prep_wr_buff.node_num = 0;
336	    spp_prep_wr_buff.buff_size = 0;
337	    spp_prep_wr_buff.first_node = NULL;
338	    spp_prep_wr_buff.last_node = NULL;
339	}
