351	void uart_task(void *pvParameters)
352	{
353	    uart_event_t event;
354	    uint8_t total_num = 0;
355	    uint8_t current_num = 0;
356	
357	    for (;;) {
358	        //Waiting for UART event.
359	        if (xQueueReceive(spp_uart_queue, (void * )&event, (TickType_t)portMAX_DELAY)) {
360	            switch (event.type) {
361	            //Event of UART receiving data
362	            case UART_DATA:
363	                if ((event.size)&&(is_connected)) {
364	                    uint8_t * temp = NULL;
365	                    uint8_t * ntf_value_p = NULL;
366	#ifdef SUPPORT_HEARTBEAT
367	                    if(!enable_heart_ntf){
368	                        ESP_LOGE(GATTS_TABLE_TAG, "%s do not enable heartbeat Notify", __func__);
369	                        break;
370	                    }
371	#endif
372	                    if(!enable_data_ntf){
373	                        ESP_LOGE(GATTS_TABLE_TAG, "%s do not enable data Notify", __func__);
374	                        break;
375	                    }
376	                    temp = (uint8_t *)malloc(sizeof(uint8_t)*event.size);
377	                    if (temp == NULL) {
378	                        ESP_LOGE(GATTS_TABLE_TAG, "%s malloc.1 failed", __func__);
379	                        break;
380	                    }
381	                    uart_read_bytes(UART_NUM_0, temp, event.size, portMAX_DELAY);
382	                    if (event.size <= (spp_mtu_size - 3)) {
383	#ifdef CONFIG_EXAMPLE_ENABLE_RF_EMC_TEST_MODE
384	                        ESP_LOG_BUFFER_HEX("TX", temp, event.size);
385	#endif
386	#ifdef CONFIG_EXAMPLE_SPP_THROUGHPUT
387	                        if(esp_ble_get_cur_sendable_packets_num(spp_conn_id) > 0) {
388	                            esp_ble_gatts_send_indicate(spp_gatts_if, spp_conn_id, spp_handle_table[SPP_IDX_SPP_DATA_NTY_VAL], event.size, temp, false);
389	                        } else {
390	                            //Add the vTaskDelay to prevent this task from consuming the CPU all the time, causing low-priority tasks to not be executed at all.
391	                            vTaskDelay(10 / portTICK_PERIOD_MS);
392	                        }
393	#else
394	                        esp_ble_gatts_send_indicate(spp_gatts_if, spp_conn_id, spp_handle_table[SPP_IDX_SPP_DATA_NTY_VAL], event.size, temp, true);
395	#endif
396	                    } else if (event.size > (spp_mtu_size - 3)) {
397	                        if ((event.size % (spp_mtu_size - 7)) == 0) {
398	                            total_num = event.size / (spp_mtu_size - 7);
399	                        } else {
400	                            total_num = event.size / (spp_mtu_size - 7) + 1;
401	                        }
402	                        current_num = 1;
403	                        ntf_value_p = (uint8_t *)malloc((spp_mtu_size-3)*sizeof(uint8_t));
404	                        if (ntf_value_p == NULL) {
405	                            ESP_LOGE(GATTS_TABLE_TAG, "%s malloc.2 failed", __func__);
406	                            free(temp);
407	                            break;
408	                        }
409	                        while (current_num <= total_num) {
410	                            if (current_num < total_num) {
411	                                ntf_value_p[0] = '#';
412	                                ntf_value_p[1] = '#';
413	                                ntf_value_p[2] = total_num;
414	                                ntf_value_p[3] = current_num;
415	                                memcpy(ntf_value_p + 4, temp + (current_num - 1)*(spp_mtu_size-7), (spp_mtu_size-7));
416	                                esp_ble_gatts_send_indicate(spp_gatts_if, spp_conn_id, spp_handle_table[SPP_IDX_SPP_DATA_NTY_VAL], (spp_mtu_size-3), ntf_value_p, false);
417	                            } else if(current_num == total_num) {
418	                                ntf_value_p[0] = '#';
419	                                ntf_value_p[1] = '#';
420	                                ntf_value_p[2] = total_num;
421	                                ntf_value_p[3] = current_num;
422	                                memcpy(ntf_value_p + 4, temp + (current_num - 1)*(spp_mtu_size-7), (event.size - (current_num - 1)*(spp_mtu_size - 7)));
423	                                esp_ble_gatts_send_indicate(spp_gatts_if, spp_conn_id, spp_handle_table[SPP_IDX_SPP_DATA_NTY_VAL], (event.size - (current_num - 1)*(spp_mtu_size - 7) + 4), ntf_value_p, false);
424	                            }
425	                            vTaskDelay(20 / portTICK_PERIOD_MS);
426	                            current_num++;
427	                        }
428	                        free(ntf_value_p);
429	                    }
430	                    free(temp);
431	                }
432	                break;
433	            default:
434	                break;
435	            }
436	        }
437	    }
438	    vTaskDelete(NULL);
439	}
