559	{
560	    esp_ble_gatts_cb_param_t *p_data = (esp_ble_gatts_cb_param_t *) param;
561	    uint8_t res = 0xff;
562	
563	    switch (event) {
564	    	case ESP_GATTS_REG_EVT:
565	    	    ESP_LOGI(GATTS_TABLE_TAG, "GATT server register, status %d, app_id %d, gatts_if %d", param->reg.status, param->reg.app_id, gatts_if);
566	        	esp_ble_gap_set_device_name(SAMPLE_DEVICE_NAME);
567	        	esp_ble_gap_config_adv_data_raw((uint8_t *)spp_adv_data, sizeof(spp_adv_data));
568	        	esp_ble_gatts_create_attr_tab(spp_gatt_db, gatts_if, SPP_IDX_NB, SPP_SVC_INST_ID);
569	       	break;
570	    	case ESP_GATTS_READ_EVT:
571	            ESP_LOGI(GATTS_TABLE_TAG, "Characteristic read");
572	       	break;
573	    	case ESP_GATTS_WRITE_EVT: {
574	            // ESP_LOGI(GATTS_TABLE_TAG, "Characteristic write, conn_id %d, handle %d", param->write.conn_id, param->write.handle);
575	    	    res = find_char_and_desr_index(p_data->write.handle);
576	            if (p_data->write.is_prep == false) {
577	                if (res == SPP_IDX_SPP_COMMAND_VAL) {
578	                    uint8_t *spp_cmd_buff = (uint8_t *)malloc(p_data->write.len);
579	                    if (spp_cmd_buff == NULL) {
580	                        ESP_LOGE(GATTS_TABLE_TAG, "%s malloc failed", __func__);
581	                        break;
582	                    }
583	                    memcpy(spp_cmd_buff, p_data->write.value, p_data->write.len);
584	                    spp_cmd_queue_msg_t msg = { .len = p_data->write.len, .data = spp_cmd_buff };
585	                    if (xQueueSend(cmd_cmd_queue, &msg, 10 / portTICK_PERIOD_MS) != pdTRUE) {
586	                        ESP_LOGE(GATTS_TABLE_TAG, "%s cmd_cmd_queue send failed", __func__);
587	                        free(spp_cmd_buff);
588	                    }
589	                } else if (res == SPP_IDX_SPP_DATA_NTF_CFG) {
590	                    if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x01) && (p_data->write.value[1] == 0x00)) {
591	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP data notification enable");
592	                        enable_data_ntf = true;
593	                    } else if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x02) && (p_data->write.value[1] == 0x00)) {
594	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP data indication enable");
595	                        enable_data_ntf = true;
596	                    } else if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x00) && (p_data->write.value[1] == 0x00)) {
597	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP data notification/indication disable");
598	                        enable_data_ntf = false;
599	                    }
600	                } else if (res == SPP_IDX_SPP_STATUS_CFG) {
601	                    if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x01) && (p_data->write.value[1] == 0x00)) {
602	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP status notification enable");
603	                    } else if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x00) && (p_data->write.value[1] == 0x00)) {
604	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP status notification disable");
605	                    }
606	                }
607	#ifdef SUPPORT_HEARTBEAT
608	                else if (res == SPP_IDX_SPP_HEARTBEAT_CFG) {
609	                    if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x01) && (p_data->write.value[1] == 0x00)) {
610	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP heartbeat notification enable");
611	                        enable_heart_ntf = true;
612	                        heartbeat_count_num = 0;
613	                    } else if ((p_data->write.len == 2) && (p_data->write.value[0] == 0x00) && (p_data->write.value[1] == 0x00)) {
614	                        ESP_LOGI(GATTS_TABLE_TAG, "SPP heartbeat notification disable");
615	                        enable_heart_ntf = false;
616	                        heartbeat_count_num = 0;
617	                    }
618	                } else if (res == SPP_IDX_SPP_HEARTBEAT_VAL) {
619	                    if ((p_data->write.len == sizeof(heartbeat_s)) && (memcmp(heartbeat_s, p_data->write.value, sizeof(heartbeat_s)) == 0)) {
620	                        heartbeat_count_num = 0;
621	                    }
622	                }
623	#endif
624	                else if (res == SPP_IDX_SPP_DATA_RECV_VAL) {
625	#ifdef CONFIG_EXAMPLE_ENABLE_RF_EMC_TEST_MODE
626	                    ESP_LOG_BUFFER_HEX("RX", p_data->write.value, p_data->write.len);
627	#else
628	                    uart_write_bytes(UART_NUM_0, (char *)(p_data->write.value), p_data->write.len);
629	#endif
630	                } else {
631	                    //TODO:
632	                }
633	            } else if ((p_data->write.is_prep == true) && (res == SPP_IDX_SPP_DATA_RECV_VAL)) {
634	                store_wr_buffer(p_data);
635	            }
636	      	 	break;
637	    	}
638	    	case ESP_GATTS_EXEC_WRITE_EVT:
639	            /* End of prepared-write transaction: print on EXEC, then always release queued chunks
640	             * (master only freed on EXEC, which leaked on CANCEL). */
641	            ESP_LOGI(GATTS_TABLE_TAG, "Execute write flag 0x%02x", p_data->exec_write.exec_write_flag);
