655	                ESP_LOGI(GATTS_TABLE_TAG, "Confirm received, status %d, handle %d", param->conf.status, param->conf.handle);
656	            }
657	    	    break;
658	    	case ESP_GATTS_UNREG_EVT:
659	        	break;
660	    	case ESP_GATTS_DELETE_EVT:
661	        	break;
662	    	case ESP_GATTS_START_EVT:
663	            ESP_LOGI(GATTS_TABLE_TAG, "Service start, status %d, service_handle %d",
664	                 param->start.status, param->start.service_handle);
665	        	break;
666	    	case ESP_GATTS_STOP_EVT:
667	        	break;
668	    	case ESP_GATTS_CONNECT_EVT:
669	            ESP_LOGI(GATTS_TABLE_TAG, "Connected, conn_id %u, remote "ESP_BD_ADDR_STR"",
