676	#ifdef SUPPORT_HEARTBEAT
677	    	    uint32_t cmd = 0;
678	            xQueueSend(cmd_heartbeat_queue, &cmd, 10 / portTICK_PERIOD_MS);
679	#endif
680	        	break;
681	    	case ESP_GATTS_DISCONNECT_EVT:
682	            ESP_LOGI(GATTS_TABLE_TAG, "Disconnected, remote "ESP_BD_ADDR_STR", reason 0x%02x",
