691	#endif
692	    	    esp_ble_gap_start_advertising(&spp_adv_params);
693	    	    break;
694	    	case ESP_GATTS_OPEN_EVT:
695	    	    break;
696	    	case ESP_GATTS_CANCEL_OPEN_EVT:
697	    	    break;
698	    	case ESP_GATTS_CLOSE_EVT:
