725	static void gatts_event_handler(esp_gatts_cb_event_t event, esp_gatt_if_t gatts_if, esp_ble_gatts_cb_param_t *param)
726	{
727	    /* If event is register event, store the gatts_if for each profile */
728	    if (event == ESP_GATTS_REG_EVT) {
729	        if (param->reg.status == ESP_GATT_OK) {
730	            spp_profile_tab[SPP_PROFILE_APP_IDX].gatts_if = gatts_if;
731	        } else {
732	            ESP_LOGI(GATTS_TABLE_TAG, "Reg app failed, app_id %04x, status %d",param->reg.app_id, param->reg.status);
733	            return;
734	        }
735	    }
736	
737	    do {
738	        int idx;
739	        for (idx = 0; idx < SPP_PROFILE_NUM; idx++) {
740	            if (gatts_if == ESP_GATT_IF_NONE || /* ESP_GATT_IF_NONE, not specify a certain gatt_if, need to call every profile cb function */
741	                    gatts_if == spp_profile_tab[idx].gatts_if) {
742	                if (spp_profile_tab[idx].gatts_cb) {
743	                    spp_profile_tab[idx].gatts_cb(event, gatts_if, param);
744	                }
745	            }
746	        }
747	    } while (0);
748	}
