/*
 * ESP-IDF entry point
 * 以太网 + 摄像头 + BLE：开机初始化以太网 → 摄像头 → BLE(ESP-Hosted) → TCP Server
 *
 * 流程：PSRAM → 以太网 → 摄像头 → BLE → TCP Server → 等命令
 * 电脑/手机通过 BLE 或 TCP 发送命令
 */
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_psram.h"
#include "esp_heap_caps.h"
#include "esp_log.h"
#include "esp_err.h"
#include "DEV_Config.h"
