#include "jpeg_encoder.h"
#include "eth_init.h"
#include "tcp_server.h"

/* ESP-Hosted (P4 通过 SDIO 控制 C6 的 WiFi/BLE) */
#include "esp_hosted.h"
#include "esp_wifi.h"
#include "esp_bt.h"
#include "esp_bt_main.h"
#include "esp_gap_ble_api.h"

static const char *TAG = "main";

/* 全局摄像头句柄 */
cam_capture_t g_cam;

/* ---- BLE SPP 服务配置 ---- */
#define SPP_SERVER_NAME    "ESP_SPP_SERVER"
#define SPP_SERVICE_UUID   0xABF0

/* BLE GATT 服务声明 */
static esp_gatts_if_t gatts_if = ESP_GATT_IF_NONE;
static uint16_t conn_id = 0;
static uint16_t char_handle = 0;
static bool is_connected = false;

/* SPP 服务 UUID */
static esp_bt_uuid_t spp_service_uuid = {
    .len = ESP_UUID_LEN_16,
    .uuid = {.uuid16 = SPP_SERVICE_UUID},
};

/* 特征值 UUID */
static esp_bt_uuid_t spp_char_uuid = {
    .len = ESP_UUID_LEN_16,
    .uuid = {.uuid16 = 0xABF1},
};

/* GAP 回调 */
static void gap_event_handler(esp_gap_ble_cb_event_t event, esp_ble_gap_cb_param_t *param)
{
    switch (event) {
    case ESP_GAP_BLE_ADV_START_COMPLETE_EVT:
        if (param->adv_start_cmpl.status != ESP_BT_STATUS_SUCCESS) {
            ESP_LOGE(TAG, "BLE 广播启动失败");
        } else {
            ESP_LOGI(TAG, "BLE 广播已启动");
        }
        break;
    case ESP_GAP_BLE_UPDATE_CONN_PARAMS_EVT:
        ESP_LOGI(TAG, "BLE 连接参数更新: status=%d", param->update_conn_params.status);
        break;
    default:
        break;
    }
}

/* GATTS 回调 */
static void gatts_event_handler(esp_gatts_cb_event_t event, esp_gatt_if_t gatts_if_param,
                                esp_ble_gatts_cb_param_t *param)
{
    switch (event) {
    case ESP_GATTS_REG_EVT:
        ESP_LOGI(TAG, "GATTS 注册: app_id=%d, gatts_if=%d", param->reg.app_id, gatts_if_param);
        gatts_if = gatts_if_param;

        /* 创建服务 */
        esp_ble_gatts_create_service(gatts_if, &spp_service_uuid, 4);
        break;

    case ESP_GATTS_CREATE_EVT:
        ESP_LOGI(TAG, "服务创建成功: handle=%d", param->create.service_handle);

        /* 添加特征值 */
        esp_ble_gatts_add_char(param->create.service_handle, &spp_char_uuid,
                               ESP_GATT_PERM_READ | ESP_GATT_PERM_WRITE,
                               ESP_GATT_CHAR_PROP_BIT_READ | ESP_GATT_CHAR_PROP_BIT_WRITE |
                               ESP_GATT_CHAR_PROP_BIT_NOTIFY,
                               NULL, NULL);
        break;

    case ESP_GATTS_ADD_CHAR_EVT:
        ESP_LOGI(TAG, "特征值添加成功: handle=%d", param->add_char.attr_handle);
        char_handle = param->add_char.attr_handle;

        /* 开始广播 */
        esp_ble_adv_params_t adv_params = {
            .adv_int_min = 0x20,
            .adv_int_max = 0x40,
            .adv_type = ADV_TYPE_IND,
            .own_addr_type = BLE_ADDR_TYPE_PUBLIC,
            .channel_map = ADV_CHNL_ALL,
            .adv_filter_policy = ADV_FILTER_ALLOW_SCAN_ANY_CON_ANY,
        };
        esp_ble_gap_set_device_name(SPP_SERVER_NAME);
        esp_ble_gap_config_adv_data_raw(NULL, 0);
        esp_ble_gap_start_advertising(&adv_params);
        break;

    case ESP_GATTS_CONNECT_EVT:
        ESP_LOGI(TAG, "BLE 设备连接: conn_id=%d", param->connect.conn_id);
        conn_id = param->connect.conn_id;
        is_connected = true;
        break;

    case ESP_GATTS_DISCONNECT_EVT:
        ESP_LOGI(TAG, "BLE 设备断开");
        is_connected = false;
        /* 重新广播 */
        esp_ble_gap_start_advertising(&adv_params);
        break;

    case ESP_GATTS_WRITE_EVT:
        if (param->write.handle == char_handle) {
            ESP_LOGI(TAG, "收到 BLE 数据: %d 字节", param->write.len);
            ESP_LOG_BUFFER_HEX(TAG, param->write.value, param->write.len);

            /* 回显数据（发送通知） */
            if (is_connected) {
                esp_ble_gatts_send_indicate(gatts_if, conn_id, char_handle,
                                           param->write.len, param->write.value, false);
            }
        }
        break;

    default:
        break;
    }
}

/* ---- BLE 初始化 ---- */
static void ble_init(void)
{
    ESP_LOGI(TAG, "初始化 BLE (ESP-Hosted)...");

    /* 释放经典蓝牙内存（只用 BLE） */
    ESP_ERROR_CHECK(esp_bt_controller_mem_release(ESP_BT_MODE_CLASSIC_BT));

    /* BT 控制器配置 */
    esp_bt_controller_config_t bt_cfg = BT_CONTROLLER_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_bt_controller_init(&bt_cfg));
    ESP_ERROR_CHECK(esp_bt_controller_enable(ESP_BT_MODE_BLE));

    /* Bluedroid 初始化 */
    ESP_ERROR_CHECK(esp_bluedroid_init());
    ESP_ERROR_CHECK(esp_bluedroid_enable());

    /* 注册回调 */
    ESP_ERROR_CHECK(esp_ble_gatts_register_callback(gatts_event_handler));
    ESP_ERROR_CHECK(esp_ble_gap_register_callback(gap_event_handler));

    /* 注册 GATT 服务应用 */
    ESP_ERROR_CHECK(esp_ble_gatts_app_register(0));

    /* 配置 GAP 安全参数 */
    esp_ble_auth_req_t auth_req = ESP_LE_AUTH_REQ_SC_MITM_BONDING;
    esp_ble_gap_set_security_param(ESP_BLE_SM_AUTHEN_REQ_MODE, &auth_req, sizeof(auth_req));

    ESP_LOGI(TAG, "BLE 初始化完成");
}

extern "C" void app_main(void)
{
    /* ---- PSRAM ---- */
    size_t psram_size = esp_psram_get_size();
    ESP_LOGI(TAG, "PSRAM: %u bytes (%.1f MB)", psram_size, psram_size / 1048576.0);
    if (psram_size == 0) {
        ESP_LOGE(TAG, "PSRAM 未初始化！");
        return;
    }

    /* ---- 墨水屏 GPIO（保留，后续集显示用）---- */
    DEV_Module_Init();

    /* ---- ESP-Hosted (P4 ↔ C6 SDIO) ---- */
    ESP_LOGI(TAG, "初始化 ESP-Hosted (SDIO)...");
    esp_err_t ret = esp_hosted_init();
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "ESP-Hosted 初始化失败: %s", esp_err_to_name(ret));
    }

    /* ---- 以太网 ---- */
    ESP_LOGI(TAG, "初始化以太网...");
    esp_err_t e = eth_init_and_wait_ip(30000);  /* 30 秒超时 */
    if (e != ESP_OK) {
        ESP_LOGW(TAG, "以太网未获取 IP，但继续启动摄像头+TCP（可用于调试）");
    }

    /* ---- 摄像头 ---- */
    ESP_LOGI(TAG, "初始化摄像头...");
    e = cam_capture_init(&g_cam);
    if (e != ESP_OK) {
        ESP_LOGE(TAG, "摄像头初始化失败[%d]", e);
    }

    /* ---- BLE ---- */
    ble_init();

    /* ---- TCP Server ---- */
    if (e == ESP_OK) {
        ESP_LOGI(TAG, "启动 TCP Server...");
        tcp_server_start(&g_cam);
    }

    ESP_LOGI(TAG, "系统就绪");
    ESP_LOGI(TAG, "BLE 设备名: %s", SPP_SERVER_NAME);
    ESP_LOGI(TAG, "用 capture_tcp.py 连接拍照:");
    ESP_LOGI(TAG, "  python tools/capture_tcp.py --ip <P4的IP> --port 8080");
}

