/*
 * ESP-IDF entry point
 * 摄像头打通：SC2336 拍照 → JPEG 压缩 → 串口传回电脑
 *
 * 流程：PSRAM 检查 → 摄像头初始化 → 启动串口命令监听
 * 电脑发 CMD_CAPTURE(0x05) → P4 拍照+编码 → 回传 CMD_CAPTURE_JPG(0x06)
 */
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_psram.h"
#include "esp_heap_caps.h"
#include "esp_log.h"
#include "esp_err.h"
#include "DEV_Config.h"
#include "camera_capture.h"
#include "epd_protocol.h"

static const char *TAG = "main";

/* 全局，供 epd_protocol 的 rx_task 访问 */
cam_capture_t g_cam;

extern "C" void app_main(void)
{
    /* ---- PSRAM 状态检查 ---- */
    size_t psram_size = esp_psram_get_size();
    size_t free_psram = heap_caps_get_free_size(MALLOC_CAP_SPIRAM);
    ESP_LOGI(TAG, "=== PSRAM 状态 ===");
    ESP_LOGI(TAG, "PSRAM 总量: %u bytes (%.1f MB)", psram_size, psram_size / 1048576.0);
    ESP_LOGI(TAG, "PSRAM 可用: %u bytes (%.1f MB)", free_psram, free_psram / 1048576.0);
    if (psram_size == 0) {
        ESP_LOGE(TAG, "!! PSRAM 未初始化，摄像头需要 PSRAM !!");
    }

    /* ---- 墨水屏 GPIO 初始化（不影响摄像头，保留以便后续集成）---- */
    DEV_Module_Init();

    /* ---- 摄像头初始化 ---- */
    ESP_LOGI(TAG, "初始化摄像头...");
    esp_err_t ret = cam_capture_init(&g_cam);
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "摄像头初始化失败[%d]，但继续启动协议任务", ret);
        /* 不 return，让协议任务起来，至少能看日志 */
    }

    /* ---- 启动串口命令监听 ---- */
    epd_protocol_start(115200);

    ESP_LOGI(TAG, "系统就绪，等串口 CMD_CAPTURE(0x05) 触发拍照");
    /* main_task 退出，rx_task 继续运行 */
}

