96	        ESP_LOGE(TAG, "CSI new fail[%d]", ret);
97	        return ret;
98	    }
99	
100	    esp_cam_ctlr_evt_cbs_t cbs = {
101	        .on_get_new_trans = s_get_new_vb,
102	        .on_trans_finished = s_trans_finished,
103	    };
104	    ret = esp_cam_ctlr_register_event_callbacks(cam->csi, &cbs, &cam->trans);
105	    if (ret != ESP_OK) {
106	        ESP_LOGE(TAG, "CSI callback fail[%d]", ret);
107	        return ret;
108	    }
109	    ret = esp_cam_ctlr_enable(cam->csi);
110	    if (ret != ESP_OK) {
111	        ESP_LOGE(TAG, "CSI enable fail[%d]", ret);
112	        return ret;
113	    }
114	
115	    /* 5. ISP（RAW8→RGB565，做 demaic）*/
116	    esp_isp_processor_cfg_t isp_cfg;
117	    memset(&isp_cfg, 0, sizeof(isp_cfg));
118	    isp_cfg.clk_hz = 80 * 1000 * 1000;
119	    isp_cfg.input_data_source = ISP_INPUT_DATA_SOURCE_CSI;
120	    isp_cfg.input_data_color_type = ISP_COLOR_RAW8;
121	    isp_cfg.output_data_color_type = ISP_COLOR_RGB565;
122	    isp_cfg.has_line_start_packet = false;
123	    isp_cfg.has_line_end_packet = false;
124	    isp_cfg.h_res = CAM_HRES;
125	    isp_cfg.v_res = CAM_VRES;
126	    ret = esp_isp_new_processor(&isp_cfg, &cam->isp);
127	    if (ret != ESP_OK) {
128	        ESP_LOGE(TAG, "ISP new fail[%d]", ret);
129	        return ret;
130	    }
131	    ret = esp_isp_enable(cam->isp);
132	    if (ret != ESP_OK) {
133	        ESP_LOGE(TAG, "ISP enable fail[%d]", ret);
134	        return ret;
135	    }
136	
137	    /* 6. 最后才 start CSI */
138	    ret = esp_cam_ctlr_start(cam->csi);
139	    if (ret != ESP_OK) {
140	        ESP_LOGE(TAG, "CSI start fail[%d]", ret);
141	        return ret;
142	    }
143	
144	    ESP_LOGI(TAG, "摄像头初始化完成 %dx%d RGB565", CAM_HRES, CAM_VRES);
145	    return ESP_OK;
146	}
