148	esp_err_t cam_capture_one_frame(cam_capture_t *cam, uint8_t **out_fb, size_t *out_len)
149	{
150	    if (!cam || !cam->csi) return ESP_ERR_INVALID_STATE;
151	
152	    /* 每次拍照做完整 teardown + rebuild，彻底避免 CSI 第二次阻塞 */
153	    /* 1. 停止 */
154	    esp_cam_ctlr_stop(cam->csi);
155	    esp_cam_ctlr_disable(cam->csi);
156	    esp_isp_disable(cam->isp);
157	
158	    /* 2. 重建 ISP + CSI */
159	    esp_isp_enable(cam->isp);
160	    esp_cam_ctlr_enable(cam->csi);
161	
162	    /* 3. 用全新 trans（局部变量），避免旧 buffer 残留 */
163	    esp_cam_ctlr_trans_t local_trans;
164	    memset(&local_trans, 0, sizeof(local_trans));
165	    local_trans.buffer = cam->frame_buffer;
166	    local_trans.buflen = CAM_FB_SIZE;
167	
168	    esp_cam_ctlr_evt_cbs_t cbs = {
169	        .on_get_new_trans = s_get_new_vb,
170	        .on_trans_finished = s_trans_finished,
171	    };
172	    esp_cam_ctlr_register_event_callbacks(cam->csi, &cbs, &local_trans);
173	
174	    esp_cam_ctlr_start(cam->csi);
175	
176	    /* 4. 收一帧（5 秒超时）*/
177	    esp_err_t ret = esp_cam_ctlr_receive(cam->csi, &local_trans, pdMS_TO_TICKS(5000));
178	    if (ret != ESP_OK) {
179	        ESP_LOGE(TAG, "receive fail[%d]", ret);
180	        return ret;
181	    }
182	
183	    /* cache invalidate：CSI DMA 写 PSRAM 后，CPU 读前必须同步，否则读到旧值 */
184	    esp_cache_msync(cam->frame_buffer, CAM_FB_SIZE, ESP_CACHE_MSYNC_FLAG_DIR_M2C);
185	
186	    *out_fb = (uint8_t *)cam->frame_buffer;
187	    *out_len = CAM_FB_SIZE;
188	    return ESP_OK;
189	}
190	
191	esp_err_t cam_capture_deinit(cam_capture_t *cam)
192	{
193	    if (cam->csi) {
194	        esp_cam_ctlr_stop(cam->csi);
195	        esp_cam_ctlr_disable(cam->csi);
196	        esp_cam_ctlr_del(cam->csi);
197	    }
198	    if (cam->isp) {
199	        esp_isp_disable(cam->isp);
200	        esp_isp_del_processor(cam->isp);
201	    }
202	    if (cam->sensor.sccb_handle) {
203	        example_sensor_deinit(cam->sensor);
204	    }
205	    if (cam->frame_buffer) {
206	        heap_caps_free(cam->frame_buffer);
207	    }
208	    if (cam->ldo) {
209	        esp_ldo_release_channel(cam->ldo);
210	    }
211	    memset(cam, 0, sizeof(*cam));
212	    return ESP_OK;
213	}
