180	
181	    /* 停止 CSI，避免连续抓帧 */
182	    esp_cam_ctlr_stop(cam->csi);
183	
184	    /* cache invalidate：CSI DMA 写 PSRAM 后，CPU 读前必须同步，否则读到旧值 */
185	    esp_cache_msync(cam->frame_buffer, CAM_FB_SIZE, ESP_CACHE_MSYNC_FLAG_DIR_M2C);
186	
187	    *out_fb = (uint8_t *)cam->frame_buffer;
188	    *out_len = CAM_FB_SIZE;
189	    return ESP_OK;
