155	static void i2s_music(void *args)
156	{
157	    esp_err_t ret = ESP_OK;
158	    size_t bytes_write = 0;
159	    uint8_t *data_ptr = (uint8_t *)music_pcm_start;
160	
161	    /* (Optional) Disable TX channel and preload the data before enabling the TX channel,
162	     * so that the valid data can be transmitted immediately */
163	    ESP_ERROR_CHECK(i2s_channel_disable(tx_handle));
164	    ESP_ERROR_CHECK(i2s_channel_preload_data(tx_handle, data_ptr, music_pcm_end - data_ptr, &bytes_write));
165	    data_ptr += bytes_write;  // Move forward the data pointer
166	
167	    /* Enable the TX channel */
168	    ESP_ERROR_CHECK(i2s_channel_enable(tx_handle));
169	    while (1) {
170	        /* Write music to earphone */
171	        ret = i2s_channel_write(tx_handle, data_ptr, music_pcm_end - data_ptr, &bytes_write, portMAX_DELAY);
172	        if (ret != ESP_OK) {
173	            /* Since we set timeout to 'portMAX_DELAY' in 'i2s_channel_write'
174	               so you won't reach here unless you set other timeout value,
175	               if timeout detected, it means write operation failed. */
176	            ESP_LOGE(TAG, "[music] i2s write failed, %s", err_reason[ret == ESP_ERR_TIMEOUT]);
177	            abort();
178	        }
179	        if (bytes_write > 0) {
180	            ESP_LOGI(TAG, "[music] i2s music played, %d bytes are written.", bytes_write);
181	        } else {
182	            ESP_LOGE(TAG, "[music] i2s music play failed.");
183	            abort();
184	        }
185	        data_ptr = (uint8_t *)music_pcm_start;
186	        vTaskDelay(1000 / portTICK_PERIOD_MS);
187	    }
188	    vTaskDelete(NULL);
189	}
