200	    size_t bytes_read = 0;
201	    size_t bytes_write = 0;
202	    ESP_LOGI(TAG, "[echo] Echo start");
203	
204	    while (1) {
205	        memset(mic_data, 0, EXAMPLE_RECV_BUF_SIZE);
206	        /* Read sample data from mic */
207	        ret = i2s_channel_read(rx_handle, mic_data, EXAMPLE_RECV_BUF_SIZE, &bytes_read, 1000);
208	        if (ret != ESP_OK) {
209	            ESP_LOGE(TAG, "[echo] i2s read failed, %s", err_reason[ret == ESP_ERR_TIMEOUT]);
210	            abort();
211	        }
212	        /* Write sample data to earphone */
213	        ret = i2s_channel_write(tx_handle, mic_data, EXAMPLE_RECV_BUF_SIZE, &bytes_write, 1000);
214	        if (ret != ESP_OK) {
215	            ESP_LOGE(TAG, "[echo] i2s write failed, %s", err_reason[ret == ESP_ERR_TIMEOUT]);
216	            abort();
217	        }
218	        if (bytes_read != bytes_write) {
219	            ESP_LOGW(TAG, "[echo] %d bytes read but only %d bytes are written", bytes_read, bytes_write);
220	        }
221	    }
222	    vTaskDelete(NULL);
223	}
