static esp_err_t i2s_driver_init(void)
{
    i2s_chan_config_t chan_cfg = I2S_CHANNEL_DEFAULT_CONFIG(ES8311_I2S_PORT, I2S_ROLE_MASTER);
    chan_cfg.auto_clear = true;
    ESP_RETURN_ON_ERROR(i2s_new_channel(&chan_cfg, &s_tx_handle, &s_rx_handle),
                        TAG, "i2s new channel fail");
    i2s_std_config_t std_cfg = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(ES8311_SAMPLE_RATE),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(ES8311_BITS_PER_SAMPLE, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {
            .mclk = ES8311_I2S_MCLK_IO,
            .bclk = ES8311_I2S_BCLK_IO,
            .ws   = ES8311_I2S_WS_IO,
            .dout = ES8311_I2S_DOUT_IO,
            .din  = ES8311_I2S_DIN_IO,
            .invert_flags = {
                .mclk_inv = false,
                .bclk_inv = false,
                .ws_inv   = false,
            },
        },
    };
    std_cfg.clk_cfg.mclk_multiple = I2S_MCLK_MULTIPLE_384;

    ESP_RETURN_ON_ERROR(i2s_channel_init_std_mode(s_tx_handle, &std_cfg),
                        TAG, "i2s tx init fail");
    ESP_RETURN_ON_ERROR(i2s_channel_init_std_mode(s_rx_handle, &std_cfg),
                        TAG, "i2s rx init fail");
    ESP_RETURN_ON_ERROR(i2s_channel_enable(s_tx_handle), TAG, "i2s tx enable fail");
    ESP_RETURN_ON_ERROR(i2s_channel_enable(s_rx_handle), TAG, "i2s rx enable fail");
    return ESP_OK;
}

static esp_err_t es8311_codec_init_internal(void)
{
    /* 复用摄像头已创建的 I2C_NUM_0 总线，不再新建 */
    i2c_master_bus_handle_t i2c_bus_handle = NULL;
    ESP_RETURN_ON_ERROR(i2c_master_get_bus_handle(ES8311_I2C_PORT, &i2c_bus_handle),
                        TAG, "获取 I2C 总线句柄失败，确保 cam_capture_init() 先执行");

    /* I2C 控制接口 */
    audio_codec_i2c_cfg_t i2c_cfg = {
        .port = ES8311_I2C_PORT,
        .addr = ES8311_CODEC_DEFAULT_ADDR,
        .bus_handle = i2c_bus_handle,
    };
    const audio_codec_ctrl_if_t *ctrl_if = audio_codec_new_i2c_ctrl(&i2c_cfg);
    ESP_RETURN_ON_FALSE(ctrl_if, ESP_FAIL, TAG, "i2c ctrl if fail");

    /* I2S 数据接口 */
    audio_codec_i2s_cfg_t i2s_cfg = {
        .port = ES8311_I2S_PORT,
        .rx_handle = s_rx_handle,
        .tx_handle = s_tx_handle,
    };
    const audio_codec_data_if_t *data_if = audio_codec_new_i2s_data(&i2s_cfg);
    ESP_RETURN_ON_FALSE(data_if, ESP_FAIL, TAG, "i2s data if fail");

    /* GPIO 接口（PA 控制）*/
    const audio_codec_gpio_if_t *gpio_if = audio_codec_new_gpio();
    ESP_RETURN_ON_FALSE(gpio_if, ESP_FAIL, TAG, "gpio if fail");

    /* ES8311 配置 */
    es8311_codec_cfg_t es8311_cfg = {
        .ctrl_if = ctrl_if,
        .gpio_if = gpio_if,
        .codec_mode = ESP_CODEC_DEV_WORK_MODE_BOTH,
        .master_mode = false,
        .use_mclk = ES8311_I2S_MCLK_IO >= 0,
        .pa_pin = ES8311_PA_CTRL_IO,
        .pa_reverted = false,
        .hw_gain = {
            .pa_voltage = 5.0,
            .codec_dac_voltage = 3.3,
        },
        .mclk_div = 384,
    };
    const audio_codec_if_t *es8311_if = es8311_codec_new(&es8311_cfg);
    ESP_RETURN_ON_FALSE(es8311_if, ESP_FAIL, TAG, "es8311 new fail");

    esp_codec_dev_cfg_t dev_cfg = {
        .dev_type = ESP_CODEC_DEV_TYPE_IN_OUT,
        .codec_if = es8311_if,
        .data_if = data_if,
    };
    s_codec_handle = esp_codec_dev_new(&dev_cfg);
    ESP_RETURN_ON_FALSE(s_codec_handle, ESP_FAIL, TAG, "codec dev new fail");

    esp_codec_dev_sample_info_t sample_cfg = {
        .bits_per_sample = ES8311_BITS_PER_SAMPLE,
        .channel = ES8311_CHANNELS,
        .channel_mask = 0x03,
        .sample_rate = ES8311_SAMPLE_RATE,
    };
    if (esp_codec_dev_open(s_codec_handle, &sample_cfg) != ESP_CODEC_DEV_OK) {
        ESP_LOGE(TAG, "codec open fail");
        return ESP_FAIL;
    }
    esp_codec_dev_set_out_vol(s_codec_handle, 60);
    return ESP_OK;
}

esp_err_t es8311_codec_init(void)
{
    ESP_RETURN_ON_ERROR(i2s_driver_init(), TAG, "I2S driver init fail");
    ESP_RETURN_ON_ERROR(es8311_codec_init_internal(), TAG, "ES8311 codec init fail");
    ESP_LOGI(TAG, "ES8311 初始化完成 %dHz/%dbit/%dch",
             ES8311_SAMPLE_RATE, ES8311_BITS_PER_SAMPLE, ES8311_CHANNELS);
    return ESP_OK;
}

esp_err_t es8311_play_tone(int freq_hz, int duration_ms)
{
    if (!s_tx_handle) return ESP_ERR_INVALID_STATE;

    /* 一帧缓冲：每个采样 = 2字节×2声道 = 4字节，取 1024 采样 = 4096 字节 */
    const int samples_per_frame = 1024;
    const int frame_bytes = samples_per_frame * 4;
    int16_t *buf = malloc(frame_bytes);
    if (!buf) return ESP_ERR_NO_MEM;

    /* 正弦波步进：每个采样在 256 点查表中的位置增量
     * 增量 = 256 * freq / sample_rate */
    int step = 256 * freq_hz / ES8311_SAMPLE_RATE;
    if (step < 1) step = 1;
    int phase = 0;
    int total_samples = ES8311_SAMPLE_RATE * duration_ms / 1000;
    int written = 0;

    while (written < total_samples) {
        int n = samples_per_frame;
        if (written + n > total_samples) n = total_samples - written;

        for (int i = 0; i < n; i++) {
            int16_t sample = s_sin_table[phase & 0xFF];
            buf[i * 2]     = sample;  /* 左声道 */
            buf[i * 2 + 1] = sample;  /* 右声道 */
            phase += step;
        }
        size_t bytes_write = 0;
        esp_err_t ret = i2s_channel_write(s_tx_handle, buf, n * 4, &bytes_write, 1000);
        if (ret != ESP_OK) {
            free(buf);
            ESP_LOGE(TAG, "tone write fail[%d]", ret);
            return ret;
        }
        written += n;
    }

    free(buf);
    return ESP_OK;
}

esp_err_t es8311_play_pcm(const uint8_t *data, size_t len)
{
    if (!s_tx_handle || !data || len == 0) return ESP_ERR_INVALID_ARG;

    size_t offset = 0;
    while (offset < len) {
        size_t chunk = len - offset;
        if (chunk > 4096) chunk = 4096;
        size_t bytes_write = 0;
        esp_err_t ret = i2s_channel_write(s_tx_handle, data + offset, chunk, &bytes_write, 2000);
        if (ret != ESP_OK) {
            ESP_LOGE(TAG, "pcm write fail[%d]", ret);
            return ret;
        }
        offset += bytes_write;
    }
    return ESP_OK;
}

