esp_err_t es8311_play_tone(int freq_hz, int duration_ms)
{
    if (!s_tx_handle) return ESP_ERR_INVALID_STATE;

    /* 一帧缓冲：每个采样 = 2字节×2声道 = 4字节，取 1024 采样 = 4096 字节 */
    const int samples_per_frame = 1024;
    const int frame_bytes = samples_per_frame * 4;
    int16_t *buf = malloc(frame_bytes);
    if (!buf) return ESP_ERR_NO_MEM;

    int total_samples = ES8311_SAMPLE_RATE * duration_ms / 1000;
    int written = 0;
    float phase = 0.0f;
    float phase_step = 2.0f * 3.14159265f * freq_hz / ES8311_SAMPLE_RATE;

    while (written < total_samples) {
        int n = samples_per_frame;
        if (written + n > total_samples) n = total_samples - written;

        for (int i = 0; i < n; i++) {
            int16_t sample = (int16_t)(sinf(phase) * 32767.0f);
            buf[i * 2]     = sample;  /* 左声道 */
            buf[i * 2 + 1] = sample;  /* 右声道 */
            phase += phase_step;
        }
        size_t bytes_write = 0;
        esp_err_t ret = i2s_channel_write(s_tx_handle, buf, n * 4, &bytes_write, 1000);
        if (ret != ESP_OK) {
            free(buf);
            ESP_LOGE(TAG, "tone write fail[%d]", ret);
            return ret;
        }
        written += n;
    }

    free(buf);
    return ESP_OK;
}

