139	esp_err_t es8311_play_tone(int freq_hz, int duration_ms)
140	{
141	    if (!s_tx_handle) return ESP_ERR_INVALID_STATE;
142	
143	    /* 一帧缓冲：每个采样 = 2字节×2声道 = 4字节，取 1024 采样 = 4096 字节 */
144	    const int samples_per_frame = 1024;
145	    const int frame_bytes = samples_per_frame * 4;
146	    int16_t *buf = malloc(frame_bytes);
147	    if (!buf) return ESP_ERR_NO_MEM;
148	
149	    int total_samples = ES8311_SAMPLE_RATE * duration_ms / 1000;
150	    int written = 0;
151	    float phase = 0.0f;
152	    float phase_step = 2.0f * 3.14159265f * freq_hz / ES8311_SAMPLE_RATE;
153	
154	    while (written < total_samples) {
155	        int n = samples_per_frame;
156	        if (written + n > total_samples) n = total_samples - written;
157	
158	        for (int i = 0; i < n; i++) {
159	            int16_t sample = (int16_t)(sinf(phase) * 32767.0f);
160	            buf[i * 2]     = sample;  /* 左声道 */
161	            buf[i * 2 + 1] = sample;  /* 右声道 */
162	            phase += phase_step;
163	        }
164	        size_t bytes_write = 0;
165	        esp_err_t ret = i2s_channel_write(s_tx_handle, buf, n * 4, &bytes_write, 1000);
166	        if (ret != ESP_OK) {
167	            free(buf);
168	            ESP_LOGE(TAG, "tone write fail[%d]", ret);
169	            return ret;
170	        }
171	        written += n;
172	    }
173	
174	    free(buf);
175	    return ESP_OK;
176	}
177	
178	esp_err_t es8311_play_pcm(const uint8_t *data, size_t len)
179	{
180	    if (!s_tx_handle || !data || len == 0) return ESP_ERR_INVALID_ARG;
181	
182	    size_t offset = 0;
183	    while (offset < len) {
184	        size_t chunk = len - offset;
185	        if (chunk > 4096) chunk = 4096;
186	        size_t bytes_write = 0;
187	        esp_err_t ret = i2s_channel_write(s_tx_handle, data + offset, chunk, &bytes_write, 2000);
188	        if (ret != ESP_OK) {
189	            ESP_LOGE(TAG, "pcm write fail[%d]", ret);
190	            return ret;
191	        }
192	        offset += bytes_write;
193	    }
194	    return ESP_OK;
195	}
