static void EPD_3IN5G_V2_ReadBusyH(void)
{
    Debug("e-Paper busy H\r\n");
    /* 注意：FreeRTOS tick 是 100Hz(10ms)，delay 必须 >=10ms 才真正休眠；
     * 用 5ms 会变成 vTaskDelay(0) 空转，饿死 IDLE0 触发 task watchdog */
    while(!DEV_Digital_Read(EPD_BUSY_PIN)) {      //LOW: idle, HIGH: busy
        DEV_Delay_ms(10);
    }
    Debug("e-Paper busy H release\r\n");
}

