294	                }
295	                i2s_pdm_rx_slot_config_t slot_cfg = I2S_PDM_RX_SLOT_DEFAULT_CONFIG(slot_bits, I2S_SLOT_MODE_STEREO);
296	                i2s_pdm_slot_mask_t slot_mask = fs->channel_mask ? (i2s_pdm_slot_mask_t)fs->channel_mask : I2S_PDM_SLOT_BOTH;
297	                // Stereo channel mask is ignored in driver, need use mono instead
298	                if (fs->channel_mask && fs->channel_mask < 3) {
299	                    slot_cfg.slot_mode = I2S_SLOT_MODE_MONO;
300	                }
301	                slot_cfg.slot_mask = slot_mask;
302	                if (slot_bits > fs->bits_per_sample) {
303	                    slot_cfg.data_bit_width = fs->bits_per_sample;
304	                    slot_cfg.slot_bit_width = slot_bits;
305	                }
306	                ret = i2s_channel_reconfig_pdm_rx_clock(channel, &clk_cfg);
307	                if (ret != ESP_OK) {
308	                    return ESP_CODEC_DEV_DRV_ERR;
309	                }
310	                ret = i2s_channel_reconfig_pdm_rx_slot(channel, &slot_cfg);
311	                if (ret != ESP_OK) {
312	                    return ESP_CODEC_DEV_DRV_ERR;
313	                }
314	                ESP_LOGI(TAG, "PDM RX mode, data_bit: %d, slot_bit: %d, sample_rate: %d, slot_mask: 0x%x",
315	                         fs->bits_per_sample, slot_bits, (int)fs->sample_rate, (int)fs->channel_mask);
316	#else
317	                ESP_LOGE(TAG, "PDM RX not supported");
318	                return ESP_CODEC_DEV_NOT_SUPPORT;
319	#endif  /* SOC_I2S_SUPPORTS_PDM_RX */
320	            } else {
321	#if SOC_I2S_SUPPORTS_PDM_TX
322	                i2s_pdm_tx_clk_config_t clk_cfg = I2S_PDM_TX_CLK_DEFAULT_CONFIG(fs->sample_rate);
323	                if (clk_src) {
324	                    clk_cfg.clk_src = clk_src;
325	                }
326	                if (fs->mclk_multiple) {
327	                    clk_cfg.mclk_multiple = fs->mclk_multiple;
328	                }
329	                clk_cfg.up_sample_fs = fs->sample_rate / 100;
330	                i2s_pdm_tx_slot_config_t slot_cfg = I2S_PDM_TX_SLOT_DEFAULT_CONFIG(slot_bits, I2S_SLOT_MODE_STEREO);
331	                // Stereo channel mask is ignored, need use mono instead
332	                if (fs->channel_mask && fs->channel_mask < 3) {
333	                    slot_cfg.slot_mode = I2S_SLOT_MODE_MONO;
334	                }
335	#if SOC_I2S_HW_VERSION_1
336	                i2s_pdm_slot_mask_t slot_mask = fs->channel_mask ?
337	                        (i2s_pdm_slot_mask_t) fs->channel_mask : I2S_PDM_SLOT_BOTH;
338	                slot_cfg.slot_mask = slot_mask;
339	#endif  /* SOC_I2S_HW_VERSION_1 */
340	                if (slot_bits > fs->bits_per_sample) {
341	                    slot_cfg.data_bit_width = fs->bits_per_sample;
342	                    slot_cfg.slot_bit_width = slot_bits;
343	                }
344	                ret = i2s_channel_reconfig_pdm_tx_clock(channel, &clk_cfg);
345	                if (ret != ESP_OK) {
346	                    return ESP_CODEC_DEV_DRV_ERR;
347	                }
348	                ret = i2s_channel_reconfig_pdm_tx_slot(channel, &slot_cfg);
349	                if (ret != ESP_OK) {
350	                    return ESP_CODEC_DEV_DRV_ERR;
351	                }
352	                ESP_LOGI(TAG, "PDM TX mode, data_bit: %d, slot_bit: %d, sample_rate: %d, slot_mask: 0x%x",
353	                         fs->bits_per_sample, slot_bits, (int)fs->sample_rate, (int)fs->channel_mask);
354	#else
355	                ESP_LOGE(TAG, "PDM TX not supported");
356	                return ESP_CODEC_DEV_NOT_SUPPORT;
357	#endif  /* SOC_I2S_SUPPORTS_PDM_TX */
358	            }
359	        }
360	        break;
361	#endif  /* SOC_I2S_SUPPORTS_PDM */
362	#if SOC_I2S_SUPPORTS_TDM
363	        case I2S_COMM_MODE_TDM: {
364	            i2s_tdm_clk_config_t clk_cfg = I2S_TDM_CLK_DEFAULT_CONFIG(fs->sample_rate);
365	            if (clk_src) {
366	                clk_cfg.clk_src = clk_src;
367	            }
368	            if (slot_bits == 24) {
369	                clk_cfg.mclk_multiple = I2S_MCLK_MULTIPLE_384;
370	            }
371	            if (fs->mclk_multiple) {
372	                clk_cfg.mclk_multiple = fs->mclk_multiple;
373	            }
374	            i2s_tdm_slot_config_t slot_cfg = I2S_TDM_PHILIPS_SLOT_DEFAULT_CONFIG(
375	                slot_bits,
376	                I2S_SLOT_MODE_STEREO,
377	                (i2s_tdm_slot_mask_t)fs->channel_mask);
378	            slot_cfg.total_slot = fs->channel;
379	            // When use STD mode, left align is true by default, but when use TDM mode, left align is false by default
380	            // so need set to true to keep the same with STD mode
381	            slot_cfg.left_align = true;
382	            if (slot_bits > fs->bits_per_sample) {
383	                slot_cfg.data_bit_width = fs->bits_per_sample;
384	            }
385	            slot_cfg.slot_bit_width = slot_bits;
386	            slot_cfg.ws_width = slot_bits * fs->channel / 2;
387	            ret = i2s_channel_reconfig_tdm_slot(channel, &slot_cfg);
388	            if (ret != ESP_OK) {
389	                return ESP_CODEC_DEV_DRV_ERR;
390	            }
391	            ret = i2s_channel_reconfig_tdm_clock(channel, &clk_cfg);
392	            if (ret != ESP_OK) {
393	                return ESP_CODEC_DEV_DRV_ERR;
394	            }
395	            ESP_LOGI(TAG, "TDM: %s, data_bit: %d, slot_bit: %d, ws_width: %d, total_slot: %d, slot_mask: 0x%x",
396	                channel_info.dir == I2S_DIR_RX ? "RX" : "TX", (int)slot_cfg.data_bit_width, (int)slot_cfg.slot_bit_width,
397	                (int)slot_cfg.ws_width, (int)slot_cfg.total_slot, (int)slot_cfg.slot_mask);
398	            ESP_LOGI(TAG, "TDM: %s, sample_rate_hz: %d, mclk_multiple: %d, clk_src: %d",
399	                    channel_info.dir == I2S_DIR_RX ? "RX" : "TX", (int)clk_cfg.sample_rate_hz, (int)clk_cfg.mclk_multiple, (int)clk_cfg.clk_src);
400	        }
401	        break;
402	#endif  /* SOC_I2S_SUPPORTS_TDM */
403	        default:
404	            return ESP_CODEC_DEV_NOT_SUPPORT;
405	    }
406	    return ret;
407	}
