409	static int set_fs(i2s_data_t *i2s_data, bool playback, bool skip)
410	{
411	    i2s_chan_handle_t channel = (i2s_chan_handle_t) (playback ? i2s_data->out_handle : i2s_data->in_handle);
412	    i2s_chan_info_t channel_info = {0};
413	    esp_codec_dev_sample_info_t *fs = playback ? &i2s_data->out_fs : &i2s_data->in_fs;
414	    uint8_t bits_per_sample = get_bits(i2s_data, playback);
415	    i2s_channel_get_info(channel, &channel_info);
416	    int ret = set_drv_fs(channel, playback, bits_per_sample, i2s_data->clk_src, fs);
417	    if (ret != ESP_CODEC_DEV_OK) {
418	        return ret;
419	    }
420	    i2s_data_t *paired = get_paired(i2s_data, playback);
421	    // Set RX clock will not take effect if in full duplex mode, need update TX clock also
422	    if (skip == false && playback == false && paired && paired->out_handle != NULL && paired->out_enable == false) {
423	        // TX is master, set to RX not take effect need reconfig TX also
424	        channel = (i2s_chan_handle_t) paired->out_handle;
425	        _i2s_drv_enable(paired, true, false);
426	        ret = set_drv_fs(channel, true, bits_per_sample, i2s_data->clk_src, fs);
427	        _i2s_drv_enable(paired, true, true);
428	    }
429	    return ret;
430	}
431	
432	static int check_fs_compatible(i2s_data_t *i2s_data, bool playback, esp_codec_dev_sample_info_t *fs)
433	{
434	    // Set fs directly when only enable one channel
435	    i2s_data_t *paired = get_paired(i2s_data, playback);
436	    esp_codec_dev_sample_info_t *channel_fs = playback ? &i2s_data->out_fs : &i2s_data->in_fs;
437	    if ((paired == NULL) ||
438	        (playback && paired->in_enable == false) ||
439	        (!playback && paired->out_enable == false)) {
440	        memcpy(&i2s_data->fs, fs, sizeof(esp_codec_dev_sample_info_t));
441	        if (paired && paired != i2s_data) {
442	            memcpy(&paired->fs, fs, sizeof(esp_codec_dev_sample_info_t));
443	        }
444	        memcpy(channel_fs, fs, sizeof(esp_codec_dev_sample_info_t));
445	        if (paired != NULL) {
446	            ESP_LOGI(TAG, "Paired data: %p, current mode: %s, paired in_enable: %d, paired out_enable: %d",
447	                     paired, playback ? "playback" : "record", paired->in_enable, paired->out_enable);
448	        } else {
449	            ESP_LOGI(TAG, "No paired data, current mode: %s", playback ? "playback" : "record");
450	        }
451	        return set_fs(i2s_data, playback, false);
452	    }
453	    if (fs->sample_rate != paired->fs.sample_rate) {
454	        ESP_LOGE(TAG, "Current mode %s conflict sample_rate %d with peer mode sample_rate %d",
455	                 playback ? "playback" : "record", (int)fs->sample_rate, (int)i2s_data->fs.sample_rate);
456	        return ESP_CODEC_DEV_NOT_SUPPORT;
457	    }
458	    // Channel and bits same, set directly
459	    if (fs->channel == paired->fs.channel &&
460	        fs->bits_per_sample == paired->fs.bits_per_sample) {
461	        memcpy(&i2s_data->fs, fs, sizeof(esp_codec_dev_sample_info_t));
462	        memcpy(channel_fs, fs, sizeof(esp_codec_dev_sample_info_t));
463	        ESP_LOGI(TAG, "Current mode(%s) and peer mode have same sample_rate %d, channel %d, bits_per_sample %d",
464	                 playback ? "playback" : "record", (int)fs->sample_rate, fs->channel, fs->bits_per_sample);
465	        return set_fs(i2s_data, playback, false);
466	    }
467	    memcpy(channel_fs, fs, sizeof(esp_codec_dev_sample_info_t));
468	    uint16_t want_bits = fs->channel * fs->bits_per_sample;
469	    uint16_t run_bits = paired->fs.channel * paired->fs.bits_per_sample;
470	    int ret;
471	    if (run_bits > want_bits) {
472	        // eg. Open with 4ch 16bit firstly, then open with 2ch 16bit, need extend slot bits to 2ch 32bit
473	        i2s_chan_handle_t channel = (i2s_chan_handle_t)(playback ? i2s_data->out_handle : i2s_data->in_handle);
474	        int slot_bits = run_bits / fs->channel;
475	        ret = set_drv_fs(channel, playback, slot_bits, i2s_data->clk_src, fs);
476	        if (ret != ESP_CODEC_DEV_OK) {
477	            ESP_LOGE(TAG, "set_drv_fs failed");
478	        } else {
479	            ESP_LOGI(TAG, "Current mode %s has extended slot bits from %d to %d", playback ? "playback" : "record", want_bits, run_bits);
480	        }
481	        return ret;
482	    }
483	    // Need expand peer channel bits
484	    ESP_LOGI(TAG, "Peer mode %s need extend bits %d to %d", !playback ? "playback" : "record", run_bits, want_bits);
485	    do {
486	        if (want_bits > run_bits) {
487	            if (playback == false) {
488	                paired->out_reconfig = true;
489	            } else {
490	                paired->in_reconfig = true;
491	            }
492	            ret = _i2s_drv_enable(paired, !playback, false);
493	            if (ret != ESP_CODEC_DEV_OK) {
494	                break;
495	            }
496	            memcpy(&paired->fs, fs, sizeof(esp_codec_dev_sample_info_t));
497	            memcpy(&i2s_data->fs, fs, sizeof(esp_codec_dev_sample_info_t));
498	        }
499	        // Need set fs before enable
500	        ret = set_fs(i2s_data, playback, false);
501	        if (ret != ESP_CODEC_DEV_OK) {
502	            break;
503	        }
504	        if (want_bits > run_bits) {
505	            ret = set_fs(paired, !playback, true);
506	            if (ret != ESP_CODEC_DEV_OK) {
507	                break;
508	            }
509	            ret = _i2s_drv_enable(paired, !playback, true);
510	            if (ret != ESP_CODEC_DEV_OK) {
511	                break;
512	            }
513	        }
514	    } while (0);
515	    i2s_data->out_reconfig = i2s_data->in_reconfig = false;
516	    paired->out_reconfig = paired->in_reconfig = false;
517	    return ret;
518	}
519	#endif  /* ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0) */
520	
521	static int _i2s_data_open(const audio_codec_data_if_t *h, void *data_cfg, int cfg_size)
522	{
523	    i2s_data_t *i2s_data = (i2s_data_t *)h;
524	    if (h == NULL || data_cfg == NULL || cfg_size != sizeof(audio_codec_i2s_cfg_t)) {
525	        return ESP_CODEC_DEV_INVALID_ARG;
526	    }
527	    audio_codec_i2s_cfg_t *i2s_cfg = (audio_codec_i2s_cfg_t *)data_cfg;
528	    i2s_data->is_open    = true;
529	    i2s_data->port       = i2s_cfg->port;
530	    i2s_data->out_handle = i2s_cfg->tx_handle;
531	    i2s_data->in_handle  = i2s_cfg->rx_handle;
532	#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0)
533	    if (i2s_data->in_handle && i2s_data->out_handle == NULL) {
534	        i2s_chan_info_t channel_info = {0};
535	        i2s_channel_get_info(i2s_data->in_handle, &channel_info);
536	        // If use duplex mode, out_handle is the pair of in_handle, otherwise out_handle is NULL
537	        i2s_data->out_handle = channel_info.pair_chan;
538	        ESP_LOGI(TAG, "Auto get out handle %p from in handle %p when duplex mode", i2s_data->out_handle, i2s_data->in_handle);
539	    }
540	    i2s_data->clk_src = (i2s_clock_src_t)i2s_cfg->clk_src;
541	#endif
542	    add_to_keeper(i2s_data);
543	    return ESP_CODEC_DEV_OK;
544	}
