555	static int _i2s_data_enable(const audio_codec_data_if_t *h, esp_codec_dev_type_t dev_type, bool enable)
556	{
557	    i2s_data_t *i2s_data = (i2s_data_t *) h;
558	    if (i2s_data == NULL) {
559	        return ESP_CODEC_DEV_INVALID_ARG;
560	    }
561	    if (i2s_data->is_open == false) {
562	        return ESP_CODEC_DEV_WRONG_STATE;
563	    }
564	    int ret = ESP_CODEC_DEV_OK;
565	    _i2s_lock(i2s_data, __func__);
566	    if (dev_type == ESP_CODEC_DEV_TYPE_IN_OUT) {
567	        ret = _i2s_drv_enable(i2s_data, true, enable);
568	        ret = _i2s_drv_enable(i2s_data, false, enable);
569	    } else {
570	        bool playback = dev_type & ESP_CODEC_DEV_TYPE_OUT ? true : false;
571	        i2s_data_t *paired = get_paired(i2s_data, playback);
572	        // When RX is working TX disable should be blocked
573	        if (enable == false && playback && i2s_data->out_handle && paired && paired->in_enable) {
574	            ESP_LOGI(TAG, "Pending out channel for in channel running");
575	            i2s_data->out_disable_pending = true;
576	        }
577	    #if SOC_I2S_HW_VERSION_1
578	        // For ESP32 and ESP32S3 if disable RX, TX also not work need pending until TX not used
579	        else if (enable == false && playback == false && i2s_data->in_handle && paired && paired->out_enable) {
580	            ESP_LOGI(TAG, "Pending in channel for out channel running");
581	            i2s_data->in_disable_pending = true;
582	        }
583	    #endif
584	        else {
585	            ret = _i2s_drv_enable(i2s_data, playback, enable);
586	            // Disable TX when RX disable if TX disable is pending
587	            if (enable == false) {
588	                if (playback == false && paired && paired->out_disable_pending)  {
589	                    ret = _i2s_drv_enable(paired, true, enable);
590	                    paired->out_disable_pending = false;
591	                }
592	                if (playback == true && paired && paired->in_disable_pending)  {
593	                    ret = _i2s_drv_enable(paired, false, enable);
594	                    paired->in_disable_pending = false;
595	                }
596	            } else {
597	                // Force to clear pending flags if enable again
598	                if (playback) {
599	                    i2s_data->out_disable_pending = false;
600	                } else {
601	                    i2s_data->in_disable_pending = false;
602	                }
603	            }
604	        }
605	    }
606	    if (dev_type & ESP_CODEC_DEV_TYPE_IN) {
607	        i2s_data->in_enable = enable;
608	    }
609	    if (dev_type & ESP_CODEC_DEV_TYPE_OUT) {
610	        i2s_data->out_enable = enable;
611	    }
612	    _i2s_unlock(i2s_data);
613	    return ret;
614	}
615	
616	static int _i2s_data_set_fmt(const audio_codec_data_if_t *h, esp_codec_dev_type_t dev_type, esp_codec_dev_sample_info_t *fs)
617	{
618	    i2s_data_t *i2s_data = (i2s_data_t *) h;
619	    if (i2s_data == NULL) {
620	        return ESP_CODEC_DEV_INVALID_ARG;
621	    }
622	    if (i2s_data->is_open == false) {
623	        return ESP_CODEC_DEV_WRONG_STATE;
624	    }
625	    esp_codec_dev_sample_info_t eq_fs;
626	    if (fs->channel == 1) {
627	        // When using one channel replace to select channel 0 in default
628	        memcpy(&eq_fs, fs, sizeof(esp_codec_dev_sample_info_t));
629	        fs = &eq_fs;
630	        fs->channel = 2;
631	        fs->channel_mask = ESP_CODEC_DEV_MAKE_CHANNEL_MASK(0);
632	    }
633	#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0)
634	    if (fs->channel_mask == 0) {
635	        // Add channel mask automatically when not set
636	        memcpy(&eq_fs, fs, sizeof(esp_codec_dev_sample_info_t));
637	        fs = &eq_fs;
638	        for (int i = 0; i < fs->channel; i++) {
639	            fs->channel_mask |= ESP_CODEC_DEV_MAKE_CHANNEL_MASK(i);
640	        }
641	    }
642	#endif
643	    if (_i2s_valid_fmt(fs) == false) {
644	        return ESP_CODEC_DEV_NOT_SUPPORT;
645	    }
646	#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0)
647	    int ret;
648	    _i2s_lock(i2s_data, __func__);
649	    // disable internally
650	    if (dev_type & ESP_CODEC_DEV_TYPE_OUT) {
651	        _i2s_drv_enable(i2s_data, true, false);
652	    }
653	    if (dev_type & ESP_CODEC_DEV_TYPE_IN) {
654	        _i2s_drv_enable(i2s_data, false, false);
655	    }
656	    if ((dev_type & ESP_CODEC_DEV_TYPE_IN) != 0 &&
657	        (dev_type & ESP_CODEC_DEV_TYPE_OUT) != 0) {
658	        // Device support playback and record at same time
659	        memcpy(&i2s_data->fs, fs, sizeof(esp_codec_dev_sample_info_t));
660	        memcpy(&i2s_data->in_fs, fs, sizeof(esp_codec_dev_sample_info_t));
661	        memcpy(&i2s_data->out_fs, fs, sizeof(esp_codec_dev_sample_info_t));
662	        ret = set_fs(i2s_data, true, true);
663	        ret = set_fs(i2s_data, false, true);
664	    } else {
665	        ret = check_fs_compatible(i2s_data, dev_type & ESP_CODEC_DEV_TYPE_OUT ? true : false, fs);
666	    }
667	    _i2s_unlock(i2s_data);
668	    return ret;
669	#else
670	    // When use multichannel data
671	    if (fs->channel_mask) {
672	        i2s_channel_t sel_channel = 0;
673	#if SOC_I2S_SUPPORTS_TDM
674	        sel_channel = (i2s_channel_t)(fs->channel_mask << 16);
675	#else
676	        if (fs->channel_mask == ESP_CODEC_DEV_MAKE_CHANNEL_MASK(0)) {
677	            sel_channel = 1;
678	        } else {
679	            ESP_LOGE(TAG, "IC not support TDM");
680	            return ESP_CODEC_DEV_NOT_FOUND;
681	        }
682	#endif
683	        i2s_set_clk(i2s_data->port, fs->sample_rate, fs->bits_per_sample, sel_channel);
684	    } else {
685	        i2s_set_clk(i2s_data->port, fs->sample_rate, fs->bits_per_sample, fs->channel);
686	    }
687	    i2s_zero_dma_buffer(i2s_data->port);
688	    memcpy(&i2s_data->fs, fs, sizeof(esp_codec_dev_sample_info_t));
689	#endif
690	    return ESP_CODEC_DEV_OK;
691	}
