693	static int _i2s_data_read(const audio_codec_data_if_t *h, uint8_t *data, int size)
694	{
695	    i2s_data_t *i2s_data = (i2s_data_t *) h;
696	    if (i2s_data == NULL) {
697	        return ESP_CODEC_DEV_INVALID_ARG;
698	    }
699	    if (i2s_data->is_open == false) {
700	        return ESP_CODEC_DEV_WRONG_STATE;
701	    }
702	    size_t bytes_read = 0;
703	#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0)
704	    i2s_chan_handle_t rx_chan = (i2s_chan_handle_t) i2s_data->in_handle;
705	    if (rx_chan == NULL) {
706	        return ESP_CODEC_DEV_DRV_ERR;
707	    }
708	    if (i2s_data->in_reconfig) {
709	        memset(data, 0, size);
710	        esp_codec_dev_sleep(10);
711	        return ESP_CODEC_DEV_OK;
712	    }
713	    int ret = i2s_channel_read(rx_chan, data, size, &bytes_read, DEFAULT_WAIT_TIMEOUT);
714	#else
715	    int ret = i2s_read(i2s_data->port, data, size, &bytes_read, portMAX_DELAY);
716	#endif
717	    return ret == 0 ? ESP_CODEC_DEV_OK : ESP_CODEC_DEV_DRV_ERR;
718	}
719	
720	static int _i2s_data_write(const audio_codec_data_if_t *h, uint8_t *data, int size)
721	{
722	    i2s_data_t *i2s_data = (i2s_data_t *) h;
723	    if (i2s_data == NULL) {
724	        return ESP_CODEC_DEV_INVALID_ARG;
725	    }
726	    if (i2s_data->is_open == false) {
727	        return ESP_CODEC_DEV_WRONG_STATE;
728	    }
