```c
esp_err_t es8311_play_pcm(const uint8_t *data, size_t len)
{
    if (!s_tx_handle || !data || len == 0) return ESP_ERR_INVALID_ARG;
    if (len % 2) len -= 1;  /* 单声道 int16 对齐 */

    /* 单声道 → 立体声展开缓冲：1024 采样 = 4KB */
    const int samples_per_chunk = 1024;
    int16_t *buf = malloc(samples_per_chunk * 4);
    if (!buf) return ESP_ERR_NO_MEM;

    const int16_t *src = (const int16_t *)data;
    int total_samples = len / 2;
    int done = 0;

    while (done < total_samples) {
        int n = total_samples - done;
        if (n > samples_per_chunk) n = samples_per_chunk;
        for (int i = 0; i < n; i++) {
            buf[i * 2]     = src[done + i];  /* 左 */
            buf[i * 2 + 1] = src[done + i];  /* 右 */
        }
        size_t bytes_write = 0;
        esp_err_t ret = i2s_channel_write(s_tx_handle, buf, n * 4, &bytes_write, 2000);
        if (ret != ESP_OK) {
            free(buf);
            ESP_LOGE(TAG, "pcm write fail[%d]", ret);
            return ret;
        }
        done += n;
    }
    free(buf);
    return ESP_OK;
}
