177	static void apply_ap_config(void)
178	{
179	    wifi_config_t ap_cfg = {0};
180	    ap_cfg.ap.ssid_len = strlen(s_ap_ssid);
181	    memcpy(ap_cfg.ap.ssid, s_ap_ssid, ap_cfg.ap.ssid_len);
182	    ap_cfg.ap.channel = wifi_manager_ap_channel();
183	    ap_cfg.ap.max_connection = wifi_manager_ap_max_conn();
184	    if (s_config.ap_password && s_config.ap_password[0] != '\0') {
185	        ap_cfg.ap.authmode = WIFI_AUTH_WPA2_PSK;
186	        strlcpy((char *)ap_cfg.ap.password, s_config.ap_password, sizeof(ap_cfg.ap.password));
187	    } else {
188	        ap_cfg.ap.authmode = WIFI_AUTH_OPEN;
189	    }
190	    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_AP, &ap_cfg));
191	}
192	
193	static void refresh_ap_ip_str(void)
194	{
195	    if (!s_ap_netif) return;
196	    esp_netif_ip_info_t ip_info = {0};
197	    if (esp_netif_get_ip_info(s_ap_netif, &ip_info) == ESP_OK && ip_info.ip.addr != 0) {
198	        snprintf(s_ap_ip, sizeof(s_ap_ip), IPSTR, IP2STR(&ip_info.ip));
199	    }
200	}
