202	static void reset_sta_runtime_state(void)
203	{
204	    strlcpy(s_ip_addr, "0.0.0.0", sizeof(s_ip_addr));
205	    s_connected = false;
206	    xEventGroupClearBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
207	}
208	
209	esp_err_t wifi_manager_validate_config(const wifi_manager_config_t *config)
210	{
211	    if (!config) return ESP_ERR_INVALID_ARG;
212	    if (config->sta_ssid && config->sta_ssid[0] != '\0') {
213	        if (strlen(config->sta_ssid) >= sizeof(((wifi_config_t *)0)->sta.ssid)) return ESP_ERR_INVALID_ARG;
214	    }
215	    if (config->sta_password && config->sta_password[0] != '\0') {
216	        size_t n = strlen(config->sta_password);
217	        if (n < 8 || n >= sizeof(((wifi_config_t *)0)->sta.password)) return ESP_ERR_INVALID_ARG;
218	    }
219	    if (config->ap_password && config->ap_password[0] != '\0') {
220	        size_t n = strlen(config->ap_password);
221	        if (n < 8 || n >= sizeof(((wifi_config_t *)0)->ap.password)) return ESP_ERR_INVALID_ARG;
222	    }
223	    if (config->ap_ssid && strlen(config->ap_ssid) > sizeof(((wifi_config_t *)0)->ap.ssid)) return ESP_ERR_INVALID_ARG;
224	    if (config->ap_ssid_prefix && strlen(config->ap_ssid_prefix) >= sizeof(s_ap_ssid) - 7) return ESP_ERR_INVALID_ARG;
225	    if (!wifi_manager_ap_behavior_is_valid(config->ap_behavior)) return ESP_ERR_INVALID_ARG;
226	    return ESP_OK;
227	}
228	
229	static esp_err_t configure_sta_mode(const wifi_manager_config_t *config)
230	{
231	    esp_err_t err = wifi_manager_validate_config(config);
232	    if (err != ESP_OK) return err;
233	
234	    sync_owned_config(config);
235	    compose_ap_ssid();
236	    s_sta_configured = (s_config.sta_ssid && s_config.sta_ssid[0] != '\0');
237	    ESP_LOGI(TAG, "Applying Wi-Fi config: sta_configured=%d sta_ssid_len=%u sta_password_empty=%d ap_password_empty=%d ap_behavior=%s",
238	             s_sta_configured,
239	             (unsigned)(s_config.sta_ssid ? strlen(s_config.sta_ssid) : 0U),
240	             wifi_manager_sta_password_is_set() ? 0 : 1,
241	             (s_config.ap_password && s_config.ap_password[0] != '\0') ? 0 : 1,
242	             s_config.ap_behavior ? s_config.ap_behavior : "keep");
243	
244	    if (s_reconnect_timer) esp_timer_stop(s_reconnect_timer);
245	    reset_sta_runtime_state();
246	
247	    if (s_sta_configured) {
248	        wifi_config_t sta_cfg = {0};
249	        strlcpy((char *)sta_cfg.sta.ssid, s_config.sta_ssid, sizeof(sta_cfg.sta.ssid));
250	        strlcpy((char *)sta_cfg.sta.password,
251	                s_config.sta_password ? s_config.sta_password : "",
252	                sizeof(sta_cfg.sta.password));
253	        sta_cfg.sta.threshold.authmode = wifi_manager_sta_password_is_set() ? WIFI_AUTH_WPA2_PSK : WIFI_AUTH_OPEN;
254	        sta_cfg.sta.pmf_cfg.capable = true;
255	        sta_cfg.sta.pmf_cfg.required = false;
256	
257	        s_mode = WM_STATE_APSTA;
258	        err = esp_wifi_set_mode(WIFI_MODE_APSTA);
259	        if (err != ESP_OK) return err;
260	        apply_ap_config();
261	        err = esp_wifi_set_config(WIFI_IF_STA, &sta_cfg);
262	        if (err != ESP_OK) return err;
263	        return ESP_OK;
264	    }
265	
266	    s_mode = WM_STATE_PROVISION_AP;
267	    err = esp_wifi_set_mode(WIFI_MODE_AP);
268	    if (err != ESP_OK) return err;
269	    apply_ap_config();
270	    return ESP_OK;
271	}
