273	static void arm_reconnect(void)
274	{
275	    if (!s_reconnect_timer) return;
276	    esp_timer_stop(s_reconnect_timer);
277	    esp_err_t err = esp_timer_start_once(s_reconnect_timer, (uint64_t)WIFI_RETRY_MS * 1000ULL);
278	    if (err != ESP_OK) {
279	        ESP_LOGW(TAG, "Failed to arm reconnect timer: %s", esp_err_to_name(err));
280	    }
281	}
