283	/*
284	 * When close_on_sta closed the AP after a successful connect and STA later
285	 * drops, bring the AP back so users can always fall through to the portal.
286	 * Called only from the disconnect path.
287	 */
288	static void reopen_ap_if_needed(void)
289	{
290	    if (s_mode != WM_STATE_STA_ONLY) return;
291	    ESP_LOGI(TAG, "Reopening AP after STA disconnect (was closed via close_on_sta)");
292	    esp_err_t err = esp_wifi_set_mode(WIFI_MODE_APSTA);
293	    if (err != ESP_OK) {
294	        ESP_LOGW(TAG, "Failed to reopen AP: %s", esp_err_to_name(err));
295	        return;
296	    }
297	    apply_ap_config();
298	    s_mode = WM_STATE_APSTA;
299	}
