301	static void wifi_event_handler(void *arg, esp_event_base_t event_base, int32_t event_id, void *event_data)
302	{
303	    (void)arg;
304	
305	    if (event_base == WIFI_EVENT) {
306	        switch (event_id) {
307	        case WIFI_EVENT_STA_START:
308	            if (s_sta_configured) {
309	                ESP_LOGI(TAG, "STA start: ssid_len=%u auth_threshold=%s mode=%s",
310	                         (unsigned)strlen(s_config.sta_ssid),
311	                         wifi_manager_sta_password_is_set() ? "wpa2_psk" : "open",
312	                         wifi_manager_mode_string(s_mode));
313	                esp_wifi_connect();
314	            } else {
315	                ESP_LOGW(TAG, "Wi-Fi STA not configured, skipping connection");
316	            }
317	            return;
318	
319	        case WIFI_EVENT_STA_DISCONNECTED: {
320	            const wifi_event_sta_disconnected_t *disc = event_data;
321	            uint16_t reason = disc ? disc->reason : 0;
322	            strlcpy(s_ip_addr, "0.0.0.0", sizeof(s_ip_addr));
323	            if (s_connected) {
324	                s_connected = false;
325	                notify_state_changed(false);
326	            }
327	            if (!s_sta_configured) {
328	                ESP_LOGW(TAG, "STA disconnected but not configured, reason=%u", (unsigned)reason);
329	                return;
330	            }
331	            reopen_ap_if_needed();
332	            ESP_LOGI(TAG, "STA disconnected: reason=%u next_retry_ms=%d ap_active=%d mode=%s",
333	                     (unsigned)reason, WIFI_RETRY_MS, s_ap_active, wifi_manager_mode_string(s_mode));
334	            arm_reconnect();
335	            return;
336	        }
337	
338	        case WIFI_EVENT_AP_START:
339	            s_ap_active = true;
340	            refresh_ap_ip_str();
341	            ESP_LOGW(TAG, "*** Provisioning AP active: %s @ %s ***", s_ap_ssid, s_ap_ip);
342	            notify_state_changed(true);
343	            return;
344	
345	        case WIFI_EVENT_AP_STOP:
346	            s_ap_active = false;
347	            notify_state_changed(true);
348	            return;
349	
350	        default:
351	            return;
352	        }
353	    }
354	
355	    if (event_base == IP_EVENT && event_id == IP_EVENT_STA_GOT_IP) {
356	        ip_event_got_ip_t *event = event_data;
357	        snprintf(s_ip_addr, sizeof(s_ip_addr), IPSTR, IP2STR(&event->ip_info.ip));
358	        s_connected = true;
359	        if (s_reconnect_timer) esp_timer_stop(s_reconnect_timer);
360	        if (wifi_manager_close_on_sta() && s_ap_active) {
361	            ESP_LOGI(TAG, "STA connected, closing AP per ap_behavior=close_on_sta");
362	            esp_err_t ap_err = esp_wifi_set_mode(WIFI_MODE_STA);
363	            if (ap_err == ESP_OK) {
364	                s_ap_active = false;
365	                s_mode = WM_STATE_STA_ONLY;
366	            } else {
367	                ESP_LOGW(TAG, "Failed to switch to STA-only mode: %s", esp_err_to_name(ap_err));
368	            }
369	        }
370	        xEventGroupSetBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
371	        notify_state_changed(true);
372	    }
373	}
374	
375	static void notify_state_changed(bool force)
376	{
377	    static bool s_last_connected;
378	    static bool s_last_ap_active;
379	    static bool s_initialized;
380	
381	    if (!force && s_initialized && s_last_connected == s_connected && s_last_ap_active == s_ap_active) return;
382	    s_last_connected = s_connected;
383	    s_last_ap_active = s_ap_active;
384	    s_initialized = true;
385	    if (s_state_cb) s_state_cb(s_connected, s_state_cb_user_ctx);
386	}
387	
388	static void reconnect_timer_cb(void *arg)
389	{
390	    (void)arg;
391	    if (!s_sta_configured) return;
392	    esp_err_t err = esp_wifi_connect();
393	    if (err != ESP_OK && err != ESP_ERR_WIFI_CONN) {
394	        ESP_LOGW(TAG, "esp_wifi_connect failed: %s; retrying in %d ms", esp_err_to_name(err), WIFI_RETRY_MS);
395	        arm_reconnect();
396	    }
397	}
