399	esp_err_t wifi_manager_init(void)
400	{
401	    if (s_wifi_event_group) return ESP_OK;
402	
403	    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
404	
405	    s_wifi_event_group = xEventGroupCreate();
406	    if (!s_wifi_event_group) return ESP_ERR_NO_MEM;
407	
408	    ESP_ERROR_CHECK(esp_netif_init());
409	    ESP_ERROR_CHECK(esp_event_loop_create_default());
410	    s_sta_netif = esp_netif_create_default_wifi_sta();
411	    s_ap_netif = esp_netif_create_default_wifi_ap();
412	    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
413	    ESP_ERROR_CHECK(esp_event_handler_instance_register(WIFI_EVENT, ESP_EVENT_ANY_ID, &wifi_event_handler, NULL, NULL));
414	    ESP_ERROR_CHECK(esp_event_handler_instance_register(IP_EVENT, IP_EVENT_STA_GOT_IP, &wifi_event_handler, NULL, NULL));
415	
416	    const esp_timer_create_args_t timer_args = { .callback = reconnect_timer_cb, .name = "wifi_reconnect" };
417	    ESP_ERROR_CHECK(esp_timer_create(&timer_args, &s_reconnect_timer));
418	
419	    memset(&s_config, 0, sizeof(s_config));
420	    s_wifi_started = false;
421	    compose_ap_ssid();
422	    return ESP_OK;
423	}
