425	esp_err_t wifi_manager_start(const wifi_manager_config_t *config)
426	{
427	    if (!config) return ESP_ERR_INVALID_ARG;
428	
429	    esp_err_t err = configure_sta_mode(config);
430	    if (err != ESP_OK) return err;
431	
432	    if (!s_wifi_started) {
433	        err = esp_wifi_start();
434	        if (err != ESP_OK) return err;
435	        s_wifi_started = true;
436	    }
437	    return ESP_OK;
438	}
439	
440	esp_err_t wifi_manager_apply_sta_config(const wifi_manager_config_t *config)
441	{
442	    if (!config) return ESP_ERR_INVALID_ARG;
443	
444	    bool was_connected = s_connected;
445	    esp_err_t err = configure_sta_mode(config);
446	    if (err != ESP_OK) return err;
447	
448	    if (was_connected) notify_state_changed(false);
449	
450	    if (!s_wifi_started) {
451	        err = esp_wifi_start();
452	        if (err != ESP_OK) return err;
453	        s_wifi_started = true;
454	    }
455	
456	    if (!s_sta_configured) return ESP_OK;
457	
458	    err = esp_wifi_disconnect();
459	    if (err != ESP_OK && err != ESP_ERR_WIFI_NOT_CONNECT) return err;
460	    err = esp_wifi_connect();
461	    if (err != ESP_OK && err != ESP_ERR_WIFI_CONN) return err;
462	    return ESP_OK;
463	}
464	
465	esp_err_t wifi_manager_wait_connected(uint32_t timeout_ms)
466	{
467	    if (!s_sta_configured) return ESP_ERR_INVALID_STATE;
468	
469	    TickType_t ticks = (timeout_ms == UINT32_MAX) ? portMAX_DELAY : pdMS_TO_TICKS(timeout_ms);
470	    EventBits_t bits = xEventGroupWaitBits(s_wifi_event_group, WIFI_CONNECTED_BIT, pdFALSE, pdFALSE, ticks);
471	    return (bits & WIFI_CONNECTED_BIT) ? ESP_OK : ESP_ERR_TIMEOUT;
472	}
473	
474	esp_err_t wifi_manager_register_state_callback(wifi_manager_state_cb_t cb, void *user_ctx)
475	{
476	    s_state_cb = cb;
477	    s_state_cb_user_ctx = user_ctx;
478	    if (s_state_cb) s_state_cb(s_connected, s_state_cb_user_ctx);
479	    return ESP_OK;
480	}
