499	esp_err_t wifi_manager_scan_aps(wifi_manager_scan_record_t *records, uint16_t max_records, uint16_t *out_count)
500	{
501	    wifi_mode_t original_mode = WIFI_MODE_NULL;
502	    wifi_mode_t scan_mode = WIFI_MODE_NULL;
503	    wifi_scan_config_t scan_cfg = { .show_hidden = true };
504	    wifi_ap_record_t *ap_records = NULL;
505	    uint16_t ap_count = 0;
506	    esp_err_t err;
507	
508	    if (!records || max_records == 0 || !out_count) return ESP_ERR_INVALID_ARG;
509	    *out_count = 0;
510	
511	    err = esp_wifi_get_mode(&original_mode);
512	    if (err != ESP_OK) return err;
513	
514	    scan_mode = original_mode;
515	    if (original_mode == WIFI_MODE_AP) {
516	        scan_mode = WIFI_MODE_APSTA;
517	        err = esp_wifi_set_mode(scan_mode);
518	        if (err != ESP_OK) return err;
519	    } else if (original_mode != WIFI_MODE_STA && original_mode != WIFI_MODE_APSTA) {
520	        return ESP_ERR_INVALID_STATE;
521	    }
522	
523	    err = esp_wifi_scan_start(&scan_cfg, true);
524	    if (err != ESP_OK) goto cleanup;
525	
526	    err = esp_wifi_scan_get_ap_num(&ap_count);
527	    if (err != ESP_OK) goto cleanup;
528	
529	    if (ap_count == 0) { err = ESP_OK; goto cleanup; }
530	    if (ap_count > max_records) ap_count = max_records;
531	
532	    ap_records = calloc(ap_count, sizeof(wifi_ap_record_t));
533	    if (!ap_records) { err = ESP_ERR_NO_MEM; goto cleanup; }
534	
535	    err = esp_wifi_scan_get_ap_records(&ap_count, ap_records);
536	    if (err != ESP_OK) goto cleanup;
537	
538	    for (uint16_t i = 0; i < ap_count; ++i) {
539	        strlcpy(records[i].ssid, (const char *)ap_records[i].ssid, sizeof(records[i].ssid));
540	        records[i].rssi = ap_records[i].rssi;
541	        records[i].primary = ap_records[i].primary;
542	        records[i].authmode = ap_records[i].authmode;
543	    }
544	    *out_count = ap_count;
545	    err = ESP_OK;
546	
547	cleanup:
548	    free(ap_records);
549	    if (scan_mode != original_mode) {
550	        esp_err_t restore_err = esp_wifi_set_mode(original_mode);
551	        if (err == ESP_OK && restore_err != ESP_OK) err = restore_err;
552	    }
553	    return err;
554	}
