82	static esp_err_t cap_system_format_current_time(char *output, size_t output_size)
83	{
84	    time_t now = 0;
85	    struct tm local_tm = {0};
86	
87	    if (!output || output_size == 0) {
88	        ESP_LOGE(TAG, "format current time: invalid arg");
89	        return ESP_ERR_INVALID_ARG;
90	    }
91	
92	    time(&now);
93	    if (now < CAP_SYSTEM_MIN_VALID_EPOCH) {
94	        ESP_LOGW(TAG, "format current time: clock is invalid");
95	        return ESP_ERR_INVALID_STATE;
96	    }
97	    if (!localtime_r(&now, &local_tm)) {
98	        ESP_LOGE(TAG, "format current time: localtime_r failed");
99	        return ESP_FAIL;
100	    }
101	    if (strftime(output, output_size, "%Y-%m-%d %H:%M:%S %Z (%A)", &local_tm) == 0) {
102	        ESP_LOGE(TAG, "format current time: buffer too small");
103	        return ESP_ERR_INVALID_SIZE;
104	    }
105	
106	    return ESP_OK;
107	}
