109	static esp_err_t cap_system_sync_with_sntp(char *output, size_t output_size)
110	{
111	    esp_err_t err = ESP_OK;
112	    esp_err_t wait_err = ESP_OK;
113	    int retry = 0;
114	#if CONFIG_LWIP_SNTP_MAX_SERVERS > 1
115	    esp_sntp_config_t config = ESP_NETIF_SNTP_DEFAULT_CONFIG_MULTIPLE(
116	        2,
117	        ESP_SNTP_SERVER_LIST(CAP_SYSTEM_SNTP_PRIMARY_SERVER, CAP_SYSTEM_SNTP_SECONDARY_SERVER)
118	    );
119	#else
120	    esp_sntp_config_t config = ESP_NETIF_SNTP_DEFAULT_CONFIG(CAP_SYSTEM_SNTP_PRIMARY_SERVER);
121	#endif
122	
123	    if (!output || output_size == 0) {
124	        ESP_LOGE(TAG, "sync with sntp: invalid arg");
125	        return ESP_ERR_INVALID_ARG;
126	    }
127	
128	    config.sync_cb = cap_system_time_sync_notification_cb;
129	    err = esp_netif_sntp_init(&config);
130	    if (err != ESP_OK) {
131	        ESP_LOGE(TAG, "sync with sntp init failed: %s", esp_err_to_name(err));
132	        return err;
133	    }
134	
135	    while ((wait_err = esp_netif_sntp_sync_wait(pdMS_TO_TICKS(CAP_SYSTEM_SNTP_WAIT_MS))) == ESP_ERR_TIMEOUT &&
136	           ++retry < CAP_SYSTEM_SNTP_RETRY_COUNT) {
137	        ESP_LOGI(TAG, "Waiting for system time to be set... (%d/%d)", retry, CAP_SYSTEM_SNTP_RETRY_COUNT);
138	    }
139	
140	    if (wait_err != ESP_OK) {
141	        err = wait_err;
142	        ESP_LOGE(TAG, "sync with sntp wait failed: %s", esp_err_to_name(err));
143	        goto done;
144	    }
145	
146	    err = cap_system_format_current_time(output, output_size);
147	    if (err != ESP_OK) {
148	        ESP_LOGE(TAG, "sync with sntp format failed: %s", esp_err_to_name(err));
149	    }
150	
151	done:
152	    esp_netif_sntp_deinit();
153	    return err;
154	}
