278	static bool store_wr_buffer(esp_ble_gatts_cb_param_t *p_data)
279	{
280	    if (p_data == NULL) {
281	        return false;
282	    }
283	
284	    /* Per Bluetooth Core Spec (Vol 3, Part F, 3.4.6.1) the Part Attribute Value
285	     * in ATT_PREPARE_WRITE_REQ may be 0..(ATT_MTU-5) bytes, so a zero-length
286	     * fragment is a valid request that carries no payload. Skip allocating an
287	     * empty node here: malloc(0) is implementation-defined in C and on
288	     * ESP-IDF's multi_heap returns NULL, which would otherwise be reported as
289	     * a (false) allocation failure. */
290	    if (p_data->write.len == 0) {
291	        return true;
292	    }
293	
294	    spp_receive_data_node_t *node = (spp_receive_data_node_t *)malloc(sizeof(spp_receive_data_node_t));
295	    if (node == NULL) {
296	        ESP_LOGE(GATTS_TABLE_TAG, "malloc error %s %d", __func__, __LINE__);
297	        return false;
298	    }
299	
300	    node->len = p_data->write.len;
301	    node->next_node = NULL;
302	    node->node_buff = (uint8_t *)malloc(p_data->write.len);
303	    if (node->node_buff == NULL) {
304	        ESP_LOGE(GATTS_TABLE_TAG, "malloc error %s %d", __func__, __LINE__);
305	        free(node);
306	        return false;
307	    }
308	    memcpy(node->node_buff, p_data->write.value, p_data->write.len);
309	
310	    if (spp_prep_wr_buff.last_node != NULL) {
311	        spp_prep_wr_buff.last_node->next_node = node;
312	    } else {
313	        spp_prep_wr_buff.first_node = node;
314	    }
315	    spp_prep_wr_buff.last_node = node;
316	    spp_prep_wr_buff.buff_size += p_data->write.len;
317	    spp_prep_wr_buff.node_num++;
318	
319	    return true;
320	}
321	
322	static void free_prep_wr_buffer(void)
323	{
324	    spp_receive_data_node_t *cur = spp_prep_wr_buff.first_node;
325	
326	    while (cur != NULL) {
327	        spp_receive_data_node_t *next = cur->next_node;
328	        if (cur->node_buff) {
329	            free(cur->node_buff);
330	        }
331	        free(cur);
332	        cur = next;
333	    }
334	
335	    spp_prep_wr_buff.node_num = 0;
336	    spp_prep_wr_buff.buff_size = 0;
337	    spp_prep_wr_buff.first_node = NULL;
338	    spp_prep_wr_buff.last_node = NULL;
339	}
340	
341	static void print_prep_wr_buffer(void)
342	{
343	    spp_receive_data_node_t *cur = spp_prep_wr_buff.first_node;
344	
345	    while (cur != NULL) {
346	        uart_write_bytes(UART_NUM_0, (char *)(cur->node_buff), cur->len);
347	        cur = cur->next_node;
348	    }
349	}
