525	static void gap_event_handler(esp_gap_ble_cb_event_t event, esp_ble_gap_cb_param_t *param)
526	{
527	    switch (event) {
528	    case ESP_GAP_BLE_ADV_DATA_RAW_SET_COMPLETE_EVT:
529	        esp_ble_gap_start_advertising(&spp_adv_params);
530	        break;
531	    case ESP_GAP_BLE_ADV_START_COMPLETE_EVT:
532	        //advertising start complete event to indicate advertising start successfully or failed
533	        if(param->adv_start_cmpl.status != ESP_BT_STATUS_SUCCESS) {
534	            ESP_LOGE(GATTS_TABLE_TAG, "Advertising start failed, status %d", param->adv_start_cmpl.status);
535	            break;
536	        }
537	        ESP_LOGI(GATTS_TABLE_TAG, "Advertising start successfully");
538	        break;
539	    case ESP_GAP_BLE_ADV_STOP_COMPLETE_EVT:
540	        if (param->adv_stop_cmpl.status != ESP_BT_STATUS_SUCCESS) {
541	            ESP_LOGE(GATTS_TABLE_TAG, "Advertising stop failed, status %d", param->adv_stop_cmpl.status);
542	            break;
543	        }
544	        ESP_LOGI(GATTS_TABLE_TAG, "Advertising stop successfully");
545	        break;
546	    case ESP_GAP_BLE_UPDATE_CONN_PARAMS_EVT:
547	         ESP_LOGI(GATTS_TABLE_TAG, "Connection params update, status %d, conn_int %d, latency %d, timeout %d",
548	                  param->update_conn_params.status,
549	                  param->update_conn_params.conn_int,
550	                  param->update_conn_params.latency,
551	                  param->update_conn_params.timeout);
552	        break;
553	    default:
554	        break;
555	    }
556	}
