#pragma once
#include <stdint.h>
#include <stddef.h>
#include "esp_err.h"

#ifdef __cplusplus
extern "C" {
#endif

/* 初始化：设时区 + 创建播报任务。须在 es8311_codec_init() 之后调用 */
esp_err_t time_announce_init(void);

/* 设置系统时间（UTC epoch 秒） */
esp_err_t time_announce_set_epoch(uint32_t epoch);

/* 请求播报当前时间（异步，立即返回；已在播报中返回 ESP_ERR_INVALID_STATE） */
esp_err_t time_announce_request(void);

/* 时间是否已同步（未同步时播报会被拒绝） */
bool time_announce_has_time(void);

/* 当前本地时间字符串 "HH:MM:SS"，未同步返回 "UNSYNC"，buf 至少 12 字节 */
void time_announce_get_time_str(char *buf, size_t bufsize);

#ifdef __cplusplus
}
#endif

/*
 * time_announce.c - 时间播报：读本地时钟 → 数字拆分 → 语音片段拼接播放
 *
 * 拼接规则（时+分）：
 *   14:30 → 现在是北京时间 十 四 点 三 十 分
 *   14:05 → 现在是北京时间 十 四 点 零 五 分
 *   14:00 → 现在是北京时间 十 四 点 整
 * 播放在独立任务中执行，BLE/TCP 命令只需入队，不阻塞协议栈。
 */
#include "time_announce.h"
#include <time.h>
#include <sys/time.h>
#include <stdio.h>
#include "esp_log.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/queue.h"
#include "audio_speaker.h"
#include "voice_clips.h"

static const char *TAG = "time_announce";

#define MIN_VALID_EPOCH  1735689600  /* 2025-01-01 UTC，早于此视为未对时 */
#define CLIP_GAP_MS      100         /* 片段间停顿（片段自带 120ms 尾静音） */
#define ANNOUNCE_STACK   4096
#define ANNOUNCE_PRIO    4

static QueueHandle_t s_trigger_queue;

static void play_clip(int idx)
{
    const voice_clip_t *c = &g_voice_clips[idx];
    es8311_play_pcm(c->data, c->len);
    vTaskDelay(pdMS_TO_TICKS(CLIP_GAP_MS));
}

/* 0-59 的数字拆成中文片段序列播放：1→一, 10→十, 14→十四, 20→二十, 45→四十五 */
static void play_number(int n)
{
    if (n == 0) {
        play_clip(CLIP_0);
    } else if (n < 10) {
        play_clip(CLIP_0 + n);
    } else if (n == 10) {
        play_clip(CLIP_TEN);
    } else if (n < 20) {
        play_clip(CLIP_TEN);
        play_clip(CLIP_0 + n - 10);
    } else {
        play_clip(CLIP_0 + n / 10);
        play_clip(CLIP_TEN);
        if (n % 10) {
            play_clip(CLIP_0 + n % 10);
        }
    }
}

static void announce_task(void *arg)
{
    uint8_t trig;
    for (;;) {
        xQueueReceive(s_trigger_queue, &trig, portMAX_DELAY);

        time_t now = time(NULL);
        if (now < MIN_VALID_EPOCH) {
            ESP_LOGW(TAG, "时间未同步，忽略播报请求（先 SETTIME）");
            continue;
        }
        struct tm tmv = {0};
        localtime_r(&now, &tmv);
        ESP_LOGI(TAG, "播报时间: %02d:%02d", tmv.tm_hour, tmv.tm_min);

        play_clip(CLIP_PREFIX);
        play_number(tmv.tm_hour);
        play_clip(CLIP_DIAN);
        if (tmv.tm_min == 0) {
            play_clip(CLIP_ZHENG);
        } else {
            if (tmv.tm_min < 10) {
                play_clip(CLIP_0);  /* 零五分 */
            }
            play_number(tmv.tm_min);
            play_clip(CLIP_FEN);
        }
        ESP_LOGI(TAG, "播报完成");
    }
}

esp_err_t time_announce_init(void)
{
    setenv("TZ", "CST-8", 1);
    tzset();

    s_trigger_queue = xQueueCreate(1, sizeof(uint8_t));
    if (!s_trigger_queue) return ESP_ERR_NO_MEM;

    if (xTaskCreate(announce_task, "announce", ANNOUNCE_STACK, NULL,
                    ANNOUNCE_PRIO, NULL) != pdPASS) {
        return ESP_FAIL;
    }
    ESP_LOGI(TAG, "时间播报就绪（时区 CST-8，等 SETTIME 对时）");
    return ESP_OK;
}

esp_err_t time_announce_set_epoch(uint32_t epoch)
{
    if (epoch < MIN_VALID_EPOCH) {
        ESP_LOGE(TAG, "无效 epoch %u", epoch);
        return ESP_ERR_INVALID_ARG;
    }
    struct timeval tv = { .tv_sec = (time_t)epoch, .tv_usec = 0 };
    if (settimeofday(&tv, NULL) != 0) {
        return ESP_FAIL;
    }
    struct tm tmv = {0};
    localtime_r(&(time_t){ (time_t)epoch }, &tmv);
    ESP_LOGI(TAG, "时间已同步: %04d-%02d-%02d %02d:%02d:%02d",
             tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday,
             tmv.tm_hour, tmv.tm_min, tmv.tm_sec);
    return ESP_OK;
}

esp_err_t time_announce_request(void)
{
    uint8_t trig = 1;
    return (xQueueSend(s_trigger_queue, &trig, 0) == pdTRUE)
           ? ESP_OK : ESP_ERR_INVALID_STATE;
}

bool time_announce_has_time(void)
{
    return time(NULL) >= MIN_VALID_EPOCH;
}

void time_announce_get_time_str(char *buf, size_t bufsize)
{
    time_t now = time(NULL);
    if (now < MIN_VALID_EPOCH) {
        snprintf(buf, bufsize, "UNSYNC");
        return;
    }
    struct tm tmv = {0};
    localtime_r(&now, &tmv);
    snprintf(buf, bufsize, "%02d:%02d:%02d",
             tmv.tm_hour, tmv.tm_min, tmv.tm_sec);
}

