static void spp_send_response(const char *text)
{
    ESP_LOGI(GATTS_TABLE_TAG, "SPP resp: %s", text);
    if (is_connected && enable_data_ntf) {
        esp_ble_gatts_send_indicate(spp_gatts_if, spp_conn_id,
                                    spp_handle_table[SPP_IDX_SPP_DATA_NTY_VAL],
                                    strlen(text), (uint8_t *)text, false);
    }
}

/* 各分支均非阻塞，可在 GATT 事件上下文直接调用。
 * 返回 true 表示是已识别的命令（已处理并回发响应） */
static bool spp_handle_command(const uint8_t *value, uint16_t len)
{
    char cmd[64];
    if (len == 0 || len >= sizeof(cmd)) return false;
    memcpy(cmd, value, len);
    cmd[len] = '\0';
    /* 去掉尾部 \r\n 和空白 */
    while (len > 0 && (cmd[len - 1] == '\r' || cmd[len - 1] == '\n'
                       || cmd[len - 1] == ' ')) {
        cmd[--len] = '\0';
    }
    if (len == 0) return false;

    char resp[48];
    if (strncmp(cmd, "SETTIME ", 8) == 0) {
        uint32_t epoch = strtoul(cmd + 8, NULL, 10);
        char tstr[12];
        if (time_announce_set_epoch(epoch) == ESP_OK) {
            time_announce_get_time_str(tstr, sizeof(tstr));
            snprintf(resp, sizeof(resp), "OK SETTIME %s", tstr);
        } else {
            snprintf(resp, sizeof(resp), "ERR SETTIME");
        }
        spp_send_response(resp);
        return true;
    }
    if (strcmp(cmd, "ANNOUNCE") == 0) {
        if (!time_announce_has_time()) {
            spp_send_response("ERR NOTIME");    /* 先 SETTIME 对时 */
        } else if (time_announce_request() == ESP_OK) {
            spp_send_response("OK ANNOUNCE");
        } else {
            spp_send_response("BUSY");          /* 正在播报中 */
        }
        return true;
    }
    if (strcmp(cmd, "TIME?") == 0) {
        char tstr[12];
        time_announce_get_time_str(tstr, sizeof(tstr));
        snprintf(resp, sizeof(resp), "TIME %s", tstr);
        spp_send_response(resp);
        return true;
    }
    return false;
}

