87	static bool csv_contains(const char *csv, const char *token)
88	{
89	    if (!csv || !token) {
90	        return false;
91	    }
92	    size_t token_len = strlen(token);
93	    const char *cursor = csv;
94	    while (*cursor) {
95	        while (*cursor == ' ' || *cursor == ',') {
96	            cursor++;
97	        }
98	        if (!*cursor) {
99	            break;
100	        }
101	        const char *comma = strchr(cursor, ',');
102	        size_t seg_len = comma ? (size_t)(comma - cursor) : strlen(cursor);
103	        while (seg_len > 0 && cursor[seg_len - 1] == ' ') {
104	            seg_len--;
105	        }
106	        if (seg_len == token_len && strncmp(cursor, token, token_len) == 0) {
107	            return true;
108	        }
109	        cursor += seg_len;
110	        if (comma) {
111	            cursor = comma + 1;
112	        }
113	    }
114	    return false;
115	}
