117	static bool field_matches_filter(const config_field_def_t *field,
118	                                 const char *groups_csv,
119	                                 const char *fields_csv)
120	{
121	    if (!groups_csv && !fields_csv) {
122	        return true;
123	    }
124	    if (groups_csv && csv_contains(groups_csv, field->group)) {
125	        return true;
126	    }
127	    if (fields_csv && csv_contains(fields_csv, field->name)) {
128	        return true;
129	    }
130	    return false;
131	}
