143	static bool is_positive_decimal_string(const char *value)
144	{
145	    const unsigned char *cursor = (const unsigned char *)value;
146	
147	    if (!cursor || !cursor[0]) {
148	        return false;
149	    }
150	    if (cursor[0] == '0') {
151	        return false;
152	    }
153	
154	    while (*cursor) {
155	        if (!isdigit(*cursor)) {
156	            return false;
157	        }
158	        cursor++;
159	    }
160	
161	    return true;
162	}
