178	static esp_err_t emit_config(httpd_req_t *req,
179	                             const app_config_t *config,
180	                             const char *groups_csv,
181	                             const char *fields_csv,
182	                             cJSON *extra_meta)
183	{
184	    cJSON *root = cJSON_CreateObject();
185	    if (!root) {
186	        /* emit_config owns extra_meta once called; free it here since it is
187	         * never attached to root on this failure path (caller does not). */
188	        cJSON_Delete(extra_meta);
189	        httpd_resp_send_500(req);
190	        return ESP_ERR_NO_MEM;
191	    }
192	
193	    for (size_t i = 0; i < CONFIG_FIELD_COUNT; i++) {
194	        const config_field_def_t *field = &CONFIG_FIELDS[i];
195	        if (!field_matches_filter(field, groups_csv, fields_csv)) {
196	            continue;
197	        }
198	        http_server_json_add_string(root, field->name, field_value(config, field));
199	    }
200	
201	    if (extra_meta) {
202	        cJSON_AddItemToObject(root, "_meta", extra_meta);
203	    }
204	
205	    return http_server_send_json_response(req, root);
206	}
