210	static esp_err_t config_get_handler(httpd_req_t *req)
211	{
212	    http_server_ctx_t *ctx = http_server_ctx();
213	    app_config_t *config = NULL;
214	    esp_err_t err;
215	
216	    config = calloc(1, sizeof(*config));
217	    if (!config) {
218	        httpd_resp_send_500(req);
219	        return ESP_ERR_NO_MEM;
220	    }
221	
222	    err = ctx->services.load_config(config);
223	    if (err != ESP_OK) {
224	        free(config);
225	        return httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Failed to load config");
226	    }
227	
228	    char filter_buf[192];
229	    char *groups_csv = NULL;
230	    char *fields_csv = NULL;
231	    bool include_meta = false;
232	
233	    if (http_server_query_get(req, "groups", filter_buf, sizeof(filter_buf)) == ESP_OK) {
234	        groups_csv = strdup(filter_buf);
235	    }
236	    if (http_server_query_get(req, "fields", filter_buf, sizeof(filter_buf)) == ESP_OK) {
237	        fields_csv = strdup(filter_buf);
238	    }
239	    if (http_server_query_get(req, "meta", filter_buf, sizeof(filter_buf)) == ESP_OK) {
240	        include_meta = (filter_buf[0] == '1' || strcmp(filter_buf, "true") == 0);
241	    }
242	
243	    cJSON *meta = NULL;
244	    if (include_meta) {
245	        meta = cJSON_CreateObject();
246	        cJSON *groups = meta ? cJSON_CreateArray() : NULL;
247	        cJSON *fields = meta ? cJSON_CreateArray() : NULL;
248	        if (meta && groups && fields) {
249	            for (size_t i = 0; i < CONFIG_FIELD_COUNT; i++) {
250	                const config_field_def_t *field = &CONFIG_FIELDS[i];
251	                cJSON *entry = cJSON_CreateObject();
252	                if (entry) {
253	                    cJSON_AddStringToObject(entry, "name", field->name);
254	                    cJSON_AddStringToObject(entry, "group", field->group);
255	                    cJSON_AddItemToArray(fields, entry);
256	                }
257	            }
258	
259	            for (size_t i = 0; i < CONFIG_FIELD_COUNT; i++) {
260	                const char *name = CONFIG_FIELDS[i].group;
261	                bool seen = false;
262	                cJSON *existing = NULL;
263	                cJSON_ArrayForEach(existing, groups) {
264	                    if (cJSON_IsString(existing) && strcmp(existing->valuestring, name) == 0) {
265	                        seen = true;
266	                        break;
267	                    }
268	                }
269	                if (!seen) {
270	                    cJSON_AddItemToArray(groups, cJSON_CreateString(name));
271	                }
272	            }
273	
274	            cJSON_AddItemToObject(meta, "groups", groups);
275	            cJSON_AddItemToObject(meta, "fields", fields);
276	        } else {
277	            cJSON_Delete(groups);
278	            cJSON_Delete(fields);
279	            cJSON_Delete(meta);
280	            meta = NULL;
281	        }
282	    }
283	
284	    esp_err_t send_err = emit_config(req, config, groups_csv, fields_csv, meta);
285	    free(config);
286	    free(groups_csv);
287	    free(fields_csv);
288	    return send_err;
289	}
