291	static esp_err_t config_post_handler(httpd_req_t *req)
292	{
293	    http_server_ctx_t *ctx = http_server_ctx();
294	    app_config_t *config = NULL;
295	    esp_err_t err;
296	
297	    config = calloc(1, sizeof(*config));
298	    if (!config) {
299	        httpd_resp_send_500(req);
300	        return ESP_ERR_NO_MEM;
301	    }
302	
303	    err = ctx->services.load_config(config);
304	    if (err != ESP_OK) {
305	        free(config);
306	        return httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Failed to load config");
307	    }
308	
309	    cJSON *root = NULL;
310	    err = http_server_parse_json_body(req, &root);
311	    if (err != ESP_OK) {
312	        free(config);
313	        return httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, "Invalid JSON body");
314	    }
315	
316	    /* Partial writes: only fields present in the JSON body are applied.
317	     * Empty string is a valid value (lets the client clear a slot). */
318	    size_t applied_count = 0;
319	
320	    for (size_t i = 0; i < CONFIG_FIELD_COUNT; i++) {
321	        const config_field_def_t *field = &CONFIG_FIELDS[i];
322	        cJSON *item = cJSON_GetObjectItemCaseSensitive(root, field->name);
323	        if (!cJSON_IsString(item)) {
324	            continue;
325	        }
326	        if (strcmp(field->name, "llm_max_tokens") == 0 ||
327	                strcmp(field->name, "llm_default_image_max_bytes") == 0) {
328	            if (!is_positive_decimal_string(item->valuestring)) {
329	                cJSON_Delete(root);
330	                free(config);
331	                return httpd_resp_send_err(req,
332	                                           HTTPD_400_BAD_REQUEST,
333	                                           strcmp(field->name, "llm_max_tokens") == 0 ?
334	                                               "llm_max_tokens must be a positive integer" :
335	                                               "llm_default_image_max_bytes must be a positive integer");
336	            }
337	        }
338	        if ((strcmp(field->name, "llm_supports_tools") == 0 ||
339	                strcmp(field->name, "llm_supports_vision") == 0 ||
340	                strcmp(field->name, "llm_image_remote_url_only") == 0) &&
341	                !is_boolean_string(item->valuestring)) {
342	            cJSON_Delete(root);
343	            free(config);
344	            return httpd_resp_send_err(req,
345	                                       HTTPD_400_BAD_REQUEST,
346	                                       "LLM boolean fields must be true/false");
347	        }
348	        strlcpy(field_mutable(config, field), item->valuestring, field->size);
349	        applied_count++;
350	    }
351	
352	    cJSON_Delete(root);
353	
354	    if (applied_count == 0) {
355	        free(config);
356	        return httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST,
357	                                   "Request did not contain any recognised fields");
358	    }
359	
360	    const char *wifi_config_error = NULL;
361	    err = validate_wifi_config_fields(config, &wifi_config_error);
362	    if (err != ESP_OK) {
363	        free(config);
364	        return httpd_resp_send_err(req, HTTPD_400_BAD_REQUEST, wifi_config_error);
365	    }
366	
367	    err = ctx->services.save_config(config);
368	    free(config);
369	    if (err != ESP_OK) {
370	        return httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "Failed to save config");
371	    }
372	
373	    ESP_LOGI(TAG, "Saved %u config field%s", (unsigned)applied_count, applied_count == 1 ? "" : "s");
374	
375	    cJSON *resp = cJSON_CreateObject();
376	    if (!resp) {
377	        httpd_resp_set_type(req, "application/json");
378	        return httpd_resp_sendstr(req, "{\"ok\":true}");
379	    }
380	    cJSON_AddBoolToObject(resp, "ok", true);
381	    cJSON_AddNumberToObject(resp, "applied", (double)applied_count);
382	    http_server_json_add_string(resp, "message",
383	                                "Saved. Restart the device to apply Wi-Fi, core LLM, capability, and Lua module changes.");
384	    return http_server_send_json_response(req, resp);
385	}
