#!/usr/bin/env python3
"""临时排查：统计抖动对文字区域的彩色噪点污染"""
from PIL import Image
from pathlib import Path

HERE = Path(__file__).parent


def analyze(path, label):
    im = Image.open(path).convert('RGB')
    px = im.load()
    W, H = im.size
    stats = {'black': 0, 'white': 0, 'yellow': 0, 'red': 0, 'other': 0}
    text_rows = {'yellow': 0, 'red': 0}  # 文字区 y=15..115
    for y in range(H):
        for x in range(W):
            r, g, b = px[x, y]
            if (r, g, b) == (0, 0, 0):
                c = 'black'
            elif (r, g, b) == (255, 255, 255):
                c = 'white'
            elif (r, g, b) == (255, 255, 0):
                c = 'yellow'
            elif (r, g, b) == (255, 0, 0):
                c = 'red'
            else:
                c = 'other'
            stats[c] += 1
            if c in ('yellow', 'red') and 15 <= y <= 115:
                text_rows[c] += 1
    total = W * H
    print('--- %s ---' % label)
    for k in ('black', 'white', 'yellow', 'red', 'other'):
        print('  %-7s %6d (%d%%)' % (k, stats[k], stats[k] * 100 // total))
    n = text_rows['yellow'] + text_rows['red']
    print('  文字区(y15-115)彩色噪点: 黄%d + 红%d = %d' %
          (text_rows['yellow'], text_rows['red'], n))


analyze(HERE / '_text_nodither.png', '关抖动')
analyze(HERE / '_text_dither.png', '开抖动')

