  testInfo += "Persistent Value: " + String(getPersistentValue("PCB_TEST", "PCB test persistent value is not OK!")) + "\n";

  showTextOnScreenCenter(testInfo);

  delay(5 * 60 * 1000);
#endif // ENABLE_PCB_TEST
}

void loop()
{
  buttonLoop();
  wifiManager.process();

  if (wifiManager.getConfigPortalActive())
  {
    return;
  }

  // Network reconnecting
  if (WiFi.status() != WL_CONNECTED)
  {
    if (initWifiWithManager())
    {
      setClock();
    }
    else
    {
      return;
    }
  }

  // every 60 seconds
  time_t now = time(nullptr);
  if (now - runningValue.lastCheck > 60 && !updating)
  {

#ifdef ENABLE_OTA
    updateFiles();
    updateFireWare();
#endif

    updating = true;
    downloadAndDrawTodo();
    updating = false;
  }
}
```

This is an Arduino sketch for an ESP8266-based e-paper todo list display device. The `setup()` function initializes serial communication, filesystem (LittleFS), WiFi (via a captive portal manager), NTP clock, display, buttons, and persistent storage. The `loop()` handles button input, WiFi reconnection, and every 60 seconds downloads and renders the todo list. It also supports optional OTA firmware/file updates and a PCB test mode, both controlled by preprocessor defines.

