137	esp_err_t sd_card_mount(int slot, const char * mount_point)
138	{
139	    esp_err_t ret;
140	
141	    if (!mount_point) {
142	        ESP_LOGE(TAG, "No mount point provided");
143	        return ESP_FAIL;
144	    }
145	
146	#if CONFIG_IDF_TARGET_ESP32P4
147	    // on ESP32-P4 Dev Board, the SDCard is on SDMMC Slot 0
148	    // ESP-Hosted uses SDMMC Slot 1
149	    if (slot != SDMMC_HOST_SLOT_0) {
150	        ESP_LOGE(TAG, "For ESP32-P4, SD Card slot should be SDMMC_HOST_SLOT_0");
151	        return ESP_FAIL;
152	    }
153	#endif
154	
155	    // Options for mounting the filesystem.
156	    esp_vfs_fat_sdmmc_mount_config_t mount_config = {
157	        .format_if_mount_failed = false,
158	        .max_files = 5,
159	        .allocation_unit_size = 16 * 1024
160	    };
161	    ESP_LOGI(TAG, "Initializing SD card");
162	
163	    // Use settings defined above to initialize SD card and mount FAT filesystem.
164	    // Note: esp_vfs_fat_sdmmc/sdspi_mount is all-in-one convenience functions.
165	    // Please check its source code and implement error recovery when developing
166	    // production applications.
167	
168	    ESP_LOGI(TAG, "Using SDMMC peripheral");
169	
170	    // By default, SD card frequency is initialized to SDMMC_FREQ_DEFAULT (20MHz)
171	    // For setting a specific frequency, use host.max_freq_khz (range 400kHz - 40MHz for SDMMC)
172	    // Example: for fixed frequency of 10MHz, use host.max_freq_khz = 10000;
173	    sdmmc_host_t host = SDMMC_HOST_DEFAULT();
174	    host.slot = slot;
175	#if WORKAROUND_HOSTED_DOES_SDMMC_HOST_INIT
176	    // The host controller is already managed by ESP-Hosted, so there is no need to add init and deinit again.
177	    host.init = &sdmmc_host_init_dummy;
178	    host.deinit = &sdmmc_host_deinit_dummy;
179	#endif
180	
181	    // For SoCs where the SD power can be supplied both via an internal or external (e.g. on-board LDO) power supply.
182	    // When using specific IO pins (which can be used for ultra high-speed SDMMC) to connect to the SD card
183	    // and the internal LDO power supply, we need to initialize the power supply first.
184	#if CONFIG_EXAMPLE_SD_PWR_CTRL_LDO_INTERNAL_IO
185	    sd_pwr_ctrl_ldo_config_t ldo_config = {
186	        .ldo_chan_id = CONFIG_EXAMPLE_SD_PWR_CTRL_LDO_IO_ID,
187	    };
188	
189	    ret = sd_pwr_ctrl_new_on_chip_ldo(&ldo_config, &pwr_ctrl_handle);
190	    if (ret != ESP_OK) {
191	        ESP_LOGE(TAG, "Failed to create a new on-chip LDO power control driver");
192	        return ret;
193	    }
194	    host.pwr_ctrl_handle = pwr_ctrl_handle;
195	#endif
196	
197	#if CONFIG_EXAMPLE_PIN_CARD_POWER_RESET
198	    ESP_ERROR_CHECK(sd_card_reset_card_power());
199	#endif
200	
201	    // This initializes the slot without card detect (CD) and write protect (WP) signals.
202	    // Modify slot_config.gpio_cd and slot_config.gpio_wp if your board has these signals.
203	    sdmmc_slot_config_t slot_config = SDMMC_SLOT_CONFIG_DEFAULT();
204	    // Set bus width to use:
205	#ifdef CONFIG_EXAMPLE_SDMMC_BUS_WIDTH_4
206	    slot_config.width = 4;
207	#else
208	    slot_config.width = 1;
209	#endif
210	
211	    // On chips where the GPIOs used for SD card can be configured, set them in
212	    // the slot_config structure:
213	#ifdef CONFIG_SOC_SDMMC_USE_GPIO_MATRIX
214	    slot_config.clk = CONFIG_EXAMPLE_PIN_CLK;
215	    slot_config.cmd = CONFIG_EXAMPLE_PIN_CMD;
216	    slot_config.d0 = CONFIG_EXAMPLE_PIN_D0;
217	#ifdef CONFIG_EXAMPLE_SDMMC_BUS_WIDTH_4
218	    slot_config.d1 = CONFIG_EXAMPLE_PIN_D1;
219	    slot_config.d2 = CONFIG_EXAMPLE_PIN_D2;
220	    slot_config.d3 = CONFIG_EXAMPLE_PIN_D3;
221	#endif  // CONFIG_EXAMPLE_SDMMC_BUS_WIDTH_4
222	#endif  // CONFIG_SOC_SDMMC_USE_GPIO_MATRIX
223	
224	    // Enable internal pullups on enabled pins. The internal pullups
225	    // are insufficient however, please make sure 10k external pullups are
226	    // connected on the bus. This is for debug / example purpose only.
227	    slot_config.flags |= SDMMC_SLOT_FLAG_INTERNAL_PULLUP;
228	
229	    ESP_LOGI(TAG, "Mounting filesystem");
230	    ret = esp_vfs_fat_sdmmc_mount(mount_point, &host, &slot_config, &mount_config, &card);
231	
232	    if (ret != ESP_OK) {
233	        if (ret == ESP_FAIL) {
234	            ESP_LOGE(TAG, "Failed to mount filesystem. ");
235	        } else {
236	            ESP_LOGE(TAG, "Failed to initialize the card (%s). "
237	                     "Make sure SD card lines have pull-up resistors in place.", esp_err_to_name(ret));
238	        }
239	        return ret;
240	    }
241	
242	    ESP_LOGI(TAG, "Filesystem mounted");
243	
244	    // Card has been initialized, print its properties
245	    sdmmc_card_print_info(stdout, card);
246	
247	    return ESP_OK;
248	}
