28	/* 正弦波相位累积器（运行时用 sinf 计算，简单准确）*/
29	
30	static esp_err_t i2s_driver_init(void)
31	{
32	    i2s_chan_config_t chan_cfg = I2S_CHANNEL_DEFAULT_CONFIG(ES8311_I2S_PORT, I2S_ROLE_MASTER);
33	    chan_cfg.auto_clear = true;
34	    ESP_RETURN_ON_ERROR(i2s_new_channel(&chan_cfg, &s_tx_handle, &s_rx_handle),
35	                        TAG, "i2s new channel fail");
36	    i2s_std_config_t std_cfg = {
37	        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(ES8311_SAMPLE_RATE),
38	        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_STEREO),
39	        .gpio_cfg = {
40	            .mclk = ES8311_I2S_MCLK_IO,
41	            .bclk = ES8311_I2S_BCLK_IO,
42	            .ws   = ES8311_I2S_WS_IO,
43	            .dout = ES8311_I2S_DOUT_IO,
44	            .din  = ES8311_I2S_DIN_IO,
45	            .invert_flags = {
46	                .mclk_inv = false,
47	                .bclk_inv = false,
48	                .ws_inv   = false,
49	            },
50	        },
51	    };
52	    /* mclk_multiple 保持默认 256（16bit 数据 256 够用）。
53	     * 注意：esp_codec_dev_open 会用 sample_info.mclk_multiple 重配时钟，
54	     * 必须与 es8311 的 mclk_div 一致，否则 codec 内部时钟错位无声 */
55	
56	    ESP_RETURN_ON_ERROR(i2s_channel_init_std_mode(s_tx_handle, &std_cfg),
57	                        TAG, "i2s tx init fail");
58	    ESP_RETURN_ON_ERROR(i2s_channel_init_std_mode(s_rx_handle, &std_cfg),
59	                        TAG, "i2s rx init fail");
60	    ESP_RETURN_ON_ERROR(i2s_channel_enable(s_tx_handle), TAG, "i2s tx enable fail");
61	    ESP_RETURN_ON_ERROR(i2s_channel_enable(s_rx_handle), TAG, "i2s rx enable fail");
62	    return ESP_OK;
63	}
