65	static esp_err_t es8311_codec_init_internal(void)
66	{
67	    /* 复用摄像头已创建的 I2C_NUM_0 总线，不再新建 */
68	    i2c_master_bus_handle_t i2c_bus_handle = NULL;
69	    ESP_RETURN_ON_ERROR(i2c_master_get_bus_handle(ES8311_I2C_PORT, &i2c_bus_handle),
70	                        TAG, "获取 I2C 总线句柄失败，确保 cam_capture_init() 先执行");
71	
72	    /* I2C 控制接口 */
73	    audio_codec_i2c_cfg_t i2c_cfg = {
74	        .port = ES8311_I2C_PORT,
75	        .addr = ES8311_CODEC_DEFAULT_ADDR,
76	        .bus_handle = i2c_bus_handle,
77	    };
78	    const audio_codec_ctrl_if_t *ctrl_if = audio_codec_new_i2c_ctrl(&i2c_cfg);
79	    ESP_RETURN_ON_FALSE(ctrl_if, ESP_FAIL, TAG, "i2c ctrl if fail");
80	
81	    /* I2S 数据接口 */
82	    audio_codec_i2s_cfg_t i2s_cfg = {
83	        .port = ES8311_I2S_PORT,
84	        .rx_handle = s_rx_handle,
85	        .tx_handle = s_tx_handle,
86	    };
87	    const audio_codec_data_if_t *data_if = audio_codec_new_i2s_data(&i2s_cfg);
88	    ESP_RETURN_ON_FALSE(data_if, ESP_FAIL, TAG, "i2s data if fail");
89	
90	    /* GPIO 接口（PA 控制）*/
91	    const audio_codec_gpio_if_t *gpio_if = audio_codec_new_gpio();
92	    ESP_RETURN_ON_FALSE(gpio_if, ESP_FAIL, TAG, "gpio if fail");
93	
94	    /* ES8311 配置 */
95	    es8311_codec_cfg_t es8311_cfg = {
96	        .ctrl_if = ctrl_if,
97	        .gpio_if = gpio_if,
98	        .codec_mode = ESP_CODEC_DEV_WORK_MODE_BOTH,
99	        .master_mode = false,
100	        .use_mclk = ES8311_I2S_MCLK_IO >= 0,
101	        .pa_pin = ES8311_PA_CTRL_IO,
102	        .pa_reverted = false,
103	        .hw_gain = {
104	            .pa_voltage = 5.0,
105	            .codec_dac_voltage = 3.3,
106	        },
107	        .mclk_div = 256,
108	    };
109	    const audio_codec_if_t *es8311_if = es8311_codec_new(&es8311_cfg);
110	    ESP_RETURN_ON_FALSE(es8311_if, ESP_FAIL, TAG, "es8311 new fail");
111	
112	    esp_codec_dev_cfg_t dev_cfg = {
113	        .dev_type = ESP_CODEC_DEV_TYPE_IN_OUT,
114	        .codec_if = es8311_if,
115	        .data_if = data_if,
116	    };
117	    s_codec_handle = esp_codec_dev_new(&dev_cfg);
118	    ESP_RETURN_ON_FALSE(s_codec_handle, ESP_FAIL, TAG, "codec dev new fail");
119	
120	    esp_codec_dev_sample_info_t sample_cfg = {
121	        .bits_per_sample = ES8311_BITS_PER_SAMPLE,
122	        .channel = ES8311_CHANNELS,
123	        .channel_mask = 0x03,
124	        .sample_rate = ES8311_SAMPLE_RATE,
125	        .mclk_multiple = 256,   /* 与 es8311 mclk_div 一致 */
126	    };
127	    if (esp_codec_dev_open(s_codec_handle, &sample_cfg) != ESP_CODEC_DEV_OK) {
128	        ESP_LOGE(TAG, "codec open fail");
129	        return ESP_FAIL;
130	    }
131	    esp_codec_dev_set_out_vol(s_codec_handle, 90);
132	    return ESP_OK;
133	}
