135	esp_err_t es8311_codec_init(void)
136	{
137	    ESP_RETURN_ON_ERROR(i2s_driver_init(), TAG, "I2S driver init fail");
138	    ESP_RETURN_ON_ERROR(es8311_codec_init_internal(), TAG, "ES8311 codec init fail");
139	    ESP_LOGI(TAG, "ES8311 初始化完成 %dHz/%dbit/%dch",
140	             ES8311_SAMPLE_RATE, ES8311_BITS_PER_SAMPLE, ES8311_CHANNELS);
141	    return ESP_OK;
142	}
143	
144	esp_err_t es8311_play_tone(int freq_hz, int duration_ms)
145	{
146	    if (!s_tx_handle) return ESP_ERR_INVALID_STATE;
147	
148	    /* 一帧缓冲：每个采样 = 2字节×2声道 = 4字节，取 1024 采样 = 4096 字节 */
149	    const int samples_per_frame = 1024;
150	    const int frame_bytes = samples_per_frame * 4;
151	    int16_t *buf = malloc(frame_bytes);
152	    if (!buf) return ESP_ERR_NO_MEM;
153	
154	    int total_samples = ES8311_SAMPLE_RATE * duration_ms / 1000;
155	    int written = 0;
156	    float phase = 0.0f;
157	    float phase_step = 2.0f * 3.14159265f * freq_hz / ES8311_SAMPLE_RATE;
158	
159	    while (written < total_samples) {
160	        int n = samples_per_frame;
161	        if (written + n > total_samples) n = total_samples - written;
162	
163	        for (int i = 0; i < n; i++) {
164	            int16_t sample = (int16_t)(sinf(phase) * 32767.0f);
165	            buf[i * 2]     = sample;  /* 左声道 */
166	            buf[i * 2 + 1] = sample;  /* 右声道 */
167	            phase += phase_step;
168	        }
169	        size_t bytes_write = 0;
170	        esp_err_t ret = i2s_channel_write(s_tx_handle, buf, n * 4, &bytes_write, 1000);
171	        if (ret != ESP_OK) {
172	            free(buf);
173	            ESP_LOGE(TAG, "tone write fail[%d]", ret);
174	            return ret;
175	        }
176	        written += n;
177	    }
178	
179	    free(buf);
180	    return ESP_OK;
181	}
182	
183	esp_err_t es8311_play_pcm(const uint8_t *data, size_t len)
184	{
185	    if (!s_tx_handle || !data || len == 0) return ESP_ERR_INVALID_ARG;
186	    if (len % 2) len -= 1;  /* 单声道 int16 样本对齐 */
187	
188	    /* 单声道展开到立体声：I2S 是双声道槽位，左右填同一样本 */
189	    const int samples_per_chunk = 1024;
190	    int16_t *buf = malloc(samples_per_chunk * 4);
191	    if (!buf) return ESP_ERR_NO_MEM;
192	
193	    const int16_t *src = (const int16_t *)data;
194	    int total_samples = len / 2;
195	    int done = 0;
196	
197	    while (done < total_samples) {
198	        int n = total_samples - done;
199	        if (n > samples_per_chunk) n = samples_per_chunk;
200	        for (int i = 0; i < n; i++) {
201	            buf[i * 2]     = src[done + i];  /* 左声道 */
202	            buf[i * 2 + 1] = src[done + i];  /* 右声道 */
203	        }
204	        size_t bytes_write = 0;
205	        esp_err_t ret = i2s_channel_write(s_tx_handle, buf, n * 4, &bytes_write, 2000);
206	        if (ret != ESP_OK) {
207	            free(buf);
208	            ESP_LOGE(TAG, "pcm write fail[%d]", ret);
209	            return ret;
210	        }
211	        done += n;
212	    }
213	
214	    free(buf);
215	    return ESP_OK;
216	}
