1	/*
2	 * tcp_server.cpp - 以太网 TCP Server，接收拍照命令并回传 JPG
3	 *
4	 * 协议（极简，TCP 自带可靠传输）：
5	 *   客户端发: "CAPTURE\n"
6	 *   服务端回: 4 字节 uint32_t (小端) JPG 长度 + JPG 数据
7	 *
8	 * 端口: 8080
9	 * Python 端: tools/capture_tcp.py
10	 */
11	#include "tcp_server.h"
12	#include "camera_capture.h"
13	#include "jpeg_encoder.h"
14	
15	#include <string.h>
16	#include <errno.h>
17	#include "freertos/FreeRTOS.h"
18	#include "freertos/task.h"
19	#include "esp_log.h"
20	#include "lwip/sockets.h"
21	#include "lwip/netdb.h"
22	
23	static const char *TAG = "tcp_srv";
24	#define TCP_PORT 8080
25	#define RECV_BUF_SIZE 64
26	
27	static cam_capture_t *s_cam = NULL;
28	
29	static void handle_client(int sock)
30	{
31	    char buf[RECV_BUF_SIZE];
32	    int len = recv(sock, buf, sizeof(buf) - 1, 0);
33	    if (len <= 0) {
34	        close(sock);
35	        return;
36	    }
37	    buf[len] = '\0';
38	    ESP_LOGI(TAG, "收到命令: %s", buf);
39	
40	    /* 简单匹配 "CAPTURE" */
41	    if (strncmp(buf, "CAPTURE", 7) != 0) {
42	        ESP_LOGW(TAG, "未知命令: %s", buf);
43	        const char *err = "ERROR: unknown command\n";
44	        send(sock, err, strlen(err), 0);
45	        close(sock);
46	        return;
47	    }
48	
49	    /* 1. 拍照 */
50	    ESP_LOGI(TAG, "开始拍照...");
51	    uint8_t *fb = NULL;
52	    size_t fb_len = 0;
53	    esp_err_t e = cam_capture_one_frame(s_cam, &fb, &fb_len);
54	    if (e != ESP_OK || !fb) {
55	        ESP_LOGE(TAG, "拍照失败[%d]", e);
