/*
 * sd_storage - SD 卡存储（SDMMC SLOT_0 + FATFS），拍照/录音落卡
 *
 * 硬件（SD1）：
 *   D0-D3 = GPIO39-42, CLK = GPIO43, CMD = GPIO44
 *   SD_DET 是测试点未接 MCU → 无卡检测，开机直接尝试挂载
 *   SD_PWRn = GPIO45（低电平=供电；若卡始终不识别，优先怀疑极性）
 *
 * 与 ESP-Hosted 共存（C6 SDIO 占 SLOT_1，GPIO14-19）：
 *   IDF>=6.0 全局 sdmmc_host_init() 只能调一次，ESP-Hosted 构造函数
 *   （CONFIG_ESP_HOSTED_AUTO_CALL_INIT_BEFORE_APP_MAIN）已在 app_main 前调过，
 *   所以这里 host.init/deinit 置 dummy（esp_hosted 官方共存例程同款处理）。
 */
#include <stdio.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <time.h>
#include <sys/stat.h>
#include "sdkconfig.h"
#include "esp_log.h"
#include "driver/gpio.h"
#include "driver/sdmmc_host.h"
#include "sdmmc_cmd.h"
#include "esp_vfs_fat.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "time_announce.h"
#include "sd_storage.h"

static const char *TAG = "sd_storage";

#define SD_PWR_GPIO     45      /* SD_PWRn：低电平=供电 */
#define SD_PIN_D0       39
#define SD_PIN_D1       40
#define SD_PIN_D2       41
#define SD_PIN_D3       42
#define SD_PIN_CLK      43
#define SD_PIN_CMD      44

static sdmmc_card_t *s_card = NULL;

static esp_err_t sdmmc_host_init_dummy(void)  { return ESP_OK; }
static esp_err_t sdmmc_host_deinit_dummy(void) { return ESP_OK; }

/* SD_PWRn 低有效：先拉高 100ms 做上电复位，再拉低供电、等卡启动 */
static void sd_power_on(void)
{
    gpio_config_t io = {};
    io.pin_bit_mask = 1ULL << SD_PWR_GPIO;
    io.mode = GPIO_MODE_OUTPUT;
    gpio_config(&io);
    gpio_set_level(SD_PWR_GPIO, 1);
    vTaskDelay(pdMS_TO_TICKS(100));
    gpio_set_level(SD_PWR_GPIO, 0);        /* 低=供电 */
    vTaskDelay(pdMS_TO_TICKS(250));
}

esp_err_t sd_storage_init(void)
{
    if (s_card) return ESP_OK;

    sd_power_on();

    esp_vfs_fat_sdmmc_mount_config_t mount_config = {
        .format_if_mount_failed = false,   /* 不自动格式化，防误删卡内数据 */
        .max_files = 5,
        .allocation_unit_size = 16 * 1024,
    };
    sdmmc_host_t host = SDMMC_HOST_DEFAULT();
    host.slot = SDMMC_HOST_SLOT_0;         /* SLOT_1 被 ESP-Hosted(C6) 占用 */
    host.init = sdmmc_host_init_dummy;     /* 全局 init 已由 ESP-Hosted 完成 */
    host.deinit = sdmmc_host_deinit_dummy;

    sdmmc_slot_config_t slot_config = SDMMC_SLOT_CONFIG_DEFAULT();
    slot_config.width = 4;
    slot_config.clk = SD_PIN_CLK;
    slot_config.cmd = SD_PIN_CMD;
    slot_config.d0 = SD_PIN_D0;
    slot_config.d1 = SD_PIN_D1;
    slot_config.d2 = SD_PIN_D2;
    slot_config.d3 = SD_PIN_D3;
    slot_config.flags |= SDMMC_SLOT_FLAG_INTERNAL_PULLUP;  /* 内部上拉偏弱，板上最好有 10K 外部上拉 */

    esp_err_t ret = esp_vfs_fat_sdmmc_mount(SD_MOUNT_POINT, &host, &slot_config,
                                            &mount_config, &s_card);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "SD 挂载失败[%s]（无卡？卡不是 FAT32？SD_PWRn 极性？），继续运行",
                 esp_err_to_name(ret));
        s_card = NULL;
        return ESP_ERR_NOT_FOUND;
    }

    ESP_LOGI(TAG, "SD 已挂载 " SD_MOUNT_POINT);
    sdmmc_card_print_info(stdout, s_card);

    mkdir(SD_MOUNT_POINT "/photo", 0775);
    mkdir(SD_MOUNT_POINT "/rec", 0775);
    return ESP_OK;
}

bool sd_storage_is_mounted(void)
{
    return s_card != NULL;
}

bool sd_storage_info(uint32_t *cap_mb, uint32_t *free_mb)
{
    if (!s_card) return false;
    uint64_t total = 0, free_b = 0;
    if (esp_vfs_fat_info(SD_MOUNT_POINT, &total, &free_b) != ESP_OK) return false;
    if (cap_mb)  *cap_mb  = (uint32_t)(total >> 20);
    if (free_mb) *free_mb = (uint32_t)(free_b >> 20);
    return true;
}

/* 扫目录找 <prefix><纯数字>.<ext> 命名的最大序号（未对时时的兜底命名，
 * 时间戳文件名带 '_' 不会被误匹配） */
static int scan_max_index(const char *dirpath, const char *prefix)
{
    DIR *d = opendir(dirpath);
    if (!d) return 0;
    size_t plen = strlen(prefix);
    int max = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strncmp(ent->d_name, prefix, plen) != 0) continue;
        const char *s = ent->d_name + plen;
        const char *dot = strchr(s, '.');
        if (!dot || dot == s) continue;
        bool all_digits = true;
        for (const char *p = s; p < dot; p++) {
            if (*p < '0' || *p > '9') { all_digits = false; break; }
        }
        if (all_digits) {
            int n = atoi(s);
            if (n > max) max = n;
        }
    }
    closedir(d);
    return max;
}

esp_err_t sd_storage_gen_path(char *out, size_t out_len,
                              const char *subdir, const char *prefix, const char *ext)
{
    if (!s_card) return ESP_ERR_INVALID_STATE;

    char dir[48];
    snprintf(dir, sizeof(dir), SD_MOUNT_POINT "/%s", subdir);

    if (time_announce_has_time()) {
        time_t now = time(NULL);
        struct tm tm;
        localtime_r(&now, &tm);
        char stamp[24];
        strftime(stamp, sizeof(stamp), "%Y%m%d_%H%M%S", &tm);
        snprintf(out, out_len, "%s/%s_%s.%s", dir, prefix, stamp, ext);
        if (access(out, F_OK) != 0) return ESP_OK;   /* 不存在 → 可用 */
        /* 同秒已有文件（连拍），落到序号命名 */
    }
    int idx = scan_max_index(dir, prefix) + 1;
    snprintf(out, out_len, "%s/%s%05d.%s", dir, prefix, idx, ext);
    return ESP_OK;
}

esp_err_t sd_storage_write_file(const char *path, const void *data, size_t len)
{
    if (!s_card) return ESP_ERR_INVALID_STATE;
    FILE *f = fopen(path, "wb");
    if (!f) {
        ESP_LOGW(TAG, "打开 %s 失败", path);
        return ESP_FAIL;
    }
    size_t w = fwrite(data, 1, len, f);
    fclose(f);
    return (w == len) ? ESP_OK : ESP_FAIL;
}

