/* ---- 录音（mic → I2S RX → WAV 落盘）---- */

typedef struct __attribute__((packed)) {
    char     riff[4];       /* "RIFF" */
    uint32_t chunk_size;    /* 36 + data_size */
    char     wave[4];       /* "WAVE" */
    char     fmt[4];        /* "fmt " */
    uint32_t fmt_size;      /* 16 */
    uint16_t format;        /* 1 = PCM */
    uint16_t channels;      /* 1 */
    uint32_t sample_rate;
    uint32_t byte_rate;     /* sample_rate * 2 */
    uint16_t block_align;   /* 2 */
    uint16_t bits;          /* 16 */
    char     data[4];       /* "data" */
    uint32_t data_size;
} wav_header_t;

esp_err_t es8311_record_wav(const char *path, int seconds, size_t *out_bytes)
{
    if (!s_rx_handle || !path || seconds <= 0) return ESP_ERR_INVALID_ARG;
    if (seconds > 60) seconds = 60;

    FILE *f = fopen(path, "wb");
    if (!f) {
        ESP_LOGE(TAG, "录音: 打开 %s 失败", path);
        return ESP_FAIL;
    }

    esp_codec_dev_set_in_gain(s_codec_handle, ES8311_MIC_GAIN_DB);

    wav_header_t hdr = {
        .riff = "RIFF", .wave = "WAVE", .fmt = "fmt ", .data = "data",
        .fmt_size = 16, .format = 1, .channels = 1,
        .sample_rate = ES8311_SAMPLE_RATE,
        .byte_rate = ES8311_SAMPLE_RATE * 2,
        .block_align = 2, .bits = 16,
    };
    fwrite(&hdr, sizeof(hdr), 1, f);

    const int frames_per_chunk = 1024;      /* 立体声帧数 */
    int16_t *stereo = malloc(frames_per_chunk * 4);
    int16_t *mono   = malloc(frames_per_chunk * 2);
    if (!stereo || !mono) {
        free(stereo); free(mono); fclose(f);
        return ESP_ERR_NO_MEM;
    }

    int total_frames = ES8311_SAMPLE_RATE * seconds;
    int done = 0;
    while (done < total_frames) {
        int want = frames_per_chunk;
        if (want > total_frames - done) want = total_frames - done;
        size_t bytes_read = 0;
        esp_err_t ret = i2s_channel_read(s_rx_handle, stereo, want * 4,
                                         &bytes_read, 1000);
        if (ret != ESP_OK) {
            ESP_LOGE(TAG, "i2s read fail[%d]", ret);
            break;
        }
        int got = bytes_read / 4;           /* 实际立体声帧数 */
        for (int i = 0; i < got; i++) {
            mono[i] = stereo[i * 2];        /* 取左声道（mic 单声道占一个槽位）*/
        }
        fwrite(mono, 2, got, f);
        done += got;
    }
    free(stereo);
    free(mono);

    /* 回填实际长度 */
    uint32_t data_bytes = (uint32_t)done * 2;
    hdr.data_size = data_bytes;
    hdr.chunk_size = 36 + data_bytes;
    fseek(f, 0, SEEK_SET);
    fwrite(&hdr, sizeof(hdr), 1, f);
    fclose(f);

    ESP_LOGI(TAG, "录音完成: %s（%.1fs/%dB）", path,
             done / (float)ES8311_SAMPLE_RATE, data_bytes);
    if (out_bytes) *out_bytes = sizeof(hdr) + data_bytes;
    return ESP_OK;
}

