/* ---- REC <秒>：一次性录音任务（录完自删，不阻塞命令通道）---- */
static volatile bool s_recording = false;

static void rec_task(void *arg)
{
    int secs = (int)(intptr_t)arg;
    char path[64];
    char resp[96];

    if (sd_storage_gen_path(path, sizeof(path), "rec", "R", "wav") == ESP_OK) {
        size_t wlen = 0;
        esp_err_t e = es8311_record_wav(path, secs, &wlen);
        if (e == ESP_OK) {
            snprintf(resp, sizeof(resp), "OK REC %s %uB", path, (unsigned)wlen);
        } else {
            snprintf(resp, sizeof(resp), "ERR REC %d", e);
        }
    } else {
        snprintf(resp, sizeof(resp), "ERR REC PATH");
    }
    spp_send_response(resp);

    s_recording = false;
    vTaskDelete(NULL);
}

