#include "epaper_image.h"
#include "epaper_text.h"   // EPAPER_WIDTH/HEIGHT/BYTES_PER_ROW

/* 四色调色板 (RGB888)，下标=墨水屏 2bit 色号：0黑 1白 2黄 3红 */
static const int8_t PAL_R[4] = {  0, 255, 255,   0};
static const int8_t PAL_G[4] = {  0, 255, 255,   0};
static const int8_t PAL_B[4] = {  0, 255,   0, 255};

static uint8_t nearest_color(int r, int g, int b)
{
    uint8_t best = 0;
    int best_d = INT_MAX;  // hmm include <limits.h> or use large const
    for (int i = 0; i < 4; i++) {
        int dr = r - PAL_R[i], dg = g - PAL_G[i], db = b - PAL_B[i];
        int d = dr*dr + dg*dg + db*db;
        if (d < best_d) { best_d = d; best = (uint8_t)i; }
    }
    return best;
}

static void fb_set(uint8_t *fb, int x, int y, uint8_t color)
{
    if (x < 0 || x >= EPAPER_WIDTH || y < 0 || y >= EPAPER_HEIGHT) return;
    int idx = y * EPAPER_BYTES_PER_ROW + x / 4;
    int shift = 6 - 2 * (x % 4);
    fb[idx] = (fb[idx] & ~(0x3 << shift)) | (color << shift);
}

void epaper_fb_draw_rgb565(uint8_t *fb, int dst_x, int dst_y,
                           const uint8_t *src, int src_w, int src_h, bool dither)
{
    if (!fb || !src || src_w <= 0 || src_h <= 0) return;

    /* 误差行缓存（当前行/下一行，各 3 通道）*/
    int *err_cur = NULL, *err_next = NULL;
    if (dither) {
        err_cur = (int *)calloc((size_t)src_w * 3, sizeof(int));
        err_next = (int *)calloc((size_t)src_w * 3, sizeof(int));
        if (!err_cur || !err_next) {  // 内存不足退化为不抖动
            free(err_cur); free(err_next);
            err_cur = err_next = NULL;
            dither = false;
        }
    }

    for (int row = 0; row < src_h; row++) {
        for (int col = 0; col < src_w; col++) {
            uint16_t px = (uint16_t)(src[(row * src_w + col) * 2] |
                                     (src[(row * src_w + col) * 2 + 1] << 8));
            int r = ((px >> 11) & 0x1F) * 255 / 31;
            int g = ((px >> 5) & 0x3F) * 255 / 63;
            int b = (px & 0x1F) * 255 / 31;

            if (dither) {
                r += err_cur[col * 3]; if (r < 0) r = 0; else if (r > 255) r = 255;
                g += err_cur[col*3+1]; ...
                b += ...
            }
            uint8_t c = nearest_color(r, g, b);
            fb_set(fb, dst_x + col, dst_y + row, c);

            if (dither) {
                int er = r - PAL_R[c], eg = g - PAL_G[c], eb = b - PAL_B[c];
                int *ec = err_cur, *en = err_next;
                // 7/16 右
                if (col + 1 < src_w) { ec[(col+1)*3] += er*7>>4; ... }
                // 3/16 左下
                if (col - 1 >= 0) { en[(col-1)*3] += er*3>>4; ...}
                // 5/16 下
                en[col*3] += er*5>>4; ...
                // 1/16 右下
                if (col + 1 < src_w) { en[(col+1)*3] += er*1>>4; ...}
            }
        }
        if (dither) {
            int *t = err_cur; err_cur = err_next; err_next = t;
            memset(err_next, 0, src_w*3*sizeof(int));
        }
    }
    free(err_cur); free(err_next);
