/**
 * Quantize an RGB565 (little-endian) image into the 2-bit 4-color frame
 * buffer, drawn at (dst_x, dst_y). Pixels outside the 184x384 panel are
 * clipped. Existing buffer content outside the image is preserved, so the
 * image layers on top of a cleared background like text does.
 *
 * dither=true uses Floyd-Steinberg error diffusion (smoother photos);
 * dither=false picks the nearest palette color directly (crisper line art).
 */
void epaper_fb_draw_rgb565(uint8_t *fb, int dst_x, int dst_y,
                           const uint8_t *src, int src_w, int src_h,
                           bool dither);

#ifdef __cplusplus
}
#endif

/*
 * SPDX-FileCopyrightText: 2026 Espressif Systems (Shanghai) CO LTD
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * RGB565 -> 4-color (black/white/yellow/red) quantization with optional
 * Floyd-Steinberg dithering. Port of the vela-esp32 project's
 * tools/img2epd.py converter, so on-screen results match the PC pipeline.
 */
#include "epaper_image.h"

#include <stdlib.h>
#include <string.h>

#include "epaper_text.h"

/* Palette in RGB888, index = 2-bit panel color code. */
#define PAL_BLACK 0
#define PAL_WHITE 1
#define PAL_YELLOW 2
#define PAL_RED 3
static const int PAL_R[4] = {  0, 255, 255,   0};
static const int PAL_G[4] = {  0, 255, 255,   0};
static const int PAL_B[4] = {  0, 255,   0, 255};

static uint8_t nearest_color(int r, int g, int b)
{
    uint8_t best = PAL_BLACK;
    int best_d = r * r + g * g + b * b + (255 * 255) * 3; /* > any distance */
    for (int i = 0; i < 4; i++) {
        int dr = r - PAL_R[i];
        int dg = g - PAL_G[i];
        int db = b - PAL_B[i];
        int d = dr * dr + dg * dg + db * db;
        if (d < best_d) {
            best_d = d;
            best = (uint8_t)i;
        }
    }
    return best;
}

/* Read-modify-write one 2-bit pixel into the packed frame buffer. */
static void fb_set(uint8_t *fb, int x, int y, uint8_t color)
{
    if (x < 0 || x >= EPAPER_WIDTH || y < 0 || y >= EPAPER_HEIGHT) {
        return;
    }
    int idx = y * EPAPER_BYTES_PER_ROW + x / 4;
    int shift = 6 - 2 * (x % 4);
    fb[idx] = (uint8_t)((fb[idx] & ~(0x3 << shift)) | (color << shift));
}

void epaper_fb_draw_rgb565(uint8_t *fb, int dst_x, int dst_y,
                           const uint8_t *src, int src_w, int src_h,
                           bool dither)
{
    if (!fb || !src || src_w <= 0 || src_h <= 0) {
        return;
    }

    /* Two rolling error rows (current / next), 3 channels per pixel. */
    int *err_cur = NULL;
    int *err_next = NULL;
    if (dither) {
        err_cur = (int *)calloc((size_t)src_w * 3, sizeof(int));
        err_next = (int *)calloc((size_t)src_w * 3, sizeof(int));
        if (!err_cur || !err_next) {
            /* Out of memory: fall back to plain nearest-color. */
            free(err_cur);
            free(err_next);
            err_cur = err_next = NULL;
            dither = false;
        }
    }

    for (int row = 0; row < src_h; row++) {
        const uint8_t *srow = src + (size_t)row * src_w * 2;
        for (int col = 0; col < src_w; col++) {
            uint16_t px = (uint16_t)(srow[col * 2] | (srow[col * 2 + 1] << 8));
            int r = ((px >> 11) & 0x1F) * 255 / 31;
            int g = ((px >> 5) & 0x3F) * 255 / 63;
            int b = (px & 0x1F) * 255 / 31;

            if (dither) {
                r += err_cur[col * 3 + 0];
                g += err_cur[col * 3 + 1];
                b += err_cur[col * 3 + 2];
                if (r < 0) r = 0; else if (r > 255) r = 255;
                if (g < 0) g = 0; else if (g > 255) g = 255;
                if (b < 0) b = 0; else if (b > 255) b = 255;
            }

            uint8_t c = nearest_color(r, g, b);
            fb_set(fb, dst_x + col, dst_y + row, c);

            if (dither) {
                int er = r - PAL_R[c];
                int eg = g - PAL_G[c];
                int eb = b - PAL_B[c];
                /* Floyd-Steinberg: 7/16 right, 3/16 left-down,
                 * 5/16 down, 1/16 right-down (>>4 == //16, floor). */
                if (col + 1 < src_w) {
                    err_cur[(col + 1) * 3 + 0] += (er * 7) >> 4;
                    err_cur[(col + 1) * 3 + 1] += (eg * 7) >> 4;
                    err_cur[(col + 1) * 3 + 2] += (eb * 7) >> 4;
                }
                if (col - 1 >= 0) {
                    err_next[(col - 1) * 3 + 0] += (er * 3) >> 4;
                    err_next[(col - 1) * 3 + 1] += (eg * 3) >> 4;
                    err_next[(col - 1) * 3 + 2] += (eb * 3) >> 4;
                }
                err_next[col * 3 + 0] += (er * 5) >> 4;
                err_next[col * 3 + 1] += (eg * 5) >> 4;
                err_next[col * 3 + 2] += (eb * 5) >> 4;
                if (col + 1 < src_w) {
                    err_next[(col + 1) * 3 + 0] += (er * 1) >> 4;
                    err_next[(col + 1) * 3 + 1] += (eg * 1) >> 4;
                    err_next[(col + 1) * 3 + 2] += (eb * 1) >> 4;
                }
            }
        }
        if (dither) {
            int *t = err_cur;
            err_cur = err_next;
            err_next = t;
            memset(err_next, 0, (size_t)src_w * 3 * sizeof(int));
        }
    }

    free(err_cur);
    free(err_next);
}

