/*
 * epaper.draw_image(frame, x, y, dither)
 * Quantize an image.frame (any format the image module can convert; RGB565
 * is requested internally) into the frame buffer at (x, y), clipped to the
 * panel. Call epaper.display() afterwards to flush. dither defaults to true.
 */
static int lua_epaper_draw_image(lua_State *L)
{
    lua_image_view_t view;
    esp_err_t err = lua_image_require_format(L, 1, LUA_IMAGE_FORMAT_RGB565LE, &view);
    if (err != ESP_OK) {
        return luaL_argerror(L, 1, "expected an image.frame (see image.convert)");
    }
    int x = (int)luaL_optinteger(L, 2, 0);
    int y = (int)luaL_optinteger(L, 3, 0);
    bool dither = (lua_gettop(L) < 4) ? true : (lua_toboolean(L, 4) != 0);

    epaper_fb_draw_rgb565(s_fb, x, y, view.data, view.width, view.height, dither);
    lua_image_release_view(&view);
    return 0;
}

